window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-07-16"]={"date": "2026-07-16", "dateKR": "2026년 7월 16일", "dateEN": "16 July 2026", "total": 179, "sections": [{"code": "TOP", "type": "news", "kTitle": "Section 1. 주요 뉴스", "eTitle": "Section 1. Top News", "items": [{"code": "TOP", "title": "Los Angeles and Long Beach Post Strong June as Retailers Frontload Imports", "src": "gCaptain", "date": "2026-07-15", "kSum": "로스앤젤레스항(Port of Los Angeles)이 6월에 1,002,734TEU를 처리해 118년 역사상 가장 바쁜 6월을 기록했으며, 월간 100만TEU를 넘어선 것은 이번이 세 번째다. 수입은 13% 증가한 530,558TEU였고, 롱비치항(Port of Long Beach)도 779,331TEU로 전년 대비 10.6% 늘었다. 8월로 예상되는 관세 인상에 앞서 화주들이 화물을 앞당겨 들여오는 프론트로딩이 물동량 급증의 주된 배경이다.", "eSum": "The Port of Los Angeles handled 1,002,734 TEU in June, its busiest June in 118 years and only the third time it has topped 1m TEU in a month. Imports rose 13% to 530,558 TEU, while Long Beach handled 779,331 TEU, up 10.6% year on year. The surge is driven by retailers frontloading cargo ahead of tariff increases expected in August.", "kImp": "북미 수입 물동량이 관세 일정에 맞춰 앞당겨지면서 하반기 수요 절벽 위험이 커지므로, 선복 배선과 컨테이너 장비 재배치 계획을 조기에 재검토해야 한다. 양 항만이 체선 없이 처리되고 있다는 점은 현시점 기항 스케줄 신뢰성이 유지되고 있음을 뜻한다.", "eImp": "With North American import volumes pulled forward around tariff deadlines, ship managers should revisit deployment and equipment repositioning plans early given the risk of a demand cliff later in the year. Both ports report fluid operations with no vessel backlogs, so port call reliability currently holds.", "url": "https://gcaptain.com/los-angeles-and-long-beach-post-strong-june-as-retailers-frontload-imports/"}, {"code": "TOP", "title": "White House Weighs Jones Act Waiver Extension As Hormuz Conflict Reignites", "src": "gCaptain", "date": "2026-07-15", "kSum": "트럼프 행정부가 존스법(Jones Act) 면제의 세 번째 연장을 검토 중이며, 외국적선의 미국 국내 항간 운송 구간을 제한하는 지리적 조건이 붙을 수 있다. 백악관과 에너지·교통·내무부 수장들이 이번 주 회동했고, 현행 면제는 8월 16일 만료된다. 미국 원유는 배럴당 약 80달러 수준이며 전략비축유(SPR)는 1983년 이후 최저치다.", "eSum": "The Trump administration is weighing a third extension of the Jones Act waiver, possibly with geographic restrictions on where foreign-flagged vessels may carry goods between US ports. The White House and the heads of the Energy, Transportation and Interior departments met this week, with the current waiver expiring on August 16. Domestic crude sits near $80 a barrel and the Strategic Petroleum Reserve is at its lowest level since 1983.", "kImp": "면제 연장 여부와 지리적 제한 조건은 미국 연안 유조선 시장의 수요와 용선료를 직접 좌우하므로, 미국 관련 배선을 가진 선사는 8월 16일 시한을 기준으로 시나리오를 준비해야 한다. 외국적선의 국내 운송 허용 범위 변화는 컴플라이언스 리스크로도 이어진다.", "eImp": "Whether the waiver is extended and on what geographic terms directly drives US coastwise tanker demand and charter rates, so operators with US trades should plan scenarios around the August 16 deadline. Changes to what foreign-flag tonnage may legally carry domestically also carry compliance exposure.", "url": "https://gcaptain.com/white-house-weighs-jones-act-waiver-extension-as-hormuz-conflict-reignites/"}, {"code": "TOP", "title": "Supertankers Increasingly Bear Brunt in Hormuz Ship Attacks", "src": "gCaptain", "date": "2026-07-15", "kSum": "6월 평화협정이 무산된 이후 상선 대상 공격 9건 중 5건이 VLCC를 겨냥한 것으로, 블룸버그(Bloomberg)가 국제해사기구(IMO) 보고 자료를 집계해 전했다. 협정 이전 전시 중 피해를 입은 상선 48척 가운데 VLCC는 9척이었다. IMO는 초대형 유조선 5척 중 4척이 오만 앞바다에서 손상됐다고 밝혔으며, 사무총장은 수요일 선박들이 계속 호르무즈 항행을 피해야 한다고 말했다.", "eSum": "Since the shelved June peace pact, five of nine attacks on commercial ships targeted VLCCs, according to Bloomberg data compiled from IMO reporting. Before the pact, nine of the 48 commercial ships damaged during wartime were VLCCs. The IMO says four of the five supertankers were damaged off the coast of Oman, and its secretary general said on Wednesday that ships should continue to avoid navigating Hormuz.", "kImp": "공격 표적이 초대형 유조선으로 옮겨가고 있어 VLCC 운항 선사는 전쟁위험보험료 급등과 선원 안전 리스크를 즉시 재산정해야 한다. IMO의 호르무즈 회피 권고가 유지되는 한 우회 항로에 따른 항해일수와 연료비 증가를 반영한 배선 계획이 필요하다.", "eImp": "With attacks shifting onto supertankers, VLCC operators must immediately reprice war risk premiums and reassess crew safety exposure. While the IMO's advice to avoid Hormuz stands, deployment plans need to absorb the extra voyage days and bunker costs of rerouting.", "url": "https://gcaptain.com/supertankers-increasingly-bear-brunt-in-hormuz-ship-attacks/"}, {"code": "TOP", "title": "Toxic Spill Shuts Down Two Container Terminals at Port of Antwerp", "src": "The Maritime Executive", "date": "2026-07-15", "kSum": "안트베르펜(Antwerp) 되르간크 독에 접안 중이던 컨테이너선 MSC 미아 서머 II(MSC Mia Summer II)에서 불화수소산이 누출돼 150명 이상이 노출 위험에 처했다. 28명이 심각한 흡입 증상으로 병원에 이송됐고 이 중 1명은 중환자실에 입원했다. 항만은 킬드레흐트 갑문 일대와 되르간크 독 전역에 차단·대피 계획을 발동했으며, DP월드 안트베르펜 게이트웨이(DP World Antwerp Gateway)는 수요일 오후 재개했으나 MPET 터미널 폐쇄는 유지됐다. 벨기에 검찰은 형사 수사에 착수했다.", "eSum": "A container aboard the boxship MSC Mia Summer II began leaking hydrofluoric acid alongside at Antwerp's Deurganck Dock, potentially exposing more than 150 people. Twenty-eight people developed serious HF inhalation symptoms and were hospitalized, one in intensive care. The port activated cordon and evacuation plans across the Kieldrecht Lock complex and all of Deurganck Dock; DP World Antwerp Gateway reopened Wednesday afternoon while MPET remained closed. Belgian prosecutors have opened a criminal inquiry.", "kImp": "위험물 컨테이너의 오신고나 부실 적재가 대형 항만을 마비시키고 형사 책임으로까지 이어질 수 있음을 보여주는 사례로, 위험물 신고 검증과 적재 절차 점검이 시급하다. 안트베르펜 기항선은 터미널 부분 폐쇄에 따른 지연과 스케줄 영향을 확인해야 한다.", "eImp": "The incident shows how a misdeclared or poorly stowed dangerous-goods container can paralyse a major port and trigger criminal liability, making DG declaration verification and stowage procedures an urgent review item. Vessels calling Antwerp should check delays arising from the partial terminal closure.", "url": "https://maritime-executive.com/article/toxic-spill-shuts-down-two-container-terminals-at-port-of-antwerp"}, {"code": "TOP", "title": "Video: U.S. Disables Iran-Linked Tanker With Hellfire Missiles", "src": "The Maritime Executive", "date": "2026-07-15", "kSum": "7월 14일 이란 항만에 대한 해상 봉쇄가 재개된 이후 첫 집행 조치로, 미군 항공기가 공선 상태로 카그섬에 접근하던 유조선 벨마(Belma, IMO 9289491, 16만dwt, 2005년 건조)를 요격했다. 수차례 경고를 무시하자 미 중부사령부(CENTCOM)는 단거리 헬파이어(Hellfire) 미사일로 연돌을 타격해 선박을 무력화했다. 에콰시스(Equasis) 자료상 이 선박은 UAE 자유무역지대 운항사를 둔 위장 선적으로, 전형적인 그림자 선단 구조를 보인다. CENTCOM은 첫 24시간 동안 다른 2척은 무력 사용 없이 회항시켰다.", "eSum": "In the first enforcement action since the naval blockade on Iran's seaports resumed on July 14, a US aircraft intercepted the tanker Belma (IMO 9289491, 160,000 dwt, built 2005) as she approached Kharg Island in ballast. After she ignored multiple warnings, CENTCOM disabled her with short-range Hellfire missiles fired at the stack. Per Equasis she is false-flagged with a UAE free-zone operator, a typical shadow-fleet arrangement. CENTCOM also turned away two other noncompliant vessels without using force in the first 24 hours.", "kImp": "봉쇄 집행이 실제 무력 행사로 이어진 만큼 이란 관련 화물과 선적 이력에 대한 실사 수준을 즉시 강화해야 하며, 그림자 선단과의 우발적 연계는 물리적 위험까지 수반한다. 페르시아만 배선 시 선적·소유구조 검증과 항로 회피 판단이 핵심이다.", "eImp": "With blockade enforcement now involving live kinetic action, due diligence on Iran-linked cargoes and vessel histories must be tightened immediately, as any inadvertent shadow-fleet association now carries physical risk. For Gulf deployments, flag and ownership verification plus routing avoidance decisions are critical.", "url": "https://maritime-executive.com/article/video-u-s-disables-iran-linked-tanker-with-hellfire-missiles"}, {"code": "TOP", "title": "Ukraine's ship drone strike tally reaches 136 in 10 days", "src": "Seatrade Maritime News", "date": "2026-07-15", "kSum": "우크라이나 무인체계군이 흑해와 아조프해에서 최근 10일간 러시아 연계 선박 136척을 타격했다. 사령관 로베르트 '마디아르' 브로우디(Robert 'Madyar' Brovdi)에 따르면 7월 6~14일 아조프해에서 116척을 공격했고, 7월 15일 흑해에서 유조선 17척, 가스선 2척, 예인선 1척 등 20척을 추가 타격했다. 러시아의 보복으로 오데사(Odesa)에서 7월 13일 상선 화재로 선원 5명이 사망했고, 14일에는 마셜제도 선적선 공격으로 3명이 숨졌다.", "eSum": "Ukraine's Unmanned Systems Forces have struck 136 Russia-linked vessels in the Black Sea and Sea of Azov over the past 10 days. Commander Robert 'Madyar' Brovdi said 116 ships were hit in the Sea of Azov from 6-14 July, followed by 20 attacks in the Black Sea on July 15 including 17 oil tankers, two gas tankers and a tug. In retaliation, a Russian attack on a commercial vessel at Odesa on 13 July killed five seafarers, and three more died in a UAV attack on a Marshall Islands-flagged ship on 14 July.", "kImp": "돈-아조프 수로와 케르치 해협이 폐쇄되며 곡물 수출 회랑이 마비돼 흑해 배선의 실행 가능성 자체를 재검토해야 한다. 일부 드론이 선교를 직접 겨냥하는 전술로 전환해 선원 생명 위험이 크게 높아진 점이 가장 중대한 변화다.", "eImp": "Closure of the Don-Azov Channel and the Kerch Strait has paralysed the grain export corridor, forcing a rethink of whether Black Sea deployment is viable at all. Most critically, some drone operators have shifted to aiming at vessel bridges, sharply raising the threat to seafarers' lives.", "url": "https://www.seatrade-maritime.com/security/ukraine-s-ship-drone-strike-tally-reaches-136-in-10-days"}]}, {"code": "ACC", "type": "accident", "kTitle": "Section 2. 해양사고", "eTitle": "Section 2. Accidents", "items": [{"code": "ACC", "title": "Historic passenger vessel Juno runs aground in Trosa archipelago, 57 aboard evacuated", "src": "SVT Nyheter", "date": "2026-07-15", "kSum": "1874년 건조된 세계 최고령 등록 유람선 유노(Juno)호가 2026년 7월 15일 스웨덴 쇠데텔리에(Södertälje)에서 예테보리(Gothenburg)로 항해 중 트로사(Trosa) 군도에서 좌초했다. 승객 46명과 승무원 11명 총 57명이 승선하고 있었으며, 22시경 소형 보트를 이용해 트로사 육상으로 대피시켰다. 부상자는 보고되지 않았다.", "eSum": "Juno, built in 1874 and the world's oldest registered overnight cruise ship, ran aground in Sweden's Trosa archipelago on 15 July 2026 while en route from Södertälje to Gothenburg. She had 46 passengers and 11 crew aboard. Evacuation to shore at Trosa by small boats began around 22:00; no injuries were reported.", "kCause": "공식 원인은 미발표. 협수로 항해 중 항로 이탈 또는 견시·조타 오류로 인한 좌초로 추정(presumed).", "eCause": "No official cause released. Presumed track deviation or helm/lookout error while navigating a narrow archipelago channel (presumed).", "kLes": "협수로 통항 시 통과계획(passage plan)상 어보트 포인트와 최소안전수심을 명확히 하고, 야간 견시 인원 보강 및 ECDIS 안전등심선 경보 설정을 확인할 것. 여객선은 좌초 즉시 인원 점검·대피 준비를 병행해야 한다.", "eLes": "For narrow-channel transits, define abort points and minimum safe depth in the passage plan, reinforce night lookout manning, and verify ECDIS safety contour/alarm settings. Passenger ships should run headcount and evacuation preparation in parallel immediately after grounding.", "url": "https://www.svt.se/nyheter/lokalt/sormland/kanalbat-pa-grund-utanfor-trosa"}, {"code": "ACC", "title": "Two more cargo ships hit off Odesa; captain killed and three crew injured", "src": "Meduza", "date": "2026-07-15", "kSum": "2026년 7월 15일 러시아군의 공격으로 우크라이나 오데사(Odesa) 앞바다에서 화물선 2척이 추가로 피격됐다. 이 공격으로 선장 1명이 사망하고 승무원 3명이 부상했다. 흑해 곡물·비료 수출 항로를 오가던 외국적 상선이 연속 표적이 되고 있다.", "eSum": "Two more cargo ships were struck off Odesa, Ukraine, on 15 July 2026 in Russian strikes. A captain was killed and three crew members were injured. Foreign-flagged merchant ships serving Black Sea grain and fertiliser export routes are being hit repeatedly.", "kCause": "공격에 의한 피격(적대행위). 항해상 과실이 아닌 외부 무력 공격이 원인.", "eCause": "Hostile attack. Cause is external armed action, not a navigational fault.", "kLes": "흑해 기항 시 항내 체류시간 최소화, 야간 하역 지양, 거주구 방호·대피구역(citadel) 지정, 선원 헬멧·방탄조끼 비치, 즉시 이탈 가능한 계류 방식 채택. 선원에게는 사전 브리핑과 거부권을 보장할 것.", "eLes": "For Black Sea calls: minimise port stay, avoid night cargo work, designate a hardened muster/citadel area away from the accommodation, provide helmets and ballistic vests, and use quick-release mooring so the ship can sail at short notice. Brief crew in advance and preserve their right to refuse.", "url": "https://meduza.io/en/news/2026/07/15/russian-forces-hit-two-more-cargo-ships-off-odesa-killing-a-captain-and-injuring-three-crew-members"}, {"code": "ACC", "title": "23 crew rescued after bulk carrier collision near Iran's Qeshm Island", "src": "Iran International", "date": "2026-07-14", "kSum": "2026년 7월 14일 이른 시각 이란 케슈름(Qeshm)섬 북쪽 해역에서 벌크선 1척이 다른 선박과 충돌했다. 충돌로 한 척이 침수되면서 긴급 퇴선이 이뤄졌고, 승무원 23명 전원이 구조돼 케슈름섬으로 안전하게 이송됐다. 사망자는 보고되지 않았다.", "eSum": "A bulk carrier collided with another vessel north of Iran's Qeshm Island in the early hours of 14 July 2026. One ship began taking on water, prompting an emergency evacuation. All 23 crew were rescued and transferred safely to Qeshm Island; no fatalities were reported.", "kCause": "공식 조사 결과 미발표. 통항 밀집 수역에서의 견시 부족 또는 COLREG 상 피항 동작 지연으로 인한 충돌로 추정(presumed).", "eCause": "No official findings released. Presumed inadequate lookout or delayed COLREG collision-avoidance action in congested waters (presumed).", "kLes": "호르무즈 접근 수역 통항 시 견시 인원 보강, 레이더 CPA/TCPA 경보 활성화 상태 확인, 조기·명확한 피항 동작 시행. 충돌 후에는 즉시 수밀문 폐쇄와 침수 구획 확인, 퇴선 준비를 병행할 것.", "eLes": "When transiting the Hormuz approaches, reinforce lookout manning, confirm radar CPA/TCPA alarms are enabled (not muted), and take early, substantial avoiding action. After collision, close watertight doors, assess flooded compartments, and prepare for abandonment simultaneously.", "url": "https://www.iranintl.com/en/202607148749"}, {"code": "ACC", "title": "Fire aboard US Ready Reserve Force ship Charles L. Gillard in Baltimore Harbor", "src": "USNI News", "date": "2026-07-14", "kSum": "2026년 7월 13일 미국 볼티모어항에 계류 중이던 예비선단(Ready Reserve Force) 소속 화물선 찰스 L. 길라드(Charles L. Gillard)호에서 화재가 발생했다. 볼티모어시 소방국이 11시경 현장 도착 시 구명정 2척 부근이 전소 상태로 타고 있었다. 1972년 건조된 이 선박은 2023년 해군 등록에서 말소돼 미국해사청(MARAD)으로 이관된 대형 고속 RO-RO선이다.", "eSum": "A fire broke out aboard Charles L. Gillard, a Ready Reserve Force cargo ship laid up in Baltimore, on 13 July 2026. Baltimore City Fire Department arrived at 1100 to find a fully involved fire in the area of two lifeboats. Built in 1972, the LMSR was stricken from the Naval Vessel Register in 2023 and transferred to MARAD.", "kCause": "공식 원인 미발표. 구명정 구역에서 발화한 점으로 미루어 열작업 또는 전기 계통 결함이 원인일 가능성이 있음(추정, presumed).", "eCause": "No official cause released. Given the point of origin at the lifeboat area, hot work or an electrical fault is a plausible cause (presumed).", "kLes": "계선 선박에 대해 무인 시간대 화재감지·경보 원격 감시를 유지하고, 열작업 허가서(hot work permit)와 화재감시원(fire watch) 배치를 엄격히 적용할 것. 구명정 구역 주변 가연물(도료·유압유·목재 받침) 제거를 정기 점검 항목으로 포함해야 한다.", "eLes": "Maintain remote fire detection/alarm monitoring on laid-up ships during unmanned periods, and enforce hot-work permits with a dedicated fire watch and post-work re-inspection. Add removal of combustibles around lifeboat stations (paint, hydraulic oil, timber cradles) to the routine inspection checklist.", "url": "https://news.usni.org/2026/07/14/marad-ship-suffers-fire-in-baltimore"}, {"code": "ACC", "title": "Russian drone strike sets bulk carrier Arosa ablaze at Chornomorsk; crew killed and injured", "src": "Kyiv Post", "date": "2026-07-13", "kSum": "2026년 7월 13일 우크라이나 초르노모르스크(Chornomorsk)항에서 광물비료를 양하 중이던 벌커 아로사(Arosa)호가 러시아 드론에 피격됐다. 거주구(superstructure)에 명중해 화재가 발생했으며, 승무원 다수가 사망하고 여러 명이 부상해 병원으로 후송됐다. 사상자 수는 보도별로 차이가 있다.", "eSum": "The bulk carrier Arosa was struck by a Russian drone at the port of Chornomorsk on 13 July 2026 while discharging mineral fertiliser. The drone hit the superstructure and started a fire; crew members were killed and several others were hospitalised. Casualty figures vary between reports.", "kCause": "드론에 의한 의도적 공격(적대행위). 항해·기관상 과실 아님.", "eCause": "Deliberate drone attack (hostile action). Not a navigational or machinery failure.", "kLes": "흑해 항 기항 시 하역 중 거주구 내 인원을 최소화하고, 선체 저층·기관실 반대측에 대피 구역을 지정할 것. 소방 장비를 갑판에 사전 전개하고, 항내 공습경보 수신 체계와 즉시 대피 훈련을 계획에 포함해야 한다.", "eLes": "During Black Sea port calls, minimise personnel in the accommodation while discharging and designate a protected muster area low in the hull away from the engine room. Pre-deploy firefighting equipment on deck, connect to the port's air-raid warning system, and drill immediate shelter response.", "url": "https://www.kyivpost.com/post/78672"}, {"code": "ACC", "title": "15 crew rescued after cargo ship collision off Douala, Cameroon", "src": "Xinhua", "date": "2026-07-13", "kSum": "2026년 7월 12일(일) 이른 시각 카메룬 최대 항구도시 두알라(Douala) 인근에서 출항 중이던 시 아너(MV Sea Honor)호와 입항 중이던 블랙 라이노(MV Black Rhino)호가 충돌했다. 화물선에 타고 있던 승무원 15명 전원이 구조됐고 인명 피해는 없었다. 예비 조사 결과 블랙 라이노호의 조타 제어 상실이 충돌의 유력한 원인으로 지목됐다.", "eSum": "The outbound MV Sea Honor and the inbound MV Black Rhino collided near Douala, Cameroon's main port city, in the early hours of Sunday 12 July 2026. All 15 crew aboard the cargo ship were rescued and no casualties were reported. Preliminary findings point to a loss of steering control aboard MV Black Rhino as the likely cause.", "kCause": "예비 조사상 블랙 라이노호의 조타 제어 상실이 유력한 원인으로 지목됨(당국 발표 기준, 최종 조사 진행 중).", "eCause": "Preliminary findings indicate loss of steering control aboard MV Black Rhino as the likely cause (per authorities; final investigation ongoing).", "kLes": "입항 12시간 전 조타기 시험을 실제로 시행하고 기록할 것(SOLAS V/26). 비상조타 전환 훈련을 3개월마다 실시하고, 조타실 백업 제어기에 명확한 라벨을 부착하며 전 항해사가 전환 절차를 숙지하도록 할 것.", "eLes": "Actually carry out and record the steering gear test within 12 hours before arrival (SOLAS V/26). Run emergency steering changeover drills every three months, label backup steering controls clearly on the bridge, and ensure every watchkeeper can execute the changeover unaided.", "url": "https://english.news.cn/africa/20260713/c2f0b0d7963843f68ffc960b7d623c15/c.html"}, {"code": "ACC", "title": "One Indian national missing after attack on vessel GFS Galaxy off Oman", "src": "gCaptain", "date": "2026-07-12", "kSum": "2026년 7월 12일 오만(Oman) 앞바다에서 상선 GFS 갤럭시(GFS Galaxy)호가 공격을 받았다. 승선 중이던 인도 국적 선원 11명 중 10명이 구조됐으나 1명은 실종 상태로 보고됐다. 호르무즈 해협 일대에서 상선 공격이 이어지는 가운데 발생했다.", "eSum": "The commercial vessel GFS Galaxy was attacked off the coast of Oman on 12 July 2026. Of the 11 Indian nationals aboard, 10 were rescued while one remains missing. The incident came amid a series of attacks on merchant shipping around the Strait of Hormuz.", "kCause": "외부 공격에 의한 피격(적대행위)으로 보고됨. 공격 주체·수단에 대한 공식 확인은 진행 중.", "eCause": "Reported as an external attack (hostile action). Official confirmation of the attacker and the weapon used is pending.", "kLes": "고위험 수역(HRA) 통항 전 UKMTO/MSCHOA 신고, 통항 속력 증속, 야간 통항 지양, 거주구 방호 및 citadel 준비를 시행할 것. 퇴선 시 구명뗏목별 인원 명부와 개인용 위치발신기(PLB) 지급으로 실종자 발생을 최소화해야 한다.", "eLes": "Before transiting a high-risk area, report to UKMTO/MSCHOA, increase transit speed, avoid night passage, and prepare accommodation hardening and a citadel. To reduce the chance of a missing seafarer, maintain a raft-by-raft muster list and issue personal locator beacons before abandonment.", "url": "https://gcaptain.com/one-indian-national-missing-after-attack-on-vessel-off-oman/"}, {"code": "ACC", "title": "Fishing vessel Hustler sinks off Ocean Shores, Washington; two crew rescued", "src": "The Astorian", "date": "2026-07-12", "kSum": "2026년 7월 9일 정오경 미국 워싱턴주 오션 쇼어스(Ocean Shores) 서쪽 약 4마일 해상에서 48피트 어선 허슬러(F/V Hustler)호가 침몰했다. 승선 중이던 승무원 2명은 모두 구조됐다. 인명 피해는 없었다.", "eSum": "The 48-foot fishing vessel F/V Hustler sank about four miles west of Ocean Shores, Washington, at around noon on 9 July 2026. Both crew members aboard were rescued. No casualties were reported.", "kCause": "공식 원인 미발표. 선체 파공 또는 밸브·시체스트 등 선저 관통부를 통한 급속 침수 가능성이 있음(추정, presumed).", "eCause": "No official cause released. Rapid flooding through a hull breach or a through-hull fitting/sea valve failure is plausible (presumed).", "kLes": "선저 관통부·시체스트·빌지 경보를 출항 전 점검하고, 조업 중 구명조끼 상시 착용과 EPIRB 자동 이탈식 설치를 시행할 것. 침수 초기 신속한 조난 통보가 이번 전원 구조의 핵심 요인으로 판단된다.", "eLes": "Check through-hull fittings, sea chests, and bilge alarms before departure; enforce continuous lifejacket wear while working and fit a float-free EPIRB. Prompt distress alerting in the early stage of flooding appears to be the decisive factor in both crew surviving here.", "url": "https://dailyastorian.com/2026/07/12/fishing-vessel-sank-crew-rescued/"}, {"code": "ACC", "title": "ATSB investigation: mixed cargo vessel loses steering in Bass Strait after linkage arm works loose", "src": "SAFETY4SEA", "date": "2026-07-08", "kSum": "호주교통안전국(ATSB)은 2026년 7월 8일 배스 해협(Bass Strait) 운항 화물선의 조타 상실 사고 조사보고서를 발표했다. 2025년 7월 23일 태즈메이니아 브리드포트(Bridport)~레이디 배런(Lady Barron) 간 항해 중 자동조타 장치의 타각 피드백이 상실되면서 양현 타가 좌현 최대각으로 고착돼 선박이 제어 불능으로 좌선회했다. 인명 피해는 없었으나 8시간 넘게 조타 불능 상태가 지속됐다.", "eSum": "The ATSB released its investigation report on 8 July 2026 into a loss of steering aboard a mixed cargo vessel in Bass Strait. On 23 July 2025, transiting between Bridport and Lady Barron, Tasmania, a rudder angle feedback failure in the autopilot locked both rudders hard to port, causing an uncontrolled turn. No injuries resulted, but the ship was without steering for more than eight hours.", "kCause": "ATSB 조사 결과: 연결 암(linkage arm)이 헐거워지면서 자동조타 장치로의 타각 피드백이 상실돼 자동조타와 추종식 수동조타가 모두 사용 불가 상태가 됨. 선장이 조타실의 토글식 조타 제어기 사용법에 익숙하지 않아 조타를 회복하지 못함.", "eCause": "ATSB finding: a loose linkage arm caused loss of rudder feedback to the autopilot, so neither autopilot nor follow-up manual steering was available. The master was unfamiliar with the bridge toggle (non-follow-up) steering controls and could not regain steering.", "kLes": "ATSB는 신규 선원 인수인계 교육이 백업 제어 시스템 사용법을 충분히 다루지 않았고 조타실 제어기에 라벨이 없었다고 지적했다. 조타실 모든 제어기에 명확한 라벨을 부착하고, 비추종식(NFU) 조타 전환 훈련을 실선에서 정기 시행하며, 조타 계통 연결부의 풀림 점검을 계획정비(PMS) 항목에 포함할 것.", "eLes": "The ATSB found that induction training for new personnel did not adequately cover the backup control system and that bridge controls were unlabelled. Label all bridge steering controls clearly, drill non-follow-up steering changeover on the actual equipment at regular intervals, and add checks for loosening of steering linkage fasteners to the planned maintenance system.", "url": "https://safety4sea.com/atsb-investigation-mixed-cargo-vessel-loses-steering/"}, {"code": "ACC", "title": "LNG tanker Al Rekayyat at risk of exploding after two vessels struck near Strait of Hormuz", "src": "Insurance Journal", "date": "2026-07-07", "kSum": "2026년 7월 초 호르무즈 해협 인근에서 선박 2척이 피격된 가운데, LNG 운반선 알 레카야트(Al Rekayyat)호가 좌현에 피격돼 기관실 화재가 발생했으며 폭발 위험 상태에 놓였다. 2026년 7월 7일 보도 기준으로 상황이 전해졌다. LNG 화물 특성상 화재 확산 시 대형 재난 우려가 제기됐다.", "eSum": "In early July 2026, amid strikes on two vessels near the Strait of Hormuz, the LNG tanker Al Rekayyat was hit on her port side and suffered an engine room fire, leaving her at risk of exploding, as reported on 7 July 2026. Given the LNG cargo, concerns were raised about a major escalation if the fire spread.", "kCause": "외부 공격에 의한 좌현 피격 및 그에 따른 기관실 화재(적대행위). 기관 결함이나 운항 과실이 아님.", "eCause": "External attack causing a port-side hit and consequent engine room fire (hostile action). Not machinery failure or operational error.", "kLes": "가스 운반선의 고위험 수역 통항은 원칙적으로 회피하되, 불가피할 경우 화물 탱크 살수 시스템 가압 대기, 기관실 고정식 소화설비 즉시 방출 가능 상태 유지, 긴급 이탈 항로 사전 설정이 필요하다. 인접 통항 선박에 대한 광역 경보 전파 체계도 함께 검토할 것.", "eLes": "Gas carriers should avoid high-risk area transits as a matter of policy; where unavoidable, keep the cargo tank water-spray system pressurised and on standby, maintain the engine room fixed firefighting system ready for immediate release, and pre-plan an escape route. Broad-area warning dissemination to nearby traffic should also be considered.", "url": "https://www.insurancejournal.com/news/international/2026/07/07/876503.htm"}]}, {"code": "PSC", "type": "news", "kTitle": "Section 3. 항만국통제", "eTitle": "Section 3. Port State Control", "items": [{"code": "PSC", "title": "Paris MoU adopts 2025 flag and RO performance lists, effective 1 July 2026", "src": "Paris MoU", "date": "2026-07-01", "kSum": "파리 MoU(Paris MoU) 위원회는 제59차 회의에서 2025년 점검 결과를 승인하고 기국 및 인정단체(RO)에 대한 새로운 성과 목록을 채택했다. 백색·회색·흑색(WGB) 목록은 3년 누적 점검·억류 실적을 기준으로 산정되며, 해당 기간 최소 30회 이상 점검을 받은 기국에만 적용된다. 새 목록은 2026년 7월 1일부터 적용된다.", "eSum": "The Paris MoU Committee approved the 2025 inspection results at its 59th meeting and adopted new performance lists for flag States and Recognized Organizations. The White, Grey and Black (WGB) list is based on total inspections and detentions over a rolling three-year period for flags with at least 30 inspections. The new lists apply from 1 July 2026.", "kImp": "기국의 WGB 등급은 선박위험프로파일(Ship Risk Profile)에 직접 반영되어 점검 주기와 강도를 좌우한다. 선박관리자는 관리 선대의 기국·RO 등급 변동을 즉시 확인해 유럽 기항 시 점검 빈도 증가 여부를 재산정해야 한다.", "eImp": "A flag's WGB ranking feeds directly into the Ship Risk Profile, driving inspection frequency and intensity. Ship managers should immediately check whether their fleet's flag or RO ranking has shifted and recalculate expected inspection exposure for European calls.", "url": "https://parismou.org/2026/07/2025-performance-lists-paris-mou"}, {"code": "PSC", "title": "Rising detention rates and recurring areas of concern in Paris MoU Annual Report 2025", "src": "IIMS", "date": "2026-07-03", "kSum": "파리 MoU(Paris MoU) 2025년 연차보고서는 16,474회 점검 중 9,879건에서 결함이 발견됐고 억류 688건, 입항거부(ban) 19건을 기록했다고 밝혔다. 억류율은 2024년 4.03%에서 2025년 4.18%로 상승했다. 주요 결함은 SOLAS 제II-2장 소방안전 16.8%, 제II-1장 11.6%, MLC Title IV 10.0% 순이었다.", "eSum": "The Paris MoU Annual Report 2025 records 16,474 inspections with deficiencies found in 9,879, alongside 688 detentions and 19 bans. The detention rate rose to 4.18% from 4.03% in 2024. Leading deficiency areas were SOLAS Chapter II-2 fire safety at 16.8%, Chapter II-1 at 11.6% and MLC Title IV at 10.0%.", "kImp": "억류율이 4년 연속 팬데믹 이전 수준을 상회한다는 것은 유럽 기항 선대의 구조적 압박을 뜻한다. 특히 MLC Title IV(선원 보건·복지) 결함 비중이 10%에 달해 기술 결함뿐 아니라 선원 거주·복지 항목까지 사전 점검 범위에 포함해야 한다.", "eImp": "Detention rates staying above pre-pandemic levels for a fourth consecutive year signals structural pressure on fleets calling Europe. With MLC Title IV deficiencies at 10%, pre-arrival self-checks must cover crew health and welfare items, not just technical defects.", "url": "https://www.iims.org.uk/rising-detention-rates-and-recurring-areas-of-concern-in-paris-mou-annual-report-2025/"}, {"code": "PSC", "title": "RISK4SEA PSI Outlook July 2026: diverging PSC enforcement trends demand segment-specific strategies", "src": "SAFETY4SEA", "date": "2026-07-07", "kSum": "리스크포씨(RISK4SEA)의 2026년 7월 PSC 스트레스 지수(PSI) 전망은 글로벌 PSC 환경이 고도로 분절돼 있음을 확인했다. 선종별 집행 강도가 서로 다른 방향으로 갈라지고 있어 선대 전체에 동일한 대응을 적용하기 어려운 국면이다. PSI는 KPI 성과 스트레스와 억류 활동 스트레스를 하나의 지표로 통합한 월간 지수다.", "eSum": "RISK4SEA's July 2026 PSC Stress Index (PSI) Outlook confirms the global Port State Control environment remains highly fragmented. Enforcement intensity is diverging by vessel segment, making a one-size-fits-all fleet response ineffective. PSI is a monthly index combining KPI performance stress and detention activity stress into a single reading.", "kImp": "선종별로 집행 강도가 갈리는 국면에서는 컨테이너선과 탱커에 동일한 준비 수준을 적용하는 것이 위험하다. 관리자는 선종·지역별 PSC 압력 신호를 분리해 점검 준비 자원을 차등 배분해야 한다.", "eImp": "When enforcement diverges by segment, applying identical readiness levels to containers and tankers is risky. Managers should separate PSC pressure signals by segment and region and allocate inspection-preparation resources accordingly.", "url": "https://safety4sea.com/cm-risk4sea-psi-outlook-july-2026-diverging-psc-enforcement-trends-demand-segment-specific-strategies/"}, {"code": "PSC", "title": "FMC Chair concerned China is weaponizing inspections of Panama-flag ships", "src": "The Maritime Executive", "date": "2026-07-08", "kSum": "미국 연방해사위원회(FMC) 신임 위원장 로라 디벨라(Laura DiBella)는 중국이 파나마 선적 선박에 대한 항만국통제 점검을 '무기화'하고 있다며 이는 FMC의 조사 권한 범위에 속한다고 밝혔다. 시정 조치 가능성도 시사했다. 억류 급증세는 정점을 지났으나 이미 바하마·마셜제도로의 선적 이전 물결을 촉발했다.", "eSum": "New FMC chair Laura DiBella said China's weaponization of port state control inspections against Panama-flagged ships falls within the FMC's remit to investigate, with remedial measures possible. The detention surge has reportedly peaked but has already triggered a wave of reflagging to the Bahamas and Marshall Islands.", "kImp": "PSC가 지정학적 도구로 활용될 경우 결함 실태와 무관하게 특정 기국 선박의 억류 위험이 급등한다. 파나마 선적 선박을 운영하는 관리자는 중국 기항 시 점검 강도 상승을 전제로 대응해야 하며, 기국 선택 자체가 운항 리스크 변수로 부상했다.", "eImp": "When PSC is used as a geopolitical instrument, detention risk for ships of a targeted flag rises regardless of actual condition. Managers running Panama-flagged tonnage should plan for heightened scrutiny at Chinese ports — flag choice itself has become an operational risk variable.", "url": "https://maritime-executive.com/article/fmc-chair-concerned-china-is-weaponizing-inspections-of-panama-flag-ships"}, {"code": "PSC", "title": "Panama flag exodus accelerates as Washington threatens probe into Beijing's crackdowns", "src": "Lloyd's List", "date": "2026-07-08", "kSum": "2026년 6월 파나마 선적에서 264척이 이탈해 5월의 180척 대비 47% 증가했다. 같은 기간 중국의 파나마 선적선 억류는 전월 대비 54% 감소했음에도 이탈은 오히려 가속됐다. 중국 선주가 최대 이탈 그룹이었으며, 이탈 선박의 50% 이상이 바하마와 마셜제도로 이전했다.", "eSum": "264 vessels left the Panama registry in June 2026, up 47% from 180 in May, even as Chinese detentions of Panama-flagged ships fell 54% month-on-month. Chinese owners were the largest reflagging group, with the Bahamas and Marshall Islands absorbing over 50% of departures.", "kImp": "억류 건수가 줄어도 선주들이 이탈하는 것은 PSC 리스크가 실적이 아닌 예측 불확실성에서 나온다는 신호다. 선박관리자는 기국 변경 시 신규 기국의 WGB 등급과 선박위험프로파일 재산정, 증서 재발급 일정까지 함께 검토해야 한다.", "eImp": "Owners leaving even as detention counts fall signals that PSC risk is driven by unpredictability, not just outcomes. Managers considering a flag change must factor in the new flag's WGB ranking, a recalculated Ship Risk Profile, and certificate re-issuance timelines.", "url": "https://www.lloydslist.com/LL1157771/Panama-flag-exodus-accelerates-as-Washington-threatens-probe-into-Beijing's-crackdowns"}, {"code": "PSC", "title": "AMSA outlines National Compliance Plan for 2026-27", "src": "SAFETY4SEA", "date": "2026-07-09", "kSum": "호주해사안전청(AMSA)이 2026-27 국가 준수 계획(National Compliance Plan)을 발표했다. 위험 기반 접근법을 통해 안전, 규정 준수, 선원 보호를 우선 과제로 설정했다. 계획은 호주 수역 내 외국적선에 대한 PSC 점검 우선순위와 중점 분야를 제시한다.", "eSum": "The Australian Maritime Safety Authority (AMSA) has published its National Compliance Plan for 2026-27. It sets out a risk-based approach prioritising safety, regulatory compliance and seafarer protection. The plan outlines PSC inspection priorities and focus areas for foreign-flagged vessels in Australian waters.", "kImp": "AMSA의 연간 준수 계획은 호주 기항 선박이 어떤 항목에서 집중 점검을 받을지 사전에 알려주는 로드맵이다. 호주 항로를 운항하는 선박관리자는 계획상 중점 분야를 자체 점검 체크리스트와 선원 교육 계획에 즉시 반영해야 한다.", "eImp": "AMSA's annual compliance plan is effectively a roadmap of what ships calling Australia will be scrutinised on. Managers on Australian trades should fold the stated focus areas into their self-inspection checklists and crew training plans right away.", "url": "https://safety4sea.com/amsa-outlines-national-compliance-plan-for-2026-27/"}, {"code": "PSC", "title": "Spain detains Turkish-owned cargo ship over crew abandonment and $68,000 in unpaid wages", "src": "Marine Insight", "date": "2026-07-10", "kSum": "스페인 해사당국은 국제운수노련(ITF) 신고를 접수한 뒤 라스팔마스(Las Palmas)에서 1989년 건조 일반화물선 레이디 미나(Lady Mina)호를 억류했다. 선원 6명에게 미지급 임금 6만 8천 달러가 있었고, 유효한 법정 증서가 없었으며 MLC 재정보증 서류는 위조로 의심됐다. 이 선박은 2026년 2월 가나에서 받은 PSC 점검에서 이미 18건의 결함이 지적된 바 있다.", "eSum": "The Spanish Maritime Authority detained the 1989-built general cargo ship Lady Mina at Las Palmas following an ITF referral. Six crew were owed USD 68,000, the vessel had no valid statutory certificates, and its MLC financial security documents appeared fraudulent. The ship had already picked up 18 deficiencies at a PSC inspection in Ghana in February 2026.", "kImp": "MLC 재정보증 위조와 임금 체불은 즉시 억류로 이어지는 대표적 사유이며, 과거 점검 이력이 다음 항만의 표적화를 촉발한다. 관리자는 MLC 보증서의 진위와 유효기간, 임금 지급 기록을 상시 검증하고, 미종결 결함이 있는 선박의 다음 기항지 리스크를 반드시 평가해야 한다.", "eImp": "Fraudulent MLC financial security and unpaid wages are classic straight-to-detention triggers, and a prior deficiency record drives targeting at the next port. Managers should continuously verify MLC certificate authenticity and validity plus wage payment records, and always assess next-port risk for vessels carrying open deficiencies.", "url": "https://www.marineinsight.com/spain-detains-turkish-owned-cargo-ship-over-crew-abandonment-and-68000-in-unpaid-wages/"}, {"code": "PSC", "title": "Sierra Leone records best-ever Paris MoU performance with 172 inspections, 10 detentions", "src": "Marine Insight", "date": "2026-07-14", "kSum": "시에라리온(Sierra Leone) 선적은 2023-2025 평가 기간 동안 172회 점검에 억류 10건, 초과계수(Excess Factor) 0.33을 기록하며 역대 최고 실적을 냈다. 이 실적은 2026년 7월 1일부터 발효되며 회색 목록(Grey List) 내에서 태국, 필리핀, 이집트, 세인트빈센트보다 상위로 올라섰다. 억류가 4건만 더 적었다면 백색 목록(White List) 진입이 가능했다.", "eSum": "Sierra Leone's flag posted 172 PSC inspections and 10 detentions over the 2023-2025 assessment period, with an Excess Factor of 0.33 — its best-ever result, effective 1 July 2026. It moved up the Grey List ahead of Thailand, the Philippines, Egypt and St Vincent. Four fewer detentions would have earned White List status.", "kImp": "소수 기국의 등급 이동은 해당 선적 선박의 점검 주기와 표적화 우선순위를 직접 바꾼다. 회색 목록 기국 선박은 24개월 내 2회 초과 억류 시 3개월 입항거부 대상이 되므로, 관리자는 기국 등급 변화가 자사 선대의 파리 MoU 노출도에 미치는 영향을 재평가해야 한다.", "eImp": "Ranking moves by smaller flags directly change inspection frequency and targeting priority for ships on that register. Grey List flagged ships face a three-month ban after more than two detentions in 24 months, so managers should reassess how flag ranking shifts alter their Paris MoU exposure.", "url": "https://www.marineinsight.com/sierra-leone-records-best-ever-paris-mou-performance-with-172-inspections-10-detentions/"}]}, {"code": "PCTC", "type": "news", "kTitle": "Section 4. 자동차운반선", "eTitle": "Section 4. PCTC / Car Carriers", "items": [{"code": "PCTC", "title": "COSCO Shipping Specialised Carriers forecasts H1 2026 net profit rise", "src": "Baird Maritime", "date": "2026-07-09", "kSum": "코스코 시핑 스페셜라이즈드 캐리어스(COSCO Shipping Specialised Carriers)는 2026년 상반기 지배주주 귀속 순이익이 12억 8천만~14억 위안(약 1억 8,823만 달러)으로 전년 동기 대비 55~70% 증가할 것으로 전망했다. 일회성 항목을 제외한 순이익도 12억 1천만~13억 4천만 위안으로 45~60% 늘어날 것으로 봤다. 회사는 2분기 수요 급증, 선복 타이트화에 따른 특수화물 운임 상승, 중국 첨단제조 수출 호조를 실적 개선 요인으로 꼽았다.", "eSum": "COSCO Shipping Specialised Carriers expects H1 2026 net profit attributable to shareholders of CNY1.28bn to CNY1.40bn ($188.23m), up 55-70% year on year. Net profit excluding non-recurring items is guided at CNY1.21bn-1.34bn, up 45-60%. The company cited a Q2 demand surge, tighter capacity lifting specialised cargo rates, and strong Chinese advanced-manufacturing exports. The figures are unaudited pending the semi-annual report for the period ending 30 June.", "kImp": "중국계 특수선·자동차선 사업자의 이익 급증은 아시아발 롤링·프로젝트 화물 수요가 여전히 강하다는 신호로, 선복 확보 경쟁과 용선료 협상력에 영향을 준다. 선박관리자는 특수화물 비중 확대에 대비해 래싱·고박 자재, 중량물 적재 검토 역량과 관련 선원 교육 수준을 점검해야 한다.", "eImp": "A sharp profit jump at a Chinese specialised/car carrier operator signals still-strong demand for Asia-origin rolling and project cargo, affecting space competition and charter negotiating leverage. Ship managers should check lashing and securing stocks, heavy-cargo stowage review capability and related crew training as the specialised cargo mix grows.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/cosco-shipping-specialised-carriers-forecasts-h1-2026-net-profit-rise"}, {"code": "PCTC", "title": "Dry Cargo Vessel News Roundup | July 15 - Asian yards focus: deliveries from China and Vietnam plus new orders", "src": "Baird Maritime", "date": "2026-07-15", "kSum": "차이나 머천츠 진링(China Merchants Jinling) 조선소가 메탄올 이중연료 PCTC 신조 시리즈의 1번선 아틱 턴(Arctic Tern)을 인도했으며, 이 선박은 유코카캐리어스(EUKOR Car Carriers)를 통해 아시아-유럽 항로에 투입되고 인도 직후 첫 메탄올 벙커링이 예정돼 있다. 같은 주에 CCCC는 중국 최대 전회전식 반잠수 크레인선 쓰항 융성(Sihang Yongsheng, 전장 110m·폭 43.8m)을 취항시켰다. 빅리프트 시핑(BigLift Shipping)과 한국 중양해운은 CY 프론티어(CY Frontier)를 명명했고, 로열 바겐보르그(Royal Wagenborg)는 중국 다진중공업에 7,400dwt급 아이스클래스 1A 다목적선 10척을 발주했다.", "eSum": "China Merchants Jinling Shipyard delivered Arctic Tern, lead ship of a new methanol dual-fuel PCTC series, to be deployed via EUKOR Car Carriers on the Asia-Europe trade with first methanol bunkering expected shortly after delivery. CCCC placed the semi-submersible crane vessel Sihang Yongsheng (110 m LOA, 43.8 m beam, 4,800 sqm deck) into service, classed by CCS as China's largest fully rotating semi-submersible crane ship. BigLift Shipping and South Korea's Chung Yang Shipping christened CY Frontier at Jing Jiang Nanyang Shipbuilding, with sister BigLift Pioneer due later this year. Royal Wagenborg ordered ten 7,400 dwt ice-class 1A multi-purpose vessels from Dajin Heavy Industry of China.", "kImp": "메탄올 이중연료 PCTC의 실제 인도와 첫 벙커링은 대체연료 자동차선 운항이 시험 단계를 넘어 상용 국면에 들어섰음을 보여준다. 선박관리자는 메탄올 취급 절차서, 저인화점 연료 대응 교육(IGF 코드), 벙커링 항만 인프라 확인을 선제적으로 준비해야 한다.", "eImp": "Actual delivery and imminent first bunkering of a methanol dual-fuel PCTC shows alternative-fuel car carrier operation moving from trial to commercial phase. Ship managers should get ahead on methanol handling procedures, low-flashpoint fuel training under the IGF Code, and verification of bunkering port infrastructure.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/dry-cargo-vessel-news-roundup-july-15-asian-yards-focus-deliveries-from-china-and-vietnam-plus-new-orders"}, {"code": "PCTC", "title": "Grimaldi presents ammonia-ready car carrier Grande Istanbul", "src": "Container News", "date": "2026-07-06", "kSum": "그리말디 그룹(Grimaldi Group)이 튀르키예 코자엘리 오토포트에서 최신 PCTC 그란데 이스탄불(Grande Istanbul)을 공식 공개했다. 이 선박은 그리말디가 발주한 17척의 차세대 암모니아 대응(ammonia-ready) PCTC 중 하나로, 최대 9,241 CEU를 적재하며 이전 세대 자동차선 대비 화물 단위당 CO2 배출을 최대 50% 줄일 수 있다. 현재 북유럽과 지중해를 잇는 유로메드(EuroMed) 서비스에 투입돼 오토포트, 보루산, 데린제, 겜릭, 하이다르파샤, 이즈미르 등 튀르키예 항만을 기항한다.", "eSum": "Grimaldi Group officially presented its latest PCTC, Grande Istanbul, at a ceremony at Autoport in Kocaeli, Turkiye. The vessel is one of 17 next-generation ammonia-ready PCTCs commissioned by Grimaldi, with capacity up to 9,241 CEU and CO2 emissions per unit of cargo cut by up to 50% versus previous-generation car carriers. She is deployed on Grimaldi's EuroMed service linking Northern Europe with the Mediterranean, calling at Autoport, Borusan, Derince, Gemlik, Haydarpasa and Izmir. Grimaldi has operated in Turkiye for almost 50 years and deploys around 20 modern ro-ro vessels and PCTCs there, representing roughly EUR1.2bn of investment.", "kImp": "암모니아 대응 표기가 붙은 선박이 실제 정기 항로에 연이어 투입되면서 선대 전환 속도가 빨라지고 있다. 선박관리자는 향후 암모니아 개조를 전제로 한 설계·자재 사양, 독성 연료 대응 안전 절차와 승무원 역량 개발 로드맵을 지금부터 마련해 두는 것이 유리하다.", "eImp": "Ammonia-ready tonnage entering scheduled services back to back shows the fleet transition accelerating. Ship managers benefit from starting now on design and material specifications premised on future ammonia conversion, plus toxic-fuel safety procedures and a crew competence roadmap.", "url": "https://container-news.com/grimaldi-presents-ammonia-ready-car-carrier-grande-istanbul/"}, {"code": "PCTC", "title": "Grimaldi takes delivery of ammonia-ready car carrier Grande Oriente", "src": "Container News", "date": "2026-07-02", "kSum": "그리말디 그룹이 차이나 머천츠 중공업 장쑤(China Merchants Heavy Industries Jiangsu)에서 건조한 12번째 암모니아 대응 PCTC 그란데 오리엔테(Grande Oriente)를 인도받았다. 전장 220m, 폭 38m, 93,145총톤, 서비스 속력 18노트에 최대 9,000 CEU를 적재하며, 이탈리아 선급 RINA로부터 암모니아 레디(Ammonia Ready) 표기를 받았다. 첫 항해는 중국 타이창에서 영국 포트버리까지 아시아-유럽 항로로, 6,200대 이상의 차량과 700 레인미터의 롤링 화물을 싣는다.", "eSum": "Grimaldi Group took delivery of Grande Oriente, its twelfth ammonia-ready PCTC, built by China Merchants Heavy Industries Jiangsu and holding RINA's Ammonia Ready notation. The vessel is 220 m long, 38 m wide, 93,145 gt, with a service speed of 18 knots and capacity up to 9,000 CEU. Her first Asia-Europe voyage runs from Taicang, China to Portbury, UK carrying more than 6,200 cars and 700 lane metres of rolling cargo. She carries a 5 MWh lithium battery system plus shore power, 2,500 sqm of solar panels, silicon hull coatings, air lubrication and a gate rudder, with Grimaldi claiming a 50% fuel consumption cut versus previous-generation car carriers; the main engine uses an exhaust gas cleaning system and SCR to hold NOx below IMO Tier III.", "kImp": "5MWh 배터리, 태양광, 공기윤활, 게이트 러더 등 다중 에너지절감장치(ESD)를 한 선박에 집약한 사례로, 실선 운항 데이터가 축적되면 유사 사양 발주가 확산될 가능성이 크다. 선박관리자는 복합 ESD 탑재선의 정비 부하 증가, 배터리·SCR 관련 예비품과 승무원 숙련도 확보를 미리 계획해야 한다.", "eImp": "Concentrating a 5 MWh battery, solar, air lubrication and a gate rudder in one ship means similar specifications will likely spread once in-service data accumulates. Ship managers should plan ahead for the higher maintenance load of multi-ESD vessels, plus battery and SCR spares and crew proficiency.", "url": "https://container-news.com/grimaldi-takes-delivery-of-ammonia-ready-car-carrier-grande-oriente/"}, {"code": "PCTC", "title": "Polaris adds tonnage from Global Car Carriers", "src": "Splash247", "date": "2026-07-07", "kSum": "폴라리스 오토라이너스(Polaris Autoliners)가 글로벌 카 캐리어스(Global Car Carriers)로부터 2,000 CEU급 피더형 자동차선 바이킹 오슬로(Viking Oslo)와 바이킹 오데사(Viking Odessa) 2척을 인수해 폴라리스 오슬로(Polaris Oslo), 폴라리스 스타(Polaris Star)로 개명했다. S&P 소식통은 2척 거래 규모를 약 4,400만 달러로 추정한다. 이번 거래로 폴라리스의 지배 선대는 자사선 5척, 용선 5척 등 총 10척으로 늘었다.", "eSum": "Polaris Autoliners acquired two 2,000 ceu feeder-size car carriers, Viking Oslo and Viking Odessa, from Global Car Carriers, renaming them Polaris Oslo and Polaris Star; S&P sources put the pair at around $44m in total. The 140 m Viking Odessa was built in 2009 and sister Viking Oslo in 2010, with both in Bermuda last month for ownership transfer and name change. The deal lifts Polaris Autoliners' controlled fleet to 10 vessels, five owned and five chartered-in, strengthening regional and shortsea operations. The sellers, formerly Gram Car Carriers, were taken over by MSC Group in 2024 and now trade as Global Car Carriers, self-described as the world's third-largest PCTC tonnage provider with 30 car carriers.", "kImp": "피더급 중고 자동차선 거래가 살아나는 것은 대형 신조 인도 확대에 따라 톤수 제공자들이 노후·소형 선박을 정리하고 있다는 신호다. 선박관리자에게는 인수 직후 선급·기국 변경, 선원 교체, SMS 이관 등 이관(takeover) 업무 수요가 늘어남을 뜻하며, 2009~2010년 건조선의 상태 검사와 개선 예산 산정이 관건이다.", "eImp": "A revived market in feeder-size secondhand car carriers signals tonnage providers offloading older, smaller ships as large newbuildings arrive. For ship managers this means more takeover work - class and flag changes, crew replacement, SMS transfer - with condition surveys and upgrade budgeting for 2009-2010 built tonnage the key issue.", "url": "https://splash247.com/polaris-adds-tonnage-from-global-car-carriers/"}, {"code": "PCTC", "title": "Hoegh Autoliners adds $300m to Asian carmaker deal", "src": "Splash247", "date": "2026-07-10", "kSum": "오슬로 상장 자동차선사 회그 오토라이너스가 아시아 주요 완성차 업체와의 기존 계약을 연장해 약 3억 달러의 추가 매출을 기대하게 됐다. 연장 계약은 2029년 12월까지이며, 확약 물량이 늘고 상업 조건이 관측 시장 운임 수준에 맞춰 갱신됐다. 이번 계약으로 중국 남부 샤오모(Xiaomo) 항이 회그의 아시아 발 서비스 기항지에 추가된다.", "eSum": "Oslo-listed car carrier operator Hoegh Autoliners extended an existing contract with a major Asian car producer, expected to add about $300m in revenue. The extension runs to December 2029 with higher committed volumes and terms updated in line with observed market rates. The deal adds Xiaomo port in southern China to Hoegh's Asia service offering. CEO Andreas Enger said it supports building contract backlog with strategically important customers; Hoegh operates around 40 vessels and makes over 2,000 port calls a year.", "kImp": "운임 조정 국면에서 2029년까지 장기 계약 백로그를 확보한 것은 선대 가동률과 캐시플로의 하방을 방어하는 조치다. 선박관리자는 확약 물량 증가와 신규 기항지 추가에 맞춰 항차 빈도, 정비 창구(maintenance window), 승선 교대 항만 계획을 재설계해야 한다.", "eImp": "Locking in contract backlog to 2029 during a rate correction defends fleet utilisation and cash flow on the downside. Ship managers should redesign voyage frequency, maintenance windows and crew-change port planning around higher committed volumes and the new port call.", "url": "https://splash247.com/hoegh-autoliners-adds-300m-to-asian-carmaker-deal/"}, {"code": "PCTC", "title": "Testing Begins for First Wing-Sail Installed on a Car Carrier", "src": "The Maritime Executive", "date": "2026-07-02", "kSum": "알파라발(Alfa Laval)과 발레니우스 라인즈(Wallenius Lines)의 합작사 오션버드(Oceanbird)가 자동차선 티란나(Tirranna, 30,000dwt·7,620대 적재)에 윙(Wing) 560 시제품 설치를 완료하고 시험에 들어갔다. 설치는 2026년 6월 21~24일 로테르담 다먼(Damen) 조선소에서 이뤄졌고, 선박은 6월 24일 출항해 7월 1일까지 항내 및 해상 인수시험을 마쳤다. 높이 46m, 폭 14m의 이 윙세일은 약 10%의 에너지 효율 개선을 목표로 하며, 자동차선 부문 최초의 윙세일 설치 사례다.", "eSum": "Oceanbird, the Alfa Laval / Wallenius Lines JV started in December 2021, completed installation of its Wing 560 prototype aboard the car carrier Tirranna (30,000 dwt, 7,620-car capacity) and began testing. Installation took place at Damen Shipyard Rotterdam between 21 and 24 June 2026; the ship departed on 24 June and harbour and sea acceptance tests were completed as of 1 July. The wing stands 46 m tall and 14 m wide and is designed to deliver around 10% energy-efficiency gains. The work is part of the EU-funded Orcelle Horizon project targeting large ro-ros drawing 50% of power from wind, with the next installation of two Wing 560s on an undisclosed vessel planned for spring 2027.", "kImp": "풍력보조추진(WAPS)이 자동차선 부문으로 확장되면서 EU ETS·FuelEU 규제 대응 수단으로 실증 데이터가 확보되기 시작했다. 선박관리자는 윙세일 탑재 시 항내 조종성, 크레인·램프 간섭, 교량 통과 높이, 구조 보강 및 정비 계획, 그리고 항해 당직자 교육 항목을 사전 검토해야 한다.", "eImp": "Wind-assisted propulsion extending into the car carrier segment starts generating in-service data as a compliance lever for EU ETS and FuelEU. Ship managers should pre-assess manoeuvrability in port, crane and ramp interference, air-draught limits, structural reinforcement and maintenance planning, and bridge-team training when fitting wing sails.", "url": "https://maritime-executive.com/article/testing-begins-for-first-wing-sail-installed-on-a-car-carrier"}, {"code": "PCTC", "title": "Port of Galveston opens new $106m cargo berth", "src": "Seatrade Maritime News", "date": "2026-07-08", "kSum": "미국 텍사스주 갤버스턴 항(Port of Galveston)의 39-40번 부두 신규 화물 선석(길이 429.7m)이 2026년 7월 2일 공식 개장했다. 첫 입항선은 발레니우스 빌헬름센(Wallenius Wilhelmsen)의 199m급 톨레도(MS Toledo)로, 브라질과 아시아에서 온 중장비 건설기계를 웨스트 포트 카고 콤플렉스에서 양하했다. 1억 600만 달러 규모의 확장 사업은 2024년 착공해 2026년 완료됐으며, 항만 운영수익과 텍사스 교통국의 3,600만 달러 보조금으로 조달됐다.", "eSum": "The Port of Galveston's new 429.7 m cargo berth at Pier 39-40 officially opened for business on 2 July 2026. Wallenius Wilhelmsen's 199 m MS Toledo was the first vessel to use it, offloading heavy construction equipment from Brazil and Asia at the West Port Cargo Complex. The $106m expansion began in 2024 and completed in 2026, enclosing two outdated slips, filling one, repaving cargo areas and demolishing a decommissioned grain elevator, growing the cargo facility from 24.2 ha to almost 36.42 ha. Funding came from port operating revenues plus a $36m Texas Department of Transportation grant; port director and CEO Rodger Rees said it is the first significant cargo investment in decades, and the port moves 3m tonnes of general and breakbulk cargo a year.", "kImp": "미국 걸프 지역의 ro-ro·브레이크벌크 선석 확충은 자동차선과 중장비 화물의 기항 선택지를 넓히고 체선 리스크를 낮춘다. 선박관리자는 신규 선석의 램프 하중, 수심, 계류 배치 등 선석 적합성 자료를 확보해 기항 계획과 항만 리스크 평가에 반영할 필요가 있다.", "eImp": "Added ro-ro and breakbulk berth capacity on the US Gulf widens port options for car carriers and heavy equipment cargo and lowers congestion risk. Ship managers should obtain berth suitability data - ramp loading, depth, mooring layout - for the new berth and fold it into call planning and port risk assessment.", "url": "https://www.seatrade-maritime.com/ports-logistics/port-of-galveston-opens-new-106m-cargo-berth"}]}, {"code": "WW", "type": "news", "kTitle": "Section 5. 발레니우스 빌헬름센", "eTitle": "Section 5. Wallenius Wilhelmsen", "items": [{"code": "WW", "title": "Wallenius Wilhelmsen takes delivery of first Shaper Class vessel, marking a new chapter in sustainable shipping", "src": "walleniuswilhelmsen.com", "date": "2026-07-09", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 셰이퍼 클래스(Shaper Class) 시리즈의 첫 선박 '아틱 턴(Arctic Tern)'을 인도받았다. 9,300 CEU급 메탄올 이중연료 PCTC로, 선대 교체 프로그램의 핵심 이정표다. 인도 직후 아시아-유럽 항로에 투입되며 현대자동차그룹과의 합작사 유코카캐리어스(EUKOR Car Carriers)를 통해 운항된다.", "eSum": "Wallenius Wilhelmsen has taken delivery of Arctic Tern, the first vessel in its Shaper Class series. The 9,300 CEU methanol dual-fuel PCTC is a key milestone in the company's fleet renewal programme. It enters the Asia-Europe trade almost immediately and will be deployed through EUKOR Car Carriers, the joint venture with Hyundai Motor Group.", "kImp": "선박관리자 입장에서 메탄올 이중연료 PCTC의 첫 상업 투입은 연료 취급 절차, 승무원 교육, 벙커링 안전관리 체계를 실증하는 사례다. 향후 13척이 추가 인도되므로 관리 표준을 조기에 정립할 필요가 있다.", "eImp": "For a ship manager, the first commercial deployment of a methanol dual-fuel PCTC is a live test of fuel-handling procedures, crew training and bunkering safety systems. With 13 more sister vessels to follow, management standards need to be established early.", "url": "https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-takes-delivery-of-first-shaper-class-vessel-marking-a-new-chapter-in-sustainable-shipping"}, {"code": "WW", "title": "Wallenius Wilhelmsen Takes Delivery of Large Methanol-Fueled Car Carrier", "src": "maritime-executive.com", "date": "2026-07-09", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 중국 초상국 진링조선소(China Merchants Jinling, 난징)에서 건조한 아틱 턴(Arctic Tern)을 인도받았다. 전장 228m, 재화중량 15,750톤, 9,300 CEU 규모의 메탄올 이중연료 자동차운반선이다. 2023년 말 발주한 6척 시리즈의 첫 호선이다.", "eSum": "Wallenius Wilhelmsen has taken delivery of Arctic Tern, built at China Merchants Jinling Shipyard in Nanjing. The vessel is 228 m long with a deadweight of 15,750 tonnes and a capacity of 9,300 CEU, running on methanol dual-fuel. It is the first of six car carriers originally ordered in late 2023.", "kImp": "중국 조선소에서 건조된 대형 메탄올 이중연료 PCTC의 인도는 아시아 신조선 품질·인도 일정 관리와 신연료 선박의 초기 운항 신뢰성 확보라는 두 가지 관리 과제를 동시에 제기한다.", "eImp": "Delivery of a large methanol dual-fuel PCTC from a Chinese yard raises two management issues at once: newbuilding quality and schedule control in Asia, and securing early operational reliability of alternative-fuel tonnage.", "url": "https://maritime-executive.com/article/wallenius-wilhelmsen-takes-delivery-of-large-methanol-fueled-car-carrier"}, {"code": "WW", "title": "Methanol-Ready Arctic Tern PCTC Joins Wallenius Wilhelmsen Fleet", "src": "marinelink.com", "date": "2026-07-10", "kSum": "메탄올 대응 PCTC 아틱 턴(Arctic Tern)이 발레니우스 빌헬름센(Wallenius Wilhelmsen) 선대에 합류했다. 이중연료 사양과 향상된 운항 효율성을 갖춰 고객의 지속가능 물류 수요에 대응한다. 셰이퍼 클래스(Shaper Class) 시리즈는 총 14척으로 확대되었다.", "eSum": "The methanol-ready PCTC Arctic Tern has joined the Wallenius Wilhelmsen fleet. With dual-fuel capability and improved operational efficiency, it addresses growing customer demand for sustainable logistics. The Shaper Class series has been expanded to 14 vessels in total.", "kImp": "선대 규모 14척으로의 확대는 메탄올 연료 공급망, 예비품 표준화, 기관부 인력 확보 계획을 선제적으로 수립해야 함을 의미한다.", "eImp": "Expansion to a 14-vessel series means methanol supply chains, spare-part standardisation and engine-department manning plans must be put in place ahead of time.", "url": "https://www.marinelink.com/news/methanolready-arctic-tern-pctc-joins-541076"}, {"code": "WW", "title": "Wallenius Wilhelmsen takes delivery of methanol dual-fuel car carrier", "src": "bairdmaritime.com", "date": "2026-07-10", "kSum": "마셜제도 선적의 아틱 턴(Arctic Tern)은 전장 228m, 폭 38m, 재화중량 15,750톤, 9,300 CEU 사양이다. 발레니우스 빌헬름센(Wallenius Wilhelmsen)과 현대자동차그룹의 합작사인 유코카캐리어스(EUKOR Car Carriers)를 통해 운항된다. 동형 13척이 추가 건조되며 이 중 5척은 9,300 CEU급, 8척은 11,700 CEU급이다.", "eSum": "The Marshall Islands-flagged Arctic Tern measures 228 m LOA with a 38 m beam, 15,750 dwt and 9,300 CEU capacity. It will be deployed through EUKOR Car Carriers, the joint venture between Wallenius Wilhelmsen and Hyundai Motor Group. Thirteen sister PCTCs will follow, comprising five 9,300 CEU and eight 11,700 CEU ships.", "kImp": "11,700 CEU급 대형선 8척이 2027년 말부터 인도되는 만큼, 터미널 접안 능력과 화물 적재 계획, 대형선 대응 인력 배치를 미리 검토해야 한다.", "eImp": "With eight 11,700 CEU vessels arriving from late 2027, terminal berthing capability, cargo stowage planning and manning for larger units need early review.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/wallenius-wilhelmsen-takes-delivery-of-methanol-dual-fuel-car-carrier"}, {"code": "WW", "title": "Wallenius Wilhelmsen dual-fuel car carrier to complete first methanol bunkering op", "src": "manifoldtimes.com", "date": "2026-07-10", "kSum": "아틱 턴(Arctic Tern)은 인도 직후 첫 메탄올 벙커링을 수행할 예정이다. 이는 발레니우스 빌헬름센(Wallenius Wilhelmsen)의 탈탄소 여정에서 또 하나의 진전이다. 선박은 재래식 VLSFO, 바이오연료, 그린 메탄올을 모두 사용할 수 있다.", "eSum": "Arctic Tern is set to complete its first methanol bunkering shortly after delivery. This marks another step in Wallenius Wilhelmsen's decarbonisation journey. The vessel can operate on conventional VLSFO, biofuel or green methanol.", "kImp": "첫 메탄올 벙커링은 벙커링 안전 절차, 항만 승인, 비상대응 계획의 실제 적용 사례로, 동종 선박을 관리하는 회사에 직접적인 참고가 된다.", "eImp": "A first methanol bunkering is a real-world test of bunkering safety procedures, port approvals and emergency response plans — directly relevant to any manager of similar tonnage.", "url": "https://www.manifoldtimes.com/news/wallenius-wilhelmsen-dual-fuel-car-carrier-to-complete-first-methanol-bunkering-op/"}, {"code": "WW", "title": "Wallenius Wilhelmsen trials Oceanbird wing sail at sea", "src": "seatrade-maritime.com", "date": "2026-07-02", "kSum": "높이 46m, 폭 14m의 틸팅식 강성 윙세일 'Wing560'이 230m급 자동차운반선 티란나(Tirranna)에 설치되었다. DNV가 6월 첫째 주 설계인증을 발급한 후 로테르담 다멘조선소(Damen Shipyard)에서 6월 21~24일 설치가 진행되었다. 항만인수시험(HAT)과 해상인수시험(SAT)이 모두 완료되었다.", "eSum": "A 46-metre tall, 14-metre wide tiltable rigid Wing560 wing sail has been installed on the 230-metre car carrier Tirranna. Installation took place at Damen Shipyard in Rotterdam between 21 and 24 June after DNV granted the design certificate in the first week of June. Harbour Acceptance and Sea Acceptance Tests have both been completed.", "kImp": "풍력보조추진장치(WAPS)를 자동차운반선에 적용한 첫 사례로, CII 및 FuelEU 대응 수단으로서 실효성 데이터가 축적된다. 갑판 구조 보강, 시야 확보, 항만 접안 제약 등 관리상 검토 항목이 명확해진다.", "eImp": "As the first WAPS installation on a car carrier, it will generate real efficacy data for CII and FuelEU compliance. It also clarifies management review items such as deck structural reinforcement, bridge visibility and port berthing constraints.", "url": "https://www.seatrade-maritime.com/sustainability/wallenius-wilhelmsen-trials-oceanbird-wing-sail-at-sea"}, {"code": "WW", "title": "Oceanbird wing sail completes first sea trial on Wallenius car carrier", "src": "splash247.com", "date": "2026-07-02", "kSum": "오션버드(Oceanbird)의 윙세일이 발레니우스(Wallenius) 자동차운반선에서 첫 해상 시운전을 완료했다. 재활용 페트병 38만 개를 사용해 제작된 강성 윙세일로 최대 10%의 연료 절감이 기대된다. 오션버드는 알파라발(Alfa Laval)과 발레니우스 라인스(Wallenius Lines)의 합작사다.", "eSum": "Oceanbird's wing sail has completed its first sea trial on a Wallenius car carrier. The rigid wing sail, made using 380,000 recycled plastic bottles, is claimed to deliver up to 10% fuel savings. Oceanbird is a joint venture between Alfa Laval and Wallenius Lines.", "kImp": "10% 연료 절감이 실증되면 자동차운반선 부문 전반에 풍력보조추진 도입이 가속될 수 있어, 선박관리사는 유지보수 및 운항 절차 표준을 미리 준비할 필요가 있다.", "eImp": "If the claimed 10% saving is proven, wind-assisted propulsion uptake across the car carrier segment could accelerate — ship managers should prepare maintenance and operating procedure standards in advance.", "url": "https://splash247.com/oceanbird-wing-sail-completes-first-sea-trial-on-wallenius-car-carrier/"}, {"code": "WW", "title": "Wallenius Wilhelmsen adds $420m to car shipping contract", "src": "splash247.com", "date": "2026-06-24", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 주요 유럽 완성차 제조사와 약 4억 2천만 달러 규모의 계약 연장을 체결했다. 3년 연장 계약은 2028년 중반부터 2031년 중반까지 적용된다. 기존 계약 잔여분 약 1억 8천만 달러를 합하면 향후 5년간 약 6억 달러의 계약 물량이 확보된다.", "eSum": "Wallenius Wilhelmsen has signed a contract extension worth about USD 420m with a major European carmaker. The three-year extension runs from mid-2028 through mid-2031. Combined with roughly USD 180m remaining on the current deal, it secures around USD 600m of contracted business over the next five years.", "kImp": "장기 계약 확보는 선대 가동률과 인력 계획의 안정성을 높인다. 계약에 저탄소 연료 사용이 포함되어 있어 연료 전환 일정과 선박 개조 계획이 상업 계약과 직접 연동된다.", "eImp": "Long-term contract cover improves stability of fleet utilisation and manning planning. Because the deal includes low-emission fuels, fuel-transition timing and vessel conversion plans are now tied directly to commercial contracts.", "url": "https://splash247.com/wallenius-wilhelmsen-adds-420m-to-car-shipping-contract/"}, {"code": "WW", "title": "Wendt promoted as Wallenius Wilhelmsen strengthens breakbulk focus", "src": "heavyliftpfi.com", "date": "2026-06-04", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 카르스텐 벤트(Carsten Wendt)를 유럽·중동·아프리카(EMEA) 산업영업 부사장으로 승진 임명했다. 회사는 산업 글로벌 세일즈 부서를 신설하며 브레이크벌크 부문 강화에 나섰다. 완성차 물량 의존도를 낮추려는 전략적 움직임으로 해석된다.", "eSum": "Wallenius Wilhelmsen has promoted Carsten Wendt to vice president, industrial sales for Europe, Middle East and Africa (EMEA). The company has formed an industrial global sales department, strengthening its focus on the breakbulk segment. The move is read as a strategic effort to reduce reliance on finished-vehicle volumes.", "kImp": "브레이크벌크·하이앤드헤비 화물 비중 확대는 적재·고박(lashing) 계획, 화물 손상 리스크, 선원 교육 요건에 직접 영향을 준다.", "eImp": "A greater share of breakbulk and high-and-heavy cargo directly affects stowage and lashing planning, cargo damage risk and crew training requirements.", "url": "https://www.heavyliftpfi.com/news/2026/06/04/wendt-promoted-as-wallenius-wilhelmsen-strengthens-breakbulk-focus/"}, {"code": "WW", "title": "Wallenius Wilhelmsen signs two-year fuel agreement with Equinor for supply of bio-methanol", "src": "walleniuswilhelmsen.com", "date": "2026-03-11", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 에퀴노르(Equinor)와 2년간의 바이오메탄올 공급 계약을 체결했다. 벙커는 제브뤼헤(Zeebrugge)와 안트베르펜(Antwerp) 항에서 2026년 말부터 공급된다. 이는 2027년부터 일부 고객에게 넷제로 엔드투엔드 파일럿 서비스를 제공하려는 목표를 뒷받침한다.", "eSum": "Wallenius Wilhelmsen has signed a two-year bio-methanol supply agreement with Equinor. Bunkers will be delivered at the ports of Zeebrugge and Antwerp, with supplies starting in late 2026. The deal supports the company's ambition to offer a net-zero end-to-end pilot service to selected customers from 2027.", "kImp": "대체연료 확보 계약은 신조선 운항 개시 시점과 맞물려야 하며, 벙커링 항만이 특정되면 항로 계획과 벙커 수급 절차를 그에 맞춰 정비해야 한다.", "eImp": "Alternative-fuel offtake must align with newbuilding entry into service; with bunkering ports now fixed, voyage planning and bunker procurement procedures must be aligned accordingly.", "url": "https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-signs-two-year-fuel-agreement-with-equinor-for-supply-of-bio-methanol"}, {"code": "WW", "title": "Wallenius Wilhelmsen secures two-year bio-methanol bunker fuel supply from Equinor", "src": "manifoldtimes.com", "date": "2026-03-12", "kSum": "에퀴노르(Equinor)가 발레니우스 빌헬름센(Wallenius Wilhelmsen)에 2년간 바이오메탄올 벙커를 공급한다. 공급은 유럽 주요 벙커링 허브인 제브뤼헤(Zeebrugge)와 안트베르펜(Antwerp)에서 이루어진다. 회사의 2040년 넷제로 목표 달성을 위한 저탄소 연료 전환의 일환이다.", "eSum": "Equinor will supply bio-methanol bunkers to Wallenius Wilhelmsen over a two-year period. Deliveries will take place at Zeebrugge and Antwerp, key European bunkering hubs. The agreement forms part of the company's transition to low-carbon fuels toward its 2040 net-zero goal.", "kImp": "바이오메탄올 벙커 품질·인증(ISCC 등) 관리와 수급 안정성은 FuelEU Maritime 준수 및 고객 배출 보고에 직결되는 관리 항목이다.", "eImp": "Quality and certification management (e.g. ISCC) of bio-methanol bunkers, plus supply reliability, feed directly into FuelEU Maritime compliance and customer emissions reporting.", "url": "https://www.manifoldtimes.com/news/wallenius-wilhelmsen-secures-two-year-bio-methanol-bunker-fuel-supply-from-equinor/"}, {"code": "WW", "title": "Wallenius Wilhelmsen begins official operations at the Gothenburg terminal", "src": "walleniuswilhelmsen.com", "date": "2026-02-02", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 스웨덴 예테보리 국제 오토·로로 터미널(GIART) 운영을 공식 개시했다. 12년 컨세션 계약에 따라 24만 제곱미터 규모 시설을 운영하며 기존 인프라 현대화에 약 600만 유로를 투자한다. 2011년부터 운영해온 로젠트 포츠 앤 터미널스(Logent Ports and Terminals)로부터 운영권을 인수했다.", "eSum": "Wallenius Wilhelmsen has officially begun operations at the Gothenburg International Auto & RoRo Terminal (GIART) in Sweden. Under a 12-year concession it operates the 240,000 sqm facility and will invest around EUR 6m in modernising existing infrastructure. It takes over from Logent Ports and Terminals, the operator since 2011.", "kImp": "북유럽 최대 차량 항만의 터미널 운영권 확보는 선박 대기시간과 하역 생산성에 대한 통제력을 높인다. 자체 터미널 운영은 항만 체류시간 단축과 화물 손상 관리에 직접 기여한다.", "eImp": "Taking over terminal operations at Scandinavia's largest vehicle port gives greater control over vessel waiting time and discharge productivity. In-house terminal operation directly supports shorter port stays and better cargo-damage management.", "url": "https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-begins-official-operations-at-the-gothenburg-terminal"}]}, {"code": "EE", "type": "news", "kTitle": "Section 6. 에너지 효율·탈탄소", "eTitle": "Section 6. Energy Efficiency", "items": [{"code": "EE", "title": "ZERO44 makes €492-a-tonne case for going beyond compliance", "src": "Splash247", "date": "2026-07-15", "kSum": "베를린 소재 탄소관리 플랫폼 제로44(ZERO44)가 백서를 통해 화석연료 1톤을 대체할 때마다 최대 492유로(562달러)의 순수익을 낼 수 있다고 분석했다. MGO를 B100 바이오디젤로 전환한 역내 항해 사례에서 연료 프리미엄 톤당 335유로에 대해 FuelEU·EU ETS 절감액 283유로가 발생하고, FuelEU 잉여분을 CO2톤당 190유로에 풀링 매각하면 544유로가 추가로 들어와 순 492유로가 남는다. 다만 규제 준수에 이미 사용한 감축분을 자발적 시장에 다시 팔 수 없다는 '추가성(additionality)' 원칙이 관건이다.", "eSum": "Berlin-based carbon management platform ZERO44 published a whitepaper arguing that emission reductions can be turned into revenue worth up to €492 ($562) per tonne of fossil fuel replaced. In a worked example swapping MGO for B100 biodiesel on an intra-EU voyage, a €335/t fuel premium is nearly offset by €283 of FuelEU and EU ETS savings, while selling the FuelEU surplus via pooling at €190/tCO2 adds €544 — leaving €492 of net revenue. The catch is additionality: a reduction already used for compliance should never be sold twice.", "kImp": "CII·EU ETS·FuelEU Maritime·자발적 탄소시장을 개별적으로 관리하면 바이오연료 프리미엄이 순수 비용으로 보이지만, 통합 관리하면 오늘 시행 중인 규정만으로도 수익화가 가능하다는 뜻이다. 선박관리자는 벙커링 시점에 해당 물량을 규제용인지 자발적 인셋팅용인지 사전 지정하고, 선주-용선자 간 FuelEU 잉여분 귀속을 용선계약에 명시적으로 반영해야 한다.", "eImp": "Managed separately, CII, EU ETS, FuelEU and the voluntary carbon market make biofuel look like pure cost; joined up, a fuel switch can be profitable under rules already in force. Ship managers should earmark bunkered volumes for either regulatory or voluntary use upfront, and pin down owner–charterer declarations on who owns the FuelEU surplus in the charter party.", "url": "https://splash247.com/zero44-makes-e492-a-tonne-case-for-going-beyond-compliance/"}, {"code": "EE", "title": "KR, HD Hyundai Complete Korea's First Ammonia Vessel Trial", "src": "MarineLink", "date": "2026-07-14", "kSum": "한국선급(KR)과 HD현대중공업(HHI)이 국내 최초 암모니아 이중연료 추진 선박의 해상 시운전을 완료했다. 이번 시운전은 해양수산부의 '녹색해운항로 구축 지원 사업'의 일환으로 진행됐으며, 암모니아 연료 추진선의 국내 운항 환경 조성을 목표로 한다.", "eSum": "Korean Register (KR) and HD Hyundai Heavy Industries (HHI) have completed a sea trial of South Korea's first ammonia dual-fuel propulsion vessel. The trial was conducted under the Ministry of Oceans and Fisheries' Green Shipping Corridor Construction Support Project, which aims to establish a domestic operating environment for ammonia-powered ships.", "kImp": "암모니아는 무탄소 연료 후보 중 가장 유력하지만 독성·연소 안정성 문제로 실증이 부족했다. 국내 선급·조선소 주도로 실선 시운전이 성사되면서 암모니아 추진선의 운항·정비 절차와 선원 교육 요건이 구체화될 전망이며, IMO 순배출제로 프레임워크 대응 옵션을 검토하는 선박관리자에게 실질적 참조 사례가 된다.", "eImp": "Ammonia is the leading zero-carbon fuel candidate but has lacked real-ship validation because of toxicity and combustion-stability concerns. A class- and yard-led sea trial moves operating, maintenance and crew-training requirements from theory toward practice, giving ship managers weighing IMO Net-Zero Framework options a concrete reference point.", "url": "https://www.marinelink.com/news/kr-hd-hyundai-complete-koreas-first-541195"}, {"code": "EE", "title": "DP World invests in Hapag-Lloyd's green shipping programme", "src": "Splash247", "date": "2026-07-14", "kSum": "DP월드(DP World)가 하팍로이드(Hapag-Lloyd)의 '십 그린(Ship Green)' 프로그램에 100만 달러를 투자해 미주 지역 고객이 폐기물 기반 바이오연료로 해상운송 탄소발자국을 줄일 수 있게 한다. 향후 4개 분기에 걸친 투자로 4,762톤의 CO2 배출 회피가 예상된다. 하팍로이드는 인증된 폐기물 기반 바이오연료가 기존 선박연료 대비 well-to-wake 기준 최소 84%의 온실가스 감축 효과가 있다고 밝혔다.", "eSum": "DP World has committed $1m to Hapag-Lloyd's Ship Green programme, letting customers in the Americas cut the carbon footprint of ocean freight using waste-based biofuels. The investment, spread over four quarters, is expected to avoid 4,762 tonnes of CO2. Hapag-Lloyd says the certified waste-based biofuels cut GHG emissions by at least 84% on a well-to-wake basis versus conventional marine fuel.", "kImp": "탄소 인셋팅(insetting)은 상쇄(offset)와 달리 운송 체인 내부에서 실제 감축을 발생시켜 화주의 Scope 3 목표에 직접 배분된다. 화주·물류사가 저탄소 운송에 프리미엄을 지불하기 시작했다는 신호로, 선박관리자는 바이오연료 수급·품질관리와 감축량 인증 추적 체계를 갖추면 신규 수익원으로 연결할 수 있다.", "eImp": "Unlike offsets, carbon insetting delivers reductions inside the transport chain and can be allocated directly to a cargo owner's scope 3 target. It signals that shippers and forwarders will pay a premium for lower-carbon transport — ship managers who can secure biofuel supply, manage quality and certify reductions can turn this into revenue.", "url": "https://splash247.com/dp-world-invests-in-hapag-lloyds-green-shipping-programme/"}, {"code": "EE", "title": "European Shipowners call for permanent ETS derogations for islands, outermost regions and ice-classed ships", "src": "SAFETY4SEA", "date": "2026-07-13", "kSum": "유럽선주협회(ECSA)가 EU 배출권거래제(ETS) 개정을 앞두고 도서지역·최외곽지역·빙급선(ice-classed ships)에 대한 적용예외를 2030년 이후에도 영구화하고 회원국 결정과 무관하게 자동 적용할 것을 EU 집행위에 요구했다. 특히 빙급선의 높은 배출량은 상업적 선택이 아니라 동절기 안전·항행 요건에 따른 것이므로 FuelEU Maritime의 동등 조항과 정합성을 맞춰야 한다고 주장했다. ECSA는 이 권고가 반영된다면 현행 EU ETS의 지리적 적용범위는 유지해도 된다는 입장이다.", "eSum": "Ahead of the upcoming EU ETS revision, ECSA has called on the Commission to make the maritime derogations for islands, outermost regions and ice-classed ships permanent beyond 2030 and to apply them automatically, without depending on Member State activation. ECSA argues higher emissions from ice-classed vessels are not a commercial choice but reflect winter safety and navigational requirements, and should be aligned with the equivalent FuelEU Maritime provision. It says the current geographical scope of the EU ETS can be maintained if these recommendations are taken on board.", "kImp": "발트해·북극권 운항 선대나 도서·최외곽 항로를 운영하는 선박관리자에게 예외조항의 영구화 여부는 배출권 구매 비용과 항로 경제성을 직접 좌우한다. 예외가 회원국 재량에 달려 있으면 국가별로 컴플라이언스 비용이 달라지므로, 개정 논의 진행 상황을 배출권 조달 계획에 반영해야 한다.", "eImp": "For managers running Baltic/Arctic tonnage or island and outermost-region trades, whether these derogations become permanent directly drives allowance purchase costs and route economics. Because activation currently depends on Member State discretion, compliance cost varies by flag state and trade — the revision timeline should feed into allowance procurement planning.", "url": "https://safety4sea.com/european-shipowners-call-for-permanent-ets-derogations-for-islands-outermost-regions-and-ice-classed-ships/"}, {"code": "EE", "title": "Hong Kong completes its largest green methanol bunkering to date", "src": "SAFETY4SEA", "date": "2026-07-13", "kSum": "벤처에너지(Venture Energy)가 중국 초상국선전해운(CM Shenzhen)이 운항하는 RoRo선에 그린 메탄올 1,000톤을 공급하며 홍콩 최대 규모의 단일 그린 메탄올 벙커링을 완료했다. 벙커링 바지선 '다칭 268(Da Qing 268)'이 작업을 수행했고, 연료는 션에너지그룹(Shenergy Group) 계열사 상하이 션지에너지가 생산했으며 시노펙 홍콩(Sinopec HK)이 지원했다.", "eSum": "Venture Energy has completed Hong Kong's largest single green methanol bunkering operation to date, supplying 1,000 tonnes to a RoRo vessel operated by China Merchants Shenzhen Shipping. The operation used the bunkering barge Da Qing 268, with green methanol produced by Shanghai Shenji Energy & Environmental Technology, an affiliate of Shenergy Group, and support from Sinopec (Hong Kong).", "kImp": "메탄올 이중연료선 발주는 늘고 있으나 실제 급유 가능 항만은 여전히 제한적이어서 배선 계획의 제약이 된다. 웨이강구(Greater Bay Area)에 그린 메탄올 공급망이 형성되면 아시아-유럽 항로 메탄올 추진선의 급유 옵션이 넓어지고, FuelEU Maritime 대응 시 아시아 측 급유 계획 수립이 수월해진다.", "eImp": "Methanol dual-fuel orders keep growing but the number of ports that can actually supply it remains a scheduling constraint. A green methanol supply chain forming in the Greater Bay Area widens bunkering options for methanol-fuelled ships on Asia–Europe trades and makes the Asian leg of FuelEU Maritime compliance planning easier.", "url": "https://safety4sea.com/hong-kong-completes-largest-green-methanol-bunkering-to-date/"}, {"code": "EE", "title": "Energy-Efficiency Measures First says DNV Maritime CEO", "src": "MarineLink", "date": "2026-07-06", "kSum": "DNV 해사부문 CEO 크리스티나 사엔스 데 산타 마리아(Cristina Saenz de Santa Maria)는 규제 변화와 지정학적 불확실성, 상업적 압박 속에서도 선사가 가장 먼저 다뤄야 할 과제는 가장 명백한 것, 즉 에너지효율 조치라고 강조했다. 다양한 신연료와 기술이 궁극적으로 2050 순배출제로를 견인하겠지만, 당장은 효율 개선이 우선이라는 취지다.", "eSum": "Cristina Saenz de Santa Maria, CEO Maritime at DNV, argues that amid regulatory shift, geopolitical uncertainty and commercial pressure, the next thing shipping companies should address is also the most obvious one: energy-efficiency measures. While a wide range of new fuels and technologies will ultimately drive shipping to net-zero by 2050, efficiency comes first.", "kImp": "IMO 순배출제로 프레임워크 채택이 지연되면서 신연료 투자 의사결정이 미뤄지는 상황에서, 선급 최고경영진이 '기다리지 말고 효율부터'라는 메시지를 낸 것이다. 선박관리자 입장에서는 규제 불확실성과 무관하게 회수기간이 짧은 ESD·선체·프로펠러 관리·최적 운항 등에 우선 투자하는 것이 리스크가 낮은 전략임을 뒷받침한다.", "eImp": "With IMO Net-Zero Framework adoption delayed and future-fuel investment decisions stalling, a class CEO is saying: don't wait — start with efficiency. It backs the low-risk strategy of prioritising short-payback items (energy saving devices, hull and propeller management, voyage optimisation) that pay off regardless of how the regulation lands.", "url": "https://www.marinelink.com/news/energyefficiency-measures-first-says-dnv-540925"}, {"code": "EE", "title": "ABS Backs bound4blue Methodology for Wind Propulsion Compliance", "src": "MarineLink", "date": "2026-07-02", "kSum": "선급 ABS가 바운드포블루(bound4blue)의 eSAIL 흡입식 세일에 대한 Pwind 값 산정 방법론을 검토·승인했다. 이 방법론은 EEDI, EEXI 및 FuelEU Maritime 컴플라이언스에 반영되는 Pwind 계산용 공력(aerodynamic) 힘 매트릭스 산출 절차를 다루며, 전산유체역학(CFD) 모델링을 결합한다.", "eSum": "Classification society ABS has reviewed bound4blue's methodology for calculating Pwind values used to quantify the contribution of its eSAIL suction sails toward emissions regulations. The review covered the methodology for producing the aerodynamic force matrices used in Pwind calculations for EEDI, EEXI and FuelEU Maritime compliance, combining computational fluid dynamics modelling.", "kImp": "풍력보조추진의 실제 문제는 장치 성능이 아니라 그 성능을 규제상 크레딧으로 얼마나 인정받느냐다. Pwind 산정 방법론이 선급 검증을 거치면 EEXI 개선분과 FuelEU 준수 기여도를 정량화할 수 있어 투자 회수 계산이 가능해지고, 레트로핏 검토 시 은행·용선자 설득 근거가 된다.", "eImp": "The real obstacle for wind-assisted propulsion is not device performance but how much of it counts as regulatory credit. Class verification of the Pwind methodology lets owners quantify the EEXI improvement and FuelEU contribution, making payback calculable and giving banks and charterers something bankable when assessing a retrofit.", "url": "https://www.marinelink.com/news/abs-backs-boundblue-methodology-wind-540866"}, {"code": "EE", "title": "UK carbon market extends to shipping from today", "src": "Splash247", "date": "2026-07-01", "kSum": "영국이 7월 1일부터 배출권거래제(UK ETS)를 국내 해운으로 확대해 5,000GT 이상 화물선·여객선을 탄소시장에 편입했다. 영국 항만 간 항해와 영국 항만 내 활동(화물작업, 정박 중 호텔링, 항내 이동)에 적용되며 CO2·메탄·아산화질소를 모니터링하고 검증배출량만큼 영국 배출권을 제출해야 한다. 책임은 원칙적으로 등록선주에게 있으나 법적 구속력 있는 서면 합의로 ISM 회사에 위임할 수 있고, 최초 이행연도는 2026년 7월 1일~12월 31일이다.", "eSum": "The UK extended its emissions trading scheme to domestic shipping from 1 July, bringing cargo and passenger vessels of 5,000 gt and above into its carbon market. UK ETS applies to voyages between UK ports and to in-port activities including cargo operations, hotelling and movements within port; operators must monitor CO2, methane and nitrous oxide and surrender UK allowances against verified emissions. Responsibility sits by default with the registered owner but can be delegated to the ISM company by legally binding written agreement; the first scheme year runs 1 July to 31 December 2026.", "kImp": "EU ETS와 별개 제도이므로 항로에 따라 두 제도를 동시에 준수해야 한다. 최초 UK ETS 대상 활동 후 42일 이내에 배출 모니터링 계획을 신청하고 'Manage your Emissions Trading Scheme' 계정을 개설해야 하며, 연간 검증보고서는 다음 해 3월 31일까지, 2026·2027년 배출권 제출은 2028년 4월 30일까지다. 선주-ISM 회사 간 위임 합의가 없으면 등록선주가 책임을 진다. 해양지원선은 2026년 말까지 제외되고 2027년 1월 1일부터 의무화된다.", "eImp": "It is separate from the EU ETS, so qualifying ships may need to comply with both depending on trading pattern. Operators must open a maritime operator account and apply for an emissions monitoring plan within 42 days of their first qualifying UK activity; verified annual reports are due by 31 March, and allowances for the 2026 and 2027 scheme years by 30 April 2028. Without a valid delegation, the registered owner remains responsible; offshore ships are excluded until end-2026 and mandatory from 1 January 2027.", "url": "https://splash247.com/uk-carbon-market-extends-to-shipping-from-today/"}]}, {"code": "DIG", "type": "news", "kTitle": "Section 7. 디지털라이제이션", "eTitle": "Section 7. Digitalization", "items": [{"code": "DIG", "title": "TTI Algeciras to implement smart terminal system with CyberLogitec TOS and digital twin", "src": "Smart Maritime Network", "date": "2026-07-14", "kSum": "스페인 알헤시라스만 항의 반자동화 컨테이너 터미널인 TTI 알헤시라스(TTI Algeciras)가 한국 해운 소프트웨어 기업 사이버로지텍(CyberLogitec)과 B1 확장 프로젝트용 터미널운영시스템(TOS) 및 디지털 트윈 공급 계약을 체결했다. 사이버로지텍은 OPUS Terminal 플랫폼과 디지털 트윈 시스템을 배치해 선박·야드·게이트·장비 운영을 통합 관리하고, 터미널 활동과 장비 상태를 실시간 시각화하며 시나리오 시뮬레이션을 지원한다. HMM과 CMA CGM 계열 투자사가 공동 보유한 이 터미널은 2028년 B1 확장 완료 시 연간 처리능력이 160만 TEU에서 210만 TEU로 늘어난다.", "eSum": "TTI Algeciras, the semi-automated container terminal in Spain's Bay of Algeciras, has signed with South Korean maritime software developer CyberLogitec for a terminal operating system (TOS) and digital twin technology for its B1 Expansion Project. CyberLogitec will deploy its OPUS Terminal platform alongside a digital twin system to manage vessel, yard, gate and equipment operations, providing real-time visualisation of terminal activity and equipment status plus scenario simulation. Jointly owned by HMM and a CMA CGM-affiliated investment firm, the terminal's annual capacity will rise from 1.6m TEU to 2.1m TEU by 2028.", "kImp": "디지털 트윈이 컨테이너 터미널 운영의 표준 인프라로 자리잡고 있음을 보여주는 사례로, 선박 관리자 입장에서는 기항 터미널의 예측 가능성과 접안·하역 계획 정확도 향상을 기대할 수 있다. 터미널 측 실시간 데이터가 정교해질수록 선사·선박관리사의 포트콜 최적화와 체선 리스크 관리도 함께 개선된다.", "eImp": "It shows digital twins becoming standard infrastructure at container terminals, which for ship managers should translate into more predictable berthing and cargo-handling schedules at the ports they call. As terminal-side real-time data improves, so does the scope for port call optimisation and demurrage/waiting-time risk management on the owner and manager side.", "url": "https://smartmaritimenetwork.com/2026/07/14/tti-algeciras-to-implement-smart-terminal-system/"}, {"code": "DIG", "title": "Maritime companies caught up in FortiBleed leak, according to report", "src": "Smart Maritime Network", "date": "2026-07-03", "kSum": "사이버 보안 기업 사이돔(Cydome)에 따르면 주요 해운·항만·에너지 기업들이 최근 포티블리드(FortiBleed) 사고로 포티넷(Fortinet) 방화벽 비밀번호와 로그인 정보가 유출된 것으로 확인됐다. 194개국에서 8만6,000건 이상의 관리자 계정 정보가 유출됐고, 여기에는 해사 위성통신 서비스 제공업체와 연관된 703개의 위성 연결 IP 주소도 포함됐다. 영향을 받은 250개 이상의 해운 관련 기업 중 대다수가 선주사 또는 선박관리회사였으며, 인터넷에 노출된 포티넷 장비의 87%가 여전히 관리 인터페이스를 외부에 개방하고 있었다.", "eSum": "Cyber security firm Cydome has identified major maritime, port and energy companies whose Fortinet Firewall passwords and login details were leaked in the FortiBleed incident. More than 86,000 administrator credentials across 194 countries were breached, including 703 satellite-linked IP addresses associated with maritime satcom service providers. Of over 250 maritime firms affected, most were shipowner or ship management companies, and 87% of internet-exposed Fortinet devices still had management interfaces facing the internet.", "kImp": "선박관리회사가 유출 피해의 중심에 있다는 점에서, 사무소·선박 네트워크의 포티넷 장비 관리자 계정 재설정, MFA 적용, 레거시 비밀번호 폐기 여부를 즉시 점검해야 한다. 위성통신 IP까지 노출된 만큼 선박 IT/OT 경계가 실제로 위협에 노출될 수 있으며, 패치만으로는 해결되지 않는다는 점이 핵심이다.", "eImp": "With ship management companies at the centre of the exposure, managers should immediately verify that Fortinet admin credentials on both office and vessel networks have been reset, MFA enabled and legacy passwords fully retired. The exposure of satcom-linked IPs means shipboard IT/OT boundaries may be genuinely at risk, and the key lesson is that patching alone did not close this hole.", "url": "https://smartmaritimenetwork.com/2026/07/03/maritime-companies-caught-up-in-fortibleed-leak-according-to-report/"}, {"code": "DIG", "title": "Angelicoussis doubles data usage following Starlink deployment", "src": "Smart Maritime Network", "date": "2026-07-02", "kSum": "그리스 안젤리쿠시스 그룹(Angelicoussis Group)이 스페이스X(SpaceX) 및 공인 리셀러 나바리노(Navarino)와 협력해 140척 이상의 선박에 스타링크(Starlink) 위성통신을 도입했고, 그 결과 선대 전체 데이터 사용량이 두 배로 늘었다. 유연한 풀링 데이터 요금제를 통해 영상통화, HD 영상 전송, 실시간 텔레메트리, 사이버보안 강화를 지원한다. 보험 클레임·사고 분석용 HD 영상과 상태기반 정비 데이터를 지연 없이 전송할 수 있게 됐다.", "eSum": "Greece's Angelicoussis Group has rolled out Starlink connectivity across more than 140 vessels in collaboration with SpaceX and authorised reseller Navarino, doubling data consumption across the fleet. Flexible pooled data plans now support video calls, HD video transfers, real-time telemetry and improved cyber security protections. HD video files for insurance claims, incident analysis and condition-based maintenance can now be transferred with minimal delay.", "kImp": "LEO 위성통신이 선원 복지 수단을 넘어 상태기반 정비·사고 조사·클레임 처리의 실질적 운영 자산으로 바뀌고 있음을 보여준다. 선박관리 측면에서는 대역폭 확대에 따른 데이터 정책·사이버 위험 관리와, '집과 같은 인터넷'이 젊은 승선원 확보·유지에 미치는 효과를 함께 계산해야 한다.", "eImp": "It shows LEO connectivity shifting from a crew-welfare perk to a working operational asset for condition-based maintenance, incident investigation and claims handling. Managers need to plan for the data governance and cyber risk that come with the extra bandwidth, while also factoring in how 'home-like' internet supports recruitment and retention of younger seafarers.", "url": "https://smartmaritimenetwork.com/2026/07/02/angelicoussis-doubles-data-usage-following-starlink-deployment/"}, {"code": "DIG", "title": "MOL and IBM unveil AI vessel operations platform", "src": "Splash247", "date": "2026-07-01", "kSum": "미쓰이 O.S.K. 라인(MOL)과 IBM 재팬(IBM Japan)이 공동 개발한 AI 기반 선박 운항 의사결정 지원 플랫폼이 7월 1일 가동에 들어갔다. 이 시스템은 MOL 관련 선박을 24시간 모니터링하는 안전운항지원센터(Safety Operation Supporting Center)를 중심으로 구축됐으며, 기상·해상 상태, 선박 운항 정보, 지정학적 동향 등 흩어져 있던 데이터를 통합한다. 생성형 AI가 과거 운항 기록과 현재 항해 정보를 활용해 선박별 리스크를 실시간으로 추출하고 의사결정 우선순위를 지원한다.", "eSum": "Mitsui OSK Lines (MOL) and IBM Japan have jointly developed an AI-powered platform to improve decision-making across MOL's global vessel operations, which went live on 1 July. Built around MOL's Safety Operation Supporting Center, its 24/7 hub monitoring MOL-affiliated vessels worldwide, the platform combines weather and sea condition data, vessel operating information and geopolitical developments previously spread across multiple sources. Generative AI extracts vessel-specific risks in real time from historical records and current voyage information to support monitoring, situation assessment and prioritisation of decisions.", "kImp": "육상 운항 관제가 '정보 수집'에서 '선제적 리스크 식별'로 이동하는 흐름을 보여주며, 선박관리사의 육상 지원 조직 설계와 인력 역할 재정의에 직접적인 시사점을 준다. 특히 지정학 리스크까지 운항 데이터와 결합해 다루는 접근은 호르무즈·홍해 등 고위험 구역 운항 판단에 참고가 된다.", "eImp": "It marks a shift in shore-based operations centres from information gathering to proactive risk identification, with direct implications for how ship managers design shore support teams and redefine roles. The approach of fusing geopolitical risk with operating data is particularly relevant to routing decisions in high-risk areas such as Hormuz and the Red Sea.", "url": "https://splash247.com/mol-and-ibm-unveil-ai-vessel-operations-platform/"}, {"code": "DIG", "title": "Shipping's AI race runs ahead of the rulebook", "src": "Splash247", "date": "2026-07-08", "kSum": "IMO 해사안전위원회가 5월 22일 채택한 자율운항선박(MASS) 코드가 7월 1일 비강제 문서로 발효되면서, 기국·선주·선급이 데이터를 축적하는 '경험 축적 단계(Experience Building Phase)'가 시작됐다. 그러나 이 코드는 선박 자율화 등급과 원격운항센터를 다룰 뿐, 실제로 가장 빠르게 확산 중인 선내 AI 어시스턴트·예측정비·행정 소프트웨어에 대해서는 거의 규정하지 않는다. DNV는 규정 데이터베이스를 검색하고 답변마다 원문 출처를 연결하는 AI 도구 룰에이전트(RuleAgent)를 출시했고, BIMCO는 소수 클라우드·AI 공급자 의존이 지정학적 사이버 리스크를 키운다고 경고했다.", "eSum": "The IMO MASS Code, adopted by the Maritime Safety Committee on 22 May, entered into force on 1 July as a voluntary instrument, opening an 'Experience Building Phase' in which flag states, owners and class societies gather data before mandatory rules follow. But the Code covers degrees of ship autonomy and remote operations centres while saying little about the AI tools spreading fastest — onboard assistants, predictive maintenance and administrative software. DNV has launched RuleAgent, an AI tool that searches its rules database and links every answer back to source text, while BIMCO warned that dependence on a few dominant cloud and AI providers adds a geopolitical dimension to cyber risk.", "kImp": "선내 AI 도구에 대한 단일 국제 기준이 없는 상태에서 선박관리사가 자체 거버넌스(사용 정책, 계정 추적, 검증 가능한 데이터 소스)를 먼저 갖춰야 함을 시사한다. EU AI법 본격 집행에 따라 전 세계 매출의 7% 또는 3,500만 유로까지 과징금이 가능하다는 점도 무시할 수 없는 컴플라이언스 리스크다.", "eImp": "With no single international standard for onboard AI tools, ship managers need to build their own governance first — usage policies, traceable accounts and vetted data sources rather than the open internet. Full enforcement of the EU AI Act, carrying fines of up to EUR 35m or 7% of global turnover, makes this a live compliance exposure rather than a future one.", "url": "https://splash247.com/shippings-ai-race-runs-ahead-of-the-rulebook/"}, {"code": "DIG", "title": "MagicPort lands $3m to accelerate port call digitalisation", "src": "Splash247", "date": "2026-07-10", "kSum": "포트콜 디지털화 스타트업 매직포트(MagicPort)가 300만 달러 규모의 투자를 유치했다. 이 회사는 선주, 선박대리점 등 해사 이해관계자들이 단일 디지털 플랫폼에서 기항 업무를 조율할 수 있도록 AI 기반 워크플로우 및 인텔리전스 도구를 개발한다.", "eSum": "Port call digitalisation startup MagicPort has raised $3m in funding. The company develops AI-powered workflow and intelligence tools that help shipowners, ship agents and other maritime stakeholders coordinate port calls through a single digital platform.", "kImp": "기항 업무는 여전히 이메일과 수작업 조율에 크게 의존하는 영역으로, 이 분야에 자본이 유입된다는 것은 선박관리사의 대리점·항만 커뮤니케이션 방식이 바뀔 여지가 크다는 뜻이다. 포트콜 조율 자동화는 재항 시간 단축과 대리점 비용 관리에 직접적으로 연결된다.", "eImp": "Port calls remain heavily dependent on email and manual coordination, so capital flowing into this niche signals real scope to change how ship managers work with agents and ports. Automating port call coordination ties directly to shorter port stays and better control of agency costs.", "url": "https://splash247.com/magicport-lands-3m-to-accelerate-port-call-digitalisation/"}, {"code": "DIG", "title": "USCG: Maritime cyber incidents rise 17% as phishing, AI and OT risks reshape the threat landscape", "src": "SAFETY4SEA", "date": "2026-07-08", "kSum": "미국 해안경비대 사이버사령부(USCG Cyber Command)가 다섯 번째 연례 '해양 환경 사이버 동향 및 인사이트(Cyber Trends and Insights in the Marine Environment)' 보고서를 발표했다. 보고서는 위협이 갈수록 정교해지는 한편, 성공한 공격 상당수는 여전히 피싱 등 익숙한 취약점에 의존하고 있다고 지적한다. 인공지능은 책임 소재, ISO/IEC 42001 준수, 데이터 격리, 접근 통제, 공급망 리스크 관리 등 추가적인 거버넌스 과제를 낳고 있다.", "eSum": "The U.S. Coast Guard Cyber Command has published its fifth annual Cyber Trends and Insights in the Marine Environment report. It describes a landscape in which threats are becoming more sophisticated, yet many successful attacks still rely on familiar weaknesses such as phishing. Artificial intelligence introduces additional governance challenges including accountability, compliance with ISO/IEC 42001, data isolation, access control and supply chain risk management.", "kImp": "공격의 정교함이 아니라 피싱 같은 기본 취약점이 여전히 주요 침투 경로라는 점은, 선박관리사의 투자 우선순위가 첨단 솔루션보다 승선원·육상 직원 대상 기본 훈련과 계정 위생에 있어야 함을 뜻한다. 위성통신과 OT 시스템의 통합 지점이 늘면서 데이터 유출을 넘어 실제 항해를 방해하는 파괴적 공격으로 진화할 수 있다는 경고도 SMS 사이버 리스크 관리에 반영해야 한다.", "eImp": "That basic weaknesses like phishing remain the main way in — not exotic sophistication — means managers should prioritise crew and shore-staff training and account hygiene over new tooling. The warning that growing integration between satcom and OT systems can turn data theft into destructive attacks that disrupt actual navigation should feed directly into SMS cyber risk management.", "url": "https://safety4sea.com/uscg-maritime-cyber-incidents-rise-17-as-phishing-ai-and-ot-risks-reshape-the-threat-landscape/"}, {"code": "DIG", "title": "Fleetwork: Posidonia 2026 signals turning point for AI, cloud adoption in shipping", "src": "MarineLink", "date": "2026-07-02", "kSum": "그리스 해사 기술기업 플릿워크(Fleetwork)는 포시도니아 2026(Posidonia 2026) 참가 결과, 인공지능과 클라우드 네이티브 기술이 혁신 프로젝트 단계를 넘어 해운사의 운영 우선순위로 이동했다고 밝혔다. 전시 기간 중 50개 해운사 관계자와 80회 이상 미팅을 진행했고 15건의 제품 시연 요청을 받았다. 창업자 겸 CEO 야니스 사리스(Giannis Sarris)는 전시 기간 대화의 70% 이상이 인공지능, 자동화, 클라우드 마이그레이션 전략에 집중됐다고 밝혔다.", "eSum": "Greek maritime technology company Fleetwork reports that, following Posidonia 2026, artificial intelligence and cloud-native technologies have moved from innovation projects to operational priorities for shipping companies. During the exhibition it held more than 80 meetings with representatives from 50 shipping companies and received 15 requests for product demonstrations. Founder and CEO Giannis Sarris said more than 70% of conversations held during the exhibition focused on artificial intelligence, automation and cloud migration strategies.", "kImp": "선주·운항사들이 온프레미스 시스템과 분절된 소프트웨어 환경에서 벗어나 실시간 가시성과 선-육 협업을 우선시하고 있다는 시장 신호로, 선박관리사의 IT 아키텍처 로드맵 수립에 참고가 된다. 업계 전반의 클라우드 이전 속도가 빨라질수록 데이터 소유권·공급자 종속·사이버 경계 설계 문제도 함께 앞당겨진다.", "eImp": "It signals that owners and operators are moving away from on-premises systems and fragmented software towards real-time visibility and seamless vessel-to-shore collaboration, which is useful input for a ship manager's IT architecture roadmap. The faster the industry migrates to cloud, the sooner questions of data ownership, vendor lock-in and cyber perimeter design have to be answered.", "url": "https://www.marinelink.com/news/fleetwork-posidonia-signals-turning-point-540885"}, {"code": "DIG", "title": "ABB to acquire Høglund to expand marine automation business", "src": "Seatrade Maritime News", "date": "2026-07-02", "kSum": "ABB가 노르웨이 해사 자동화 전문기업 회글룬(Høglund)을 인수해 선박 자동화 사업을 확대한다고 발표했다. 회글룬은 통합 자동화 시스템과 연료·에너지 관리 솔루션 분야에서 입지를 갖춘 기업이다.", "eSum": "ABB has announced it will acquire Norwegian marine automation specialist Høglund to expand its marine automation business. Høglund is established in integrated automation systems and fuel and energy management solutions.", "kImp": "선박 자동화·통합 제어 시장이 소수 대형 공급자로 재편되는 흐름을 보여주며, 선박관리사 입장에서는 기존 회글룬 시스템 탑재선의 서비스 체계와 장기 지원 정책 변화 가능성을 점검할 필요가 있다. 공급자 통합은 통합 자동화 로드맵의 일관성을 높이는 동시에 협상력과 공급자 종속 측면의 리스크도 함께 키운다.", "eImp": "It shows consolidation of the marine automation and integrated control market into fewer large suppliers, so managers with Høglund systems installed should check for changes to service arrangements and long-term support policy. Supplier consolidation can bring a more coherent automation roadmap but also increases vendor lock-in and weakens negotiating leverage.", "url": "https://www.seatrade-maritime.com/maritime-technology/abb-to-acquire-h-glund-to-expand-marine-automation-business"}]}, {"code": "TECH", "type": "news", "kTitle": "Section 8. 선박관리 기술", "eTitle": "Section 8. Ship Manager Technical", "items": [{"code": "TECH", "title": "Kongsberg Maritime to acquire Berg Propulsion", "src": "Smart Maritime Network", "date": "2026-07-13", "kSum": "콩스버그 마리타임(Kongsberg Maritime)이 스웨덴 예테보리에 본사를 둔 추진·전기 시스템 전문업체 베르그 프로펄션(Berg Propulsion) 인수 계약을 체결했다. 거래 금액은 공개되지 않았으며, 콩스버그는 자사의 현재 EV/EBITDA 배수와 유사한 수준에서 가격이 책정됐다고 밝혔다. 거래는 통상적인 규제 승인 및 클로징 조건을 충족해야 완료된다.", "eSum": "Kongsberg Maritime has signed an agreement to acquire Swedish marine propulsion and electrical systems manufacturer Berg Propulsion, headquartered in Gothenburg. Financial terms were not disclosed, though Kongsberg said the deal was priced at approximately the same enterprise value-to-EBITDA multiple as its own market valuation. The transaction remains subject to customary regulatory approvals and closing conditions.", "kImp": "추진 장비 공급사가 통합되면 CPP·추력기 등 예비품 조달 경로와 서비스 네트워크, 장기 지원 조건이 바뀔 수 있다. 베르그 장비를 탑재한 선박을 관리하는 기술감독은 인수 후 OEM 서비스 계약과 부품 리드타임 변화를 사전에 확인해 둘 필요가 있다.", "eImp": "Consolidation among propulsion suppliers can reshape spare-parts channels, service networks and long-term support terms for CPPs and thrusters. Technical superintendents managing Berg-equipped tonnage should check how OEM service agreements and parts lead times change post-acquisition.", "url": "https://smartmaritimenetwork.com/2026/07/13/kongsberg-maritime-to-acquire-berg-propulsion/"}, {"code": "TECH", "title": "Kongsberg Maritime, KOTUG Pen Extended Tug Thruster Deal", "src": "MarineLink", "date": "2026-07-10", "kSum": "콩스버그 마리타임(Kongsberg Maritime)이 코터그 인터내셔널(KOTUG International)과 서아프리카 해상 터미널에 투입되는 신조 ASD 예인선 5척에 대한 추력기 커버리지 확대 계약을 체결했다. 5척은 동일 사양으로 단일 선단처럼 관리되며, 각 선박에는 콩스버그 US255 고정피치 추력기 2기가 탑재된다. 계약은 OEM이 정의한 예방정비 계획에 기반한 생애주기 지원 체계를 구축한다.", "eSum": "Kongsberg Maritime has signed an extended thruster coverage agreement with KOTUG International covering five newbuild azimuth stern drive tugs deployed at offshore terminals in West Africa. The five vessels share a common configuration and will be treated as a single fleet under the agreement, each fitted with two Kongsberg US255 fixed pitch thrusters. The deal establishes a lifecycle support framework based on an OEM-defined preventive maintenance plan.", "kImp": "OEM 정의 예방정비 계획을 기반으로 한 선단 단위 커버리지 계약은 계획정비 주기와 예비품 재고를 표준화해 예산 예측성을 높이는 대표적 사례다. 동일 사양 선박을 다수 운용하는 기술팀에 적용 가능한 계약 구조 참고 모델이 된다.", "eImp": "Fleet-level coverage built on an OEM-defined preventive maintenance plan is a working example of standardising PMS intervals and spare holdings to improve budget predictability. It offers a contract-structure reference for technical teams running multiple sister vessels.", "url": "https://www.marinelink.com/news/kongsberg-maritime-kotug-pen-extended-tug-541120"}, {"code": "TECH", "title": "WinGD Books Engine Order for 12 Dynacom VLCC Newbuilds", "src": "MarineLink", "date": "2026-07-01", "kSum": "스위스 엔진 설계사 윈GD(WinGD)가 중국 후둥중화조선(Hudong-Zhonghua Shipbuilding)에서 건조되는 그리스 다이나콤(Dynacom) 소속 VLCC 12척의 주기관 공급 계약을 확보했다. 각 선박에는 WinGD 6X82-2.0 저속 엔진과 함께 배기가스 스크러버 및 고압 선택적 촉매환원(SCR) 장치가 탑재된다. IMO 현행 배출 규제 충족을 목표로 한 구성이다.", "eSum": "Swiss marine engine designer WinGD has secured an order to supply main engines for 12 very large crude carriers being built at China's Hudong-Zhonghua Shipbuilding for Greek tanker owner Dynacom. Each vessel will be fitted with a WinGD 6X82-2.0 low-speed engine, alongside exhaust gas scrubbers and high-pressure selective catalytic reduction (SCR) systems. The configuration is designed to meet current IMO emissions requirements.", "kImp": "대형 탱커 신조에서 재래 연료 저속엔진 + 스크러버 + 고압 SCR 조합이 여전히 주력으로 선택되고 있음을 보여준다. 스크러버 세정수 관리와 SCR 요소수(우레아) 소비·촉매 열화 관리가 향후 기술감독의 상시 정비 항목이 된다는 점을 시사한다.", "eImp": "It shows conventional-fuel low-speed engines paired with scrubbers and high-pressure SCR remain a mainstream choice for large tanker newbuildings. That implies ongoing superintendent workload around washwater management, urea consumption and SCR catalyst degradation.", "url": "https://www.marinelink.com/news/wingd-books-engine-order-dynacoms-vlcc-540828"}, {"code": "TECH", "title": "Svanehoj Lands First LNG Carrier-to-FSU Conversion Job", "src": "MarineLink", "date": "2026-07-01", "kSum": "덴마크 선박 기자재 공급사 스바네호이(Svanehoj)가 LNG운반선을 부유식 저장설비(FSU)로 개조하는 사업에 LNG 탱크 계측 시스템을 공급하는 첫 계약을 따냈다. 스바네호이는 드라이독스 월드 두바이(Drydocks World Dubai)에 LNG 밀도·온도(LTD) 계측 시스템 4기를 납품하며, LNG운반선 'LNG Bayelsa'가 FSU 'Cap Lopez'로 개조된다. 이 공사는 가봉 해상 가스 인프라 확장 사업의 일환이다.", "eSum": "Danish marine equipment supplier Svanehoj has secured its first contract to supply LNG tank gauging systems for the conversion of an LNG carrier into a floating storage unit (FSU). The company will deliver four LNG density and temperature (LTD) gauging systems to Drydocks World Dubai for the conversion of the LNG carrier LNG Bayelsa into the FSU Cap Lopez. The work forms part of a floating LNG development expanding Gabon's offshore gas infrastructure.", "kImp": "노후 LNG운반선의 FSU 전환은 수리조선소 수요와 개조 엔지니어링 역량 확보 경쟁을 보여주는 사례다. 개조 프로젝트에서 계측·안전 시스템 교체 범위와 야드 선정이 공기·비용에 직접 영향을 주므로, 개조를 검토 중인 기술팀에 벤치마크가 된다.", "eImp": "Converting ageing LNG carriers into FSUs illustrates growing demand on repair yards and competition for conversion engineering capability. Since gauging and safety system replacement scope and yard selection drive schedule and cost, it is a useful benchmark for technical teams weighing conversions.", "url": "https://www.marinelink.com/news/svanehoj-lands-first-lng-carriertofsu-540825"}, {"code": "TECH", "title": "WE Tech Solutions and Everllence Join Forces to Advance Maritime Decarbonisation", "src": "Everllence (MAN Energy Solutions)", "date": "2026-07-14", "kSum": "에벌런스(Everllence, 구 MAN Energy Solutions)가 핀란드 전기추진·에너지효율 솔루션 업체 WE Tech Solutions와 해운 탈탄소화 추진을 위한 파트너십을 체결했다. 이번 협력은 에벌런스 프라임서브(PrimeServ)의 옴니케어(Omnicare) 3자 기자재 서비스 제공 범위를 확대한다. 에벌런스는 이를 'Moving Big Things to Zero' 전략의 일환으로 설명했다.", "eSum": "Everllence (formerly MAN Energy Solutions) has entered a partnership with Finnish electric propulsion and energy efficiency specialist WE Tech Solutions to advance maritime decarbonisation. The tie-up expands the offering of Everllence PrimeServ's Omnicare third-party equipment service business. Everllence framed the move as part of its 'Moving Big Things to Zero' ambition.", "kImp": "프라임서브 옴니케어처럼 OEM이 타사 기자재까지 서비스 범위를 넓히면, 기술감독은 여러 공급사와 개별 계약을 맺는 대신 단일 창구로 정비·부품을 통합 관리할 여지가 생긴다. 서비스 계약 재협상 시 검토할 옵션이다.", "eImp": "As OEMs like PrimeServ Omnicare extend service coverage to third-party equipment, superintendents gain the option of consolidating maintenance and parts through a single window instead of contracting each supplier separately. It is worth reviewing at service-agreement renewal.", "url": "https://www.everllence.com/company/press-releases/details/2026/07/14/we-tech-solutions-and-everllence-join-forces-to-advance-maritime-decarbonisation"}, {"code": "TECH", "title": "PrimeServ Successfully Delivers Methanol Engine Upgrade for Seaspan", "src": "Everllence (MAN Energy Solutions)", "date": "2026-06-22", "kSum": "에벌런스(Everllence) 프라임서브(PrimeServ)가 시스팬(Seaspan) 컨테이너선의 메탄올 이중연료 주기관 개조를 성공적으로 완료했다. 회사는 이를 통해 기존 선박을 이중연료로 전환하는 검증되고 확장 가능한 성숙 플랫폼이 존재함을 입증했다고 밝혔으며, 이중연료 전환이 새로운 시장 표준이 되고 있다고 강조했다. 이는 하팍로이드(Hapag-Lloyd) 대상 다선박 개조 프로그램의 일부다.", "eSum": "Everllence PrimeServ has successfully completed a methanol dual-fuel main engine upgrade on a Seaspan containership. The company said the project proves a mature, scalable and proven platform now exists for upgrading vessels to dual-fuel operation, which it described as the new market standard. The work forms part of a multi-vessel upgrade programme for Hapag-Lloyd.", "kImp": "실선 메탄올 개조 완료는 개조 공기, 야드 작업 범위, 시운전 절차에 대한 실측 데이터를 제공한다. 이중연료 개조를 검토 중인 기술감독에게 OEM 개조 패키지의 성숙도와 사후 서비스 체계를 판단할 근거가 된다.", "eImp": "A completed in-service methanol conversion provides real data on retrofit duration, yard work scope and commissioning procedures. It gives superintendents evidence on the maturity of OEM conversion packages and their after-sales support when assessing dual-fuel retrofits.", "url": "https://www.everllence.com/company/press-releases/details/2026/06/22/primeserv-successfully-delivers-methanol-engine-upgrade-for-seaspan"}, {"code": "TECH", "title": "Wärtsilä agreement to strengthen operational reliability and maintenance predictability for Pardus Energy FSRU", "src": "Wärtsilä", "date": "2026-07-15", "kSum": "바르질라(Wärtsilä)가 아일랜드 파두스 에너지(Pardus Energy)와 FSRU 'TURQUOISE P'의 안정적 운항을 지원하는 5년 생애주기 계약(Lifecycle Agreement)을 체결했다. 계약에는 전담 계약관리, 정비 계획 수립, 예비품 공급이 포함된다. 2019년 준공된 TURQUOISE P는 튀르키예 알리아아(Aliaga) ETKI LNG 터미널에서 정박형 FSRU로 운영 중이며, 수주는 2026년 2분기에 계상됐다.", "eSum": "Wärtsilä has signed a five-year Lifecycle Agreement with Ireland-based Pardus Energy to support reliable operation of the FSRU TURQUOISE P. The agreement covers dedicated contract management, maintenance planning and spare parts support. Commissioned in 2019, TURQUOISE P operates as a stationary FSRU at the ETKI LNG terminal in Aliaga, Türkiye; the order was booked in Q2 2026.", "kImp": "정비 계획·예비품을 묶은 다년 생애주기 계약은 계획외 정지 리스크를 공급사와 분담하는 구조로, 가동률이 곧 수익인 자산에서 특히 유효하다. 기술감독 입장에서 CBM 기반 계약 설계와 예비품 재고 최적화의 실무 사례다.", "eImp": "Multi-year lifecycle agreements bundling maintenance planning and spares shift unplanned-downtime risk onto the supplier, which matters most where uptime equals revenue. For superintendents it is a practical case study in CBM-based contract design and spares inventory optimisation.", "url": "https://www.wartsila.com/media/news/15-07-2026-wartsila-agreement-to-strengthen-operational-reliability-and-maintenance-predictability-for-pardus-energy-fsru-3772478"}, {"code": "TECH", "title": "Wärtsilä propulsion solutions selected for Grimaldi Group's major newbuild programme", "src": "Wärtsilä", "date": "2026-07-07", "kSum": "바르질라(Wärtsilä)가 그리말디 그룹(Grimaldi Group)의 신조 페리 9척에 추진 솔루션 일체를 공급한다. 9척은 그리말디 라인스(Grimaldi Lines) 4척, 핀라인스(Finnlines) 3척, 미노안 라인스(Minoan Lines) 2척으로 구성되며 중국 초상국공업 웨이하이(China Merchants Shipbuilding Weihai) 조선소에서 건조된다. 전 선박에 바르질라의 연료 유연성·고효율 46F 엔진이 탑재된다.", "eSum": "Wärtsilä will supply a full range of propulsion solutions for nine newbuild ferries for the Grimaldi Group — four for Grimaldi Lines, three for Finnlines and two for Minoan Lines — being built at China Merchants Shipbuilding Industry Group Weihai Shipyard. All nine vessels will operate with Wärtsilä's fuel-flexible, high-efficiency 46F engines.", "kImp": "대형 선주가 단일 공급사 추진 패키지와 연료 유연성 엔진을 표준으로 채택하는 흐름을 보여준다. 선단 표준화는 예비품 공통화, 승선원 교육 부담 경감, 서비스 계약 단순화로 이어져 기술관리 비용에 직접 영향을 준다.", "eImp": "It reflects large owners standardising on a single-supplier propulsion package with fuel-flexible engines. Fleet standardisation drives spares commonality, lighter crew training burden and simpler service contracts — all with direct impact on technical management cost.", "url": "https://www.wartsila.com/media/news/07-07-2026-wartsila-propulsion-solutions-selected-for-grimaldi-group-s-major-newbuild-programme-3770089"}, {"code": "TECH", "title": "Hydrogen-fuelled shipping takes step forward as BeHydro's engine gets go-ahead", "src": "Offshore Energy", "date": "2026-06-18", "kSum": "로이드선급(Lloyd's Register)이 비하이드로(BeHydro)의 100% 수소 전소 스파크 점화식 선박 엔진에 대해 최초의 형식승인 증서를 발급했다. 비하이드로는 CMB.TECH와 앵글로 벨지언 코퍼레이션(ABC Engines)의 합작사로, 해당 엔진은 겐트(Ghent) 소재 ABC 시설에서 개발·시험됐다. 파일럿 연료 없이 수소만으로 운전 가능하며, 출력 범위는 900kW에서 2,670kW다.", "eSum": "Lloyd's Register has issued the first type approval certificate for BeHydro's 100% hydrogen-fuelled, spark-ignited marine engine. BeHydro is a joint venture between CMB.TECH and Anglo Belgian Corporation (ABC) Engines, and the engine was developed and tested at ABC's facility in Ghent. It runs entirely on hydrogen without pilot fuel, with a range from 900 kW to 2,670 kW.", "kImp": "파일럿 연료가 필요 없는 수소 전소 엔진의 형식승인은 보조기관·소형 선박용 무탄소 대안이 상용화 단계에 근접했음을 뜻한다. 다만 수소 벙커링 인프라와 안전 절차가 제약이므로, 기술감독은 승인 사실보다 실제 운용 여건을 함께 평가해야 한다.", "eImp": "Type approval for a pilot-fuel-free hydrogen engine signals that zero-carbon options for auxiliaries and smaller vessels are nearing commercial readiness. Bunkering infrastructure and safety procedures remain the constraint, so superintendents should weigh operational feasibility alongside the certification itself.", "url": "https://www.offshore-energy.biz/hydrogen-fuelled-shipping-takes-step-forward-as-behydros-engine-gets-go-ahead/"}]}, {"code": "HR", "type": "news", "kTitle": "Section 9. 해기인력·선원", "eTitle": "Section 9. Marine HR", "items": [{"code": "HR", "title": "Abandoned and unpaid: seafarers left stranded, owed $68,000 in Las Palmas", "src": "ITF Seafarers", "date": "2026-07-09", "kSum": "터키 선주 소유 일반화물선 레이디 미나(Lady Mina)호의 선원 6명이 라스팔마스(Las Palmas)항에 유기된 채 남아 있으며, 미지급 임금은 총 6만 8천 달러에 달한다. ITF 검사관 조사 결과 위조된 재정보증(MLC) 증서와 법정 증서 미비가 드러나 스페인 해사당국(Capitanía Marítima)이 선박을 억류했다. 기관장은 2024년 10월 승선 이후 2026년 1월부터 무급 상태이며, 일부 선원은 MLC 상한인 11개월을 넘겨 13개월 이상 승선했다.", "eSum": "Six seafarers remain abandoned aboard the Turkish-owned general cargo ship Lady Mina, detained in Las Palmas, with unpaid wages now totalling USD 68,000. An ITF inspection found the vessel lacked required statutory certificates and that its MLC financial-security documentation appears fraudulent, prompting the Spanish Maritime Authority to detain her. The Chief Engineer had served since October 2024 and been unpaid since January 2026, while one crew member exceeded the MLC 11-month maximum with over 13 months on board. ITF is now assisting the crew to arrest the vessel; the same owner abandoned crew on this ship in Djen Djen, Algeria in December 2024.", "kImp": "위조 MLC 재정보증 증서가 실재한다는 점은 선박관리자가 하도급 선주·선원공급업체의 보증서를 액면 그대로 신뢰해서는 안 된다는 경고다. 억류·선박 압류로 이어지면 용선 중단과 평판 손실이 즉시 발생하므로, 승선기간 11개월 상한과 임금 지급 이력을 상시 모니터링하는 통제장치가 필요하다.", "eImp": "The forged MLC financial-security certificate shows ship managers cannot take owners' or manning agents' guarantee documents at face value. Detention and vessel arrest bring immediate charter interruption and reputational damage, so continuous monitoring of the 11-month service cap and wage-payment records is an essential control.", "url": "https://www.itfseafarers.org/en/news/abandoned-and-unpaid-seafarers-left-stranded-owed-68000-las-palmas"}, {"code": "HR", "title": "Crew Welfare Week 2026: Operational excellence and crew welfare are not competing priorities", "src": "SAFETY4SEA", "date": "2026-07-14", "kSum": "크루 웰페어 위크 2026(Crew Welfare Week 2026) 선박관리자 패널에서 V.Ships Greece의 디미트리스 파트리키오스(Dimitris Patrikios)는 해운이 여전히 탱커와 건화물선 간 복지 격차가 큰 '이중 시장(two-tier market)'이라고 지적하며 '행복한 배가 안전한 배(a happy ship is a safe ship)'라고 말했다. 왈렘 그룹(Wallem Group)의 저크시스 다지(Xerxes Daji) 선장은 정신건강 낙인과 휴식시간 위반이 지속되며 일부 선주는 여전히 선원에게 인터넷 비용을 청구한다고 밝혔다. 마리암 십매니지먼트(Maryam Shipmanagement)의 파우지 프라디(Faouzi Fradi) CEO는 '핵심 인력(key worker)' 지위가 위기 때만 반짝 언급된다고 비판했다.", "eSum": "At a Crew Welfare Week 2026 ship-manager panel, Dimitris Patrikios of V. Ships Greece said shipping still runs a two-tier market in which welfare standards differ sharply between tankers and dry cargo, with tanker progress driven by charterer and oil-major pressure, adding: 'Operational excellence and crew welfare are not competing priorities. They are mutually dependent.' Capt. Xerxes Daji of Wallem Group flagged persistent mental-health stigma, work and rest hour violations, and owners who still charge crew for internet or provide minimal bandwidth. Capt. Faouzi Fradi of Maryam Shipmanagement warned the 'key worker' label fades once each crisis passes and urged empowering masters to anchor for crew rest. Patrikios cautioned against creating compliance fatigue, and Costas Kontes of Navilands stressed regular surveys to hear directly from crew; V. Ships draws on a pool of around 45,000 seafarers.", "kImp": "동종 선박관리사 경영진이 직접 밝힌 격차 진단이므로 자사 선대의 복지 수준을 벤치마킹할 실질적 기준이 된다. 특히 인터넷 비용 부담, 휴식시간 위반, 컴플라이언스 피로는 선원 유지율과 직결되는 관리 항목이다.", "eImp": "This is a peer benchmark stated directly by ship-manager executives, giving a practical yardstick against which to measure one's own fleet. Internet cost-sharing, rest-hour violations and compliance fatigue are the specific levers that most directly affect crew retention.", "url": "https://safety4sea.com/cm-crew-welfare-week-2026-operational-excellence-and-crew-welfare-are-not-competing-priorities/"}, {"code": "HR", "title": "Indian seafarer killed in Iran tanker strikes, says UAE", "src": "Seatrade Maritime News", "date": "2026-07-14", "kSum": "UAE 국방부는 이란의 순항미사일 공격으로 유조선 2척이 피격돼 인도 선원 1명이 사망하고 인도·우크라이나 선원 8명이 부상했으며 이 중 4명은 중상이라고 밝혔다. 피격 선박은 ADNOC Logistics & Services가 운항하는 VLCC 몸바사 B(Mombasa B)와 알 바히아(Al Bahyah)로, 호르무즈 해협(Strait of Hormuz) 남쪽 항로를 통과하던 중 공격을 받아 화재가 발생했다. UAE는 '국제법의 명백한 위반'이라며 대응 권리를 유보한다고 밝혔다.", "eSum": "The UAE Ministry of Defence says one Indian seafarer was killed and eight Indian and Ukrainian seafarers injured, four seriously, in Iranian cruise missile attacks on two tankers. The VLCCs Mombasa B and Al Bahyah, both operated by ADNOC Logistics & Services, were transiting the southern route through the Strait of Hormuz when hit, sustaining material damage and onboard fires that have since been brought under control. The ministry condemned 'this blatant attack, which is considered a serious violation and a clear breach of international law' and said the UAE reserves its full right to respond. Kpler reported Hormuz crossings down roughly 52% week-on-week for 10-12 July, with the southern route almost deserted after the US announced its blockade of Iranian ports would resume.", "kImp": "미국이 권고한 남쪽 항로에서조차 선원 사상자가 발생했다는 것은 '안전 회랑'이라는 전제가 무너졌음을 뜻한다. 선박관리자는 호르무즈 통항 여부를 선원 동의와 전쟁위험 지역(WOA) 보상 체계에 연동해 재검토하고, 통항 거부권을 실질적으로 보장해야 한다.", "eImp": "Casualties on the very southern route the US has promoted undermine the premise of a safe corridor. Managers should re-examine Hormuz transit decisions against crew consent and Warlike Operations Area compensation, and make the right to refuse transit genuinely exercisable.", "url": "https://www.seatrade-maritime.com/security/indian-seafarer-killed-in-iran-tanker-strikes-says-uae"}, {"code": "HR", "title": "Seafarers Killed and Injured as Russia and Ukraine Intensify Strikes", "src": "The Maritime Executive", "date": "2026-07-13", "kSum": "흑해와 아조프해(Sea of Azov)에서 러시아와 우크라이나의 공격이 격화되며 민간 선원 사상자가 잇따르고 있다. 초르노모르스크(Chornomorsk)에서 비료를 양하하던 토고 선적 벌크선이 거주구에 피격돼 선원 3명이 사망하고 5명이 부상했으며, 사상자는 이집트·시리아 국적으로 전해졌다. 우크라이나는 8일간 105척 이상을 타격했다고 밝혔고, IMO 사무총장 아르세니오 도밍게스(Arsenio Dominguez)는 민간 상선 공격을 개탄한다고 밝혔다.", "eSum": "Civilian seafarer casualties are mounting as Russia and Ukraine escalate strikes in the Black Sea and Sea of Azov. A Togo-registered bulker discharging fertilizer at Chornomorsk was hit in the superstructure, killing three crew and injuring five, reported to be Egyptian and Syrian nationals; a Saint Kitts and Nevis vessel was struck on 11 July with no injuries. Russia said it struck Chornomorsk for three consecutive days, damaging two Ro-Ro ferries and a bulk carrier, while Ukraine reported six port workers, drivers and sailors killed over three days and at least 56 people injured nationwide. Ukraine's Sea of Azov drone campaign has now hit over 105 ships in eight days, including at least four tankers in Taganrog Bay on 11 July with at least one seafarer killed. IMO Secretary-General Arsenio Dominguez said the IMO deplores the attacks on civilian merchant ships.", "kImp": "정박·하역 중인 선박의 거주구가 직접 피격됐다는 점은 항내 체류 자체가 더 이상 안전지대가 아님을 뜻한다. 선박관리자는 흑해·아조프해 기항 시 최소 인원 승선, 거주구 방호, 전쟁위험 담보와 선원 동의(consent) 및 보상 체계를 재점검해야 한다.", "eImp": "Accommodation blocks being hit while vessels are alongside discharging means port stays are no longer a safe zone. Managers calling Black Sea and Sea of Azov ports must revisit minimum manning on board, accommodation protection, war-risk cover, and crew consent and compensation frameworks.", "url": "https://maritime-executive.com/article/seafarers-killed-and-injured-as-russia-and-ukraine-intensify-strikes"}, {"code": "HR", "title": "Seafarer wellbeing must move beyond compliance", "src": "SAFETY4SEA", "date": "2026-07-09", "kSum": "노스스탠다드(NorthStandard)의 팟캐스트에서 스텔라 마리스(Stella Maris)와 국제선원선교회(The Mission to Seafarers) 소속 채플린들은 선박 방문 시 가장 자주 접하는 문제로 '피로'를 꼽았고, 이를 복지가 아닌 운항 안전 문제로 규정했다. 루스 캠벨(Ruth Campbell)은 9개월에서 6개월로 계약기간이 단축된 변화를 환영하며 '6개월 계약은 웰빙에 실질적 차이를 만든다'고 말했다. 상륙휴가에 대해서는 허가는 받지만 너무 지쳐 나가지 못하는 선원이 많아, 허가가 아닌 업무량과 일정이 관건이라고 지적했다.", "eSum": "In the first episode of NorthStandard's Alongside Future Thinking podcast, chaplains Steve Willows of Stella Maris and Ruth Campbell of The Mission to Seafarers identified fatigue as the issue they encounter most often on ship visits, framing it as an operational safety issue rather than a welfare nicety. Campbell said economic motivation dominates and welcomed the shift from nine-month to six-month contracts: 'Six-month contracts really do make a difference to their wellbeing.' On connectivity, reliable internet delivers major wellbeing benefits but has made crew messes noticeably quieter as seafarers retreat to cabins, so owners should pair it with gyms, film nights and revitalised communal spaces. Crucially, many seafarers are permitted ashore but are simply too exhausted to go, so improving shore leave means tackling workload and schedules, not just permission.", "kImp": "'상륙휴가 허가율'을 복지 지표로 삼는 관행이 무의미할 수 있음을 보여준다. 관리자는 허가 통계 대신 실제 상륙 실적과 업무량·항내 일정을 함께 관리해야 하며, 6개월 계약 전환은 유지율 개선의 검증된 지렛대다.", "eImp": "It shows that tracking 'shore leave granted' as a welfare KPI can be meaningless. Managers should measure actual shore leave taken alongside workload and port schedules, and the shift to six-month contracts is a proven lever for retention.", "url": "https://safety4sea.com/cm-seafarer-wellbeing-must-move-beyond-compliance/"}, {"code": "HR", "title": "IMO Calls for Release of Three Ships Hijacked by Somali Pirates", "src": "The Maritime Executive", "date": "2026-07-06", "kSum": "IMO는 소말리아 해적에게 억류된 선원들의 건강이 심각하게 악화되고 있다며 석방을 촉구했다. 4월 24일 피랍된 유조선 아너 25(Honour 25)호 선장은 선원 17명 전원이 생존해 있으나 5명(선장 포함)이 건강 문제를 겪고 있고, 쌀로만 연명하며 안전한 식수가 떨어졌다고 보고했다. 선원은 인도네시아·파키스탄·인도·미얀마 국적이며, 스워드(Sward)호와 에우레카(Eureka)호 선원들도 여전히 억류 중이다.", "eSum": "The IMO says it is increasingly concerned over dozens of seafarers held for ransom by Somali pirates, several suffering significant health setbacks. Via the Djibouti Code of Conduct/Jeddah Amendment, the master of the hijacked tanker Honour 25, boarded and seized on 24 April, reports all 17 crew are alive but five including the master have health problems, the crew is surviving on rice, and they are out of safe drinking water. Pirate rivalry adds risk, with a competing pirate action group approaching the vessel and the pirates aboard opening fire to drive them off. 'Behind every piracy incident are innocent seafarers enduring fear, deprivation, uncertainty and prolonged psychological trauma,' the committee wrote; the crew comprises Indonesian, Pakistani, Indian and Burmese nationals, and the crews of the Sward and MV Eureka remain held. Analysts attribute the resurgence to anti-piracy patrols being diverted to the Red Sea, leaving a Gulf of Aden gap.", "kImp": "장기 인질 상태의 선원에 대한 의료·심리 지원과 가족 커뮤니케이션은 선주·선박관리자의 실질적 책임 영역이며, 사후 복귀 프로그램까지 사전 설계돼야 한다. 아덴만 초계 공백이 확인된 만큼 통항 계획, 시타델 운용 훈련, 무장경비 배치 기준을 즉시 재검토할 필요가 있다.", "eImp": "Medical and psychological support and family communication for long-term hostages fall squarely on owners and managers, and post-release reintegration must be designed in advance. With the Gulf of Aden patrol gap now confirmed, transit planning, citadel drills and armed-guard criteria warrant immediate review.", "url": "https://maritime-executive.com/article/imo-calls-for-release-of-three-ships-hijacked-by-somali-pirates"}, {"code": "HR", "title": "2026 Crew Welfare Week: Seafarer wellbeing at the core of safer and more resilient shipping", "src": "SAFETY4SEA", "date": "2026-06-23", "kSum": "제6회 크루 웰페어 위크가 2026년 6월 23~25일 '선원의 날(Day of the Seafarer)'에 맞춰 열려 16개 세션에 50명 이상의 전문가가 참여했다. IMO 사무총장 아르세니오 도밍게스(Arsenio Dominguez)는 '모든 선박은 화물 이상을 싣고 있으며, 집에서 기다리는 가족이 있는 사람을 싣고 있다'고 개회사를 했다. 여성 선원 비중이 2% 미만이라는 점, 50세 이상 선원의 비만율이 70%에 달한다는 점, 그리고 노티컬 인스티튜트(The Nautical Institute)가 로이드선급재단(Lloyd's Register Foundation) 후원으로 STEER 프로젝트를 출범한 사실이 발표됐다.", "eSum": "The 6th annual Crew Welfare Week ran 23-25 June 2026 alongside the Day of the Seafarer, with more than 50 experts across 16 sessions. IMO Secretary-General Arsenio Dominguez opened with: 'Every ship carries more than cargo; it carries people with families waiting for them at home.' Data points included women making up less than 2% of the seafaring workforce, obesity reaching 70% among seafarers over 50, an estimated $168 million in annual industry savings from consolidating five key health data sources, and MACN's Help Desk resolving over 200 incidents. The Nautical Institute launched STEER, a two-and-a-half-year project backed by Lloyd's Register Foundation on how technology affects seafarer wellbeing. Capt. Konstantinos Karavasilis of UK P&I Club summed up: 'Ships run primarily on people, not fuel; human sustainability equals operational excellence and profitability.'", "kImp": "50세 이상 선원 비만율 70%는 승선 적합성(fitness) 판정과 의료후송·P&I 클레임 비용에 직접 연결되는 수치다. 선박관리자는 건강 데이터 통합과 STEER 같은 연구 결과를 인사·복지 정책 설계의 근거로 활용할 수 있으며, 여성 선원 2% 미만은 인력난 대응에서 미개척 공급원이 남아 있음을 뜻한다.", "eImp": "A 70% obesity rate among seafarers over 50 feeds directly into fitness-for-duty determinations and the cost of medical evacuations and P&I claims. Managers can use consolidated health data and research such as STEER as an evidence base for crewing and welfare policy, while women at under 2% of the workforce represent an untapped supply pool against the officer shortage.", "url": "https://safety4sea.com/2026-crew-welfare-week/"}, {"code": "HR", "title": "Crews of Dali and MSC Elsa 3 Ask Courts for Release", "src": "The Maritime Executive", "date": "2026-06-17", "kSum": "인도와 미국 볼티모어 법원이 해양사고의 '중요 참고인(material witness)'으로 선원을 얼마나 오래 억류할 수 있는지를 심리 중이다. 2025년 5월 인도 앞바다에서 침몰한 MSC 엘사3(MSC Elsa 3)호의 선장·1항사·기관장·2기사 4명은 여권 반환과 케랄라주 이탈 금지 명령 해제를 케랄라 고등법원에 청구했으며, 아무도 기소되지 않은 상태다. 2024년 3월 프랜시스 스콧 키 브리지(Francis Scott Key Bridge)를 붕괴시킨 달리(Dali)호 관련 인도·스리랑카 국적 선원 등 14명은 여전히 볼티모어 호텔에 머물고 있다.", "eSum": "Courts in India and Baltimore are weighing how long crew members can be detained as material witnesses to casualties, with lawyers arguing the men are 'marooned' and held illegally. Four MSC Elsa 3 seafarers - the captain, chief officer, chief engineer and second engineer - petitioned the Kerala High Court for return of their passports and lifting of an order confining them to Kerala; none have been charged. In Maryland, 14 crew members and Synergy employees connected to the Dali remain in Baltimore hotels, receiving salary, hotel and $48/day under a security agreement with the US government, with four having been in the US since the March 2024 allision. The criminal trial of Synergy and one technical supervisor was set for 4 October 2027, and the Dali's chief engineer was indicted under a deferred plea agreement.", "kImp": "선원 형사화(criminalisation)의 실제 비용을 보여주는 사례로, 사고 후 2년 이상 선원이 본국에 돌아가지 못하는 상황이 현실화됐다. 선박관리자는 사고 대응 계획에 선원 개별 법률대리인 선임과 장기 억류 시 급여·가족 지원 프로토콜을 사전에 포함해야 하며, 이는 채용 시장에서의 평판과도 직결된다.", "eImp": "This shows the real cost of seafarer criminalisation, with crew unable to return home more than two years after a casualty. Emergency response plans should pre-provide for independent legal counsel for each seafarer and a protocol covering pay and family support during prolonged detention - a factor that also shapes reputation in the recruitment market.", "url": "https://maritime-executive.com/article/crews-of-dali-and-msc-elsa-3-ask-courts-for-release"}]}, {"code": "HSEQ", "type": "news", "kTitle": "Section 10. HSEQ·손해방지", "eTitle": "Section 10. HSEQ", "items": [{"code": "HSEQ", "title": "AIS-assisted collisions: The risks of over-reliance", "src": "Gard", "date": "2026-07-14", "kSum": "가드(Gard)의 손실예방 담당자는 선박자동식별장치(AIS)에 대한 과도한 의존이 충돌 사고의 반복적 원인이 되고 있다고 경고한다. 2018년 동중국해 유조선·벌크선 충돌(32명 사망) 등 4건의 사례에서 당직자가 시각 견시와 체계적 레이더 작도를 생략하고 AIS 표시 정보만으로 충돌 위험을 판단한 정황이 확인됐다. AIS는 연결된 센서의 정확도에 좌우되며, 어선 등 일부 선박은 AIS를 작동하지 않거나 수동 모드로 운항한다.", "eSum": "Gard's loss prevention team warns that over-reliance on AIS is a recurring factor in collisions rather than a safeguard against them. Four case studies — including the 2018 East China Sea tanker/bulker collision that killed 32 — show bridge teams assessing collision risk from AIS-derived CPA/TCPA alone while omitting visual lookout and systematic radar plotting. AIS accuracy depends on its connected sensors, and not every vessel transmits: fishing vessels and navy ships may be absent or in passive mode.", "kImp": "HSEQ 및 안전관리 담당자는 안전관리체제(SMS), 선장 상시명령서(Standing Orders) 및 야간명령서에 '가용한 모든 수단에 의한 적절한 견시' 요구를 명시적으로 강화해야 한다. 지정학적 분쟁 해역의 GPS 교란이 AIS 데이터 신뢰도를 추가로 훼손하고 있으므로, 레이더 작도와 수동 선위측정 등 전통적 항해술 교육을 항해사 대상 온보드 훈련 항목으로 재편성할 필요가 있다.", "eImp": "HSEQ managers should explicitly reinforce 'proper lookout by all available means' in the SMS, master's standing orders and night orders, and audit whether bridge teams actually plot radar targets rather than reading AIS off the ECDIS. With GPS interference in conflict zones further degrading AIS reliability, onboard training should restore systematic radar observation, radar overlay cross-checks and manual position fixing as assessed competencies.", "url": "https://gard.no/en/insights/ais-assisted-collisions-overreliance-risk/"}, {"code": "HSEQ", "title": "Liquid Cargoes - Challenges and Prevention of Cargo Contamination (Risk Alert 140)", "src": "Steamship Mutual", "date": "2026-07-07", "kSum": "스팀십뮤추얼(Steamship Mutual)이 액체화물 오염 및 규격미달(off-specification) 클레임을 다룬 리스크 얼럿 140호를 발간했다. 부적절한 탱크 클리닝, 이전 화물로 인한 오염, 적·양하 중 운전 오류, 샘플링·시험 결과를 둘러싼 이견 등 사소해 보이는 문제가 분쟁·지연·대규모 손실로 확대되는 경로를 분석했다. 얼럿은 효과적인 문서화, 견고한 샘플링 관행, 적시의 증거 보전이 예방과 방어 모두에 핵심이라고 강조한다.", "eSum": "Steamship Mutual has issued Risk Alert 140 examining the most common causes of off-specification liquid cargo claims. It traces how seemingly minor issues — inadequate tank cleaning, contamination from previous cargoes, operational errors during loading or discharge, and disagreements over sampling and testing results — escalate into disputes, delays and significant financial losses. The alert stresses effective documentation, robust sampling practices and timely evidence preservation, both to prevent incidents and to defend potential claims.", "kImp": "액체화물 운송 선대를 관리하는 HSEQ 담당자는 탱크 클리닝 절차와 이전 화물 이력(cargo history) 검증을 SMS 내 명확한 점검항목으로 편성하고, 샘플 채취·봉인·보관 체계를 표준화해야 한다. 화물 품질 분쟁은 발생 후 증거 확보가 사실상 불가능하므로, 선상에서의 즉시 증거 보전 훈련이 클레임 방어력을 좌우한다.", "eImp": "For HSEQ teams managing tanker fleets, tank cleaning procedures and previous-cargo history verification should be explicit SMS checkpoints, with standardised sampling, sealing and retention regimes. Because cargo quality disputes are nearly impossible to defend once evidence is lost, drilling crews on immediate evidence preservation is what determines the outcome of a claim.", "url": "https://www.steamshipmutual.com/publications/articles/liquid-cargoes-challenges-and-prevention-cargo-contamination"}, {"code": "HSEQ", "title": "Beyond the Inspection: Rethinking Port State Control (Risk Alert 139)", "src": "Steamship Mutual", "date": "2026-06-30", "kSum": "스팀십뮤추얼(Steamship Mutual)이 항만국통제(PSC) 검사를 단순 적합성 확인 수단이 아닌 선제적 위험관리 도구로 활용하는 방안을 다룬 리스크 얼럿 139호를 발간했다. PSC 지적사항은 선박의 실제 상태, 정비 및 선내 관리체계의 실효성, 안전절차의 실질적 이행 수준을 보여주는 유용한 지표이며, 반복되는 결함과 검사 추세는 사고·운항 중단·클레임으로 이어지기 전 근본 문제를 드러낼 수 있다. 얼럿은 검사 결과 분석, 근본 원인 해결, 교훈 공유를 통한 지속적 개선을 권고한다.", "eSum": "Steamship Mutual's Risk Alert 139 argues that PSC inspections should be used as a proactive risk management tool rather than solely a means of verifying compliance. PSC findings offer insight into a vessel's condition, the effectiveness of maintenance and onboard management systems, and how safety procedures are actually implemented; recurring deficiencies and inspection trends can surface underlying issues before they cause incidents, operational disruption or claims. The alert recommends analysing inspection outcomes, addressing root causes and sharing lessons learned to drive continuous improvement across the fleet.", "kImp": "HSEQ 관리자는 PSC 결과를 선박별 단발성 시정조치로 종결하지 말고 선대 전체의 결함 추세를 데이터화해 SMS 개선과 내부심사 계획에 환류해야 한다. 동일 유형 지적이 반복된다면 이는 개별 선박 문제가 아니라 육상 관리·감독·정비계획의 구조적 결함 신호이며, 이를 조기에 포착하는 것이 억류와 클레임 예방의 지렛대가 된다.", "eImp": "Rather than closing PSC findings out ship-by-ship, HSEQ managers should aggregate deficiency trends across the fleet and feed them back into SMS revisions and internal audit planning. Repeat findings of the same type signal a structural weakness in shore-side supervision, maintenance planning or oversight rather than a one-off vessel issue — catching that early is what prevents detentions and claims.", "url": "https://www.steamshipmutual.com/publications/articles/beyond-inspection-rethinking-port-state-control"}, {"code": "HSEQ", "title": "ABS: Manual rescue boat davits raise PSC compliance concerns", "src": "SAFETY4SEA", "date": "2026-07-13", "kSum": "미국선급(ABS)이 저장식 기계동력 없이 전적으로 수동 조작에 의존하는 구조정(rescue boat) 진수장치를 갖춘 화물선을 대상으로 지침을 발행했다. 최근 유럽 항만의 PSC 검사에서 2008년 12월 기공된 컨테이너선이 결함코드 11113(구조정 진수장치)을 지적받았는데, 다비트를 저장동력·중력으로 선외 선회할 수 없고 구조정 내부에서 진수를 작동할 수 없으며 기국의 대체설계 승인도 제시하지 못했다. IMO 결의 MSC.459(101)의 수동 진수 허용 예외는 2024년 1월 1일 이후 설치된 구조정에만 적용되어 소급되지 않는다.", "eSum": "ABS has issued guidance for cargo ships whose rescue boat launching appliances rely entirely on manual operation without stored mechanical power. At a recent PSC inspection in a European port, a container ship (keel laid December 2008) received deficiency Code 11113 because the davit could not be slewed out using stored mechanical power or gravity, launching could not be actuated from within the rescue boat, and no flag State acceptance of the alternative arrangement was on board. The IMO Resolution MSC.459(101) exemption permitting manual launching appliances for rescue boats up to 700 kg applies only to boats installed on or after 1 January 2024 and is not retrospective.", "kImp": "HSEQ 관리자는 2024년 이전 설치된 수동식 구조정 진수장치를 보유한 선박에 대해 SOLAS 제I/5조(동등물)에 따른 기국 행정청의 공식 수락 증빙을 확보해 본선에 비치해야 한다. 장치가 실질적으로 안전하고 오랫동안 인정돼 왔더라도 서면 승인이 없으면 억류성 지적으로 이어질 수 있으므로, 선대 전반의 구조정 진수 방식 인벤토리 조사와 기국 조회가 시급하다.", "eImp": "HSEQ managers should audit the fleet for pre-2024 manual rescue boat launching arrangements and obtain formal flag Administration acceptance under SOLAS regulation I/5, keeping documentary evidence on board. An arrangement that is safe, functional and long-accepted in practice can still generate a detainable deficiency without that written approval, so a fleet-wide inventory and flag State enquiry is the immediate action.", "url": "https://safety4sea.com/abs-manual-rescue-boat-davits-raise-psc-compliance-concerns/"}, {"code": "HSEQ", "title": "BSEE highlights inspection gaps behind offshore crane failure", "src": "SAFETY4SEA", "date": "2026-07-09", "kSum": "미국 안전환경집행국(BSEE)이 해양플랫폼 해체 및 잠수 작업 중이던 리프트보트에서 발생한 크레인 사고를 조사했다. 붐 끝단 고정점에서 이탈한 A2B(anti-two-block) 추가 패스트라인 케이블을 타고 미끄러져 내려와 볼의 웨지 소켓을 강타했고, 소켓 진입부에서 와이어로프가 파단되면서 볼과 추가 약 12피트 아래 갑판으로 추락했다. 인근에서 작업 중이던 잠수사가 피하려 몸을 돌리는 순간 반동한 와이어로프에 우측 몸통을 맞아 경상을 입었다.", "eSum": "BSEE investigated a crane incident aboard a lift boat conducting decommissioning and diving operations at an offshore platform. The crane's anti-two-block (A2B) weight detached from its anchor point at the boom tip, slid down the fast line cable and struck the fast line ball's wedge socket, causing the wire rope to fail at the socket entry; the ball and detached weight fell about 12 feet to the deck. A diver working nearby saw the falling components and turned away, but was struck on the right side of the torso by the recoiling wire rope, sustaining minor injuries. BSEE stresses greater inspection awareness of ageing, worn or neglected crane components — brake systems, sheaves, bearings and wire ropes.", "kImp": "양중작업(lifting operations)을 관리하는 HSEQ 담당자는 크레인 점검 범위를 주요 구조물뿐 아니라 A2B 추·고정점·웨지 소켓·쉬브·베어링 등 소형 부속까지 확대해야 한다. 이 사고는 작은 부품 하나의 이탈이 와이어로프 파단과 인명 사고로 직결됨을 보여주므로, 모든 양중작업에 대한 철저한 작업안전분석(JSA)과 낙하물 위험구역(drop zone) 출입통제가 필수적이다.", "eImp": "HSEQ managers overseeing lifting operations should widen crane inspection scope beyond primary structure to small fittings — A2B weights, anchor points, wedge sockets, sheaves and bearings. The incident shows how one detached component cascades into wire rope failure and personnel injury, making thorough job safety analysis for every lift and strict drop-zone exclusion around suspended loads non-negotiable controls.", "url": "https://safety4sea.com/bsee-highlights-inspection-gaps-behind-offshore-crane-failure/"}, {"code": "HSEQ", "title": "Allianz Safety and Shipping Review 2026", "src": "IIMS", "date": "2026-06-25", "kSum": "알리안츠(Allianz)의 2026년 해운 안전 리뷰가 발간됐다. 2025년 100GT 이상 선박의 보고된 사고는 2,818건으로 전년(3,353건) 대비 약 16% 감소했고, 지난 10년간 전손은 905척으로 2021~2025년 연평균 70척까지 줄어 안전 규제와 선박 설계·기술 개선의 효과를 보여준다. 다만 사고 원인 1위는 기관 손상·고장(1,505건)이었고 충돌(260건), 화재·폭발(218건)이 뒤를 이었으며, 대형선 화재는 2025년 200건 이상으로 10년 내 두 번째로 많았다.", "eSum": "The Allianz Safety and Shipping Review 2026 reports 2,818 shipping incidents on vessels over 100GT in 2025, down around 16% from 3,353 in 2024, with total losses over the past decade at 905 and the 2021–2025 average down to 70 a year — reflecting the effect of regulation, improved design and risk management. Machinery damage or failure remained the leading cause of incidents (1,505), followed by collision (260) and fire/explosion (218). Fires on large vessels topped 200 incidents in 2025, the second highest total of the decade, with at least nine total losses.", "kImp": "HSEQ 관리자에게 이 데이터는 '전손은 줄었지만 기관 손상과 화재라는 전통적 리스크는 그대로'라는 메시지를 준다. 특히 대형 컨테이너선·자동차운반선 화재와 기관실 화재 예방(연료 누출, 고온부 차폐, 화재탐지 시스템 시험)을 선대 위험관리 최우선 순위로 두어야 하며, 선박 대형화에 따른 공동해손(General Average) 클레임 확대는 단일 사고의 재무적 파급을 급격히 키운다.", "eImp": "For HSEQ managers the message is that while total losses fall, the traditional risks — machinery damage and fire — have not. Engine-room and large-vessel fire prevention (fuel leaks, hot-surface shielding, fire detection testing) should stay at the top of fleet risk priorities, and the rise in General Average claims driven by ever-larger vessels means a single fire can now carry far heavier financial consequences.", "url": "https://www.iims.org.uk/allianz-safety-and-shipping-review-2026/"}]}, {"code": "KR", "type": "news", "kTitle": "Section 11. 한국 해운시장", "eTitle": "Section 11. Korean Shipping Market", "items": [{"code": "KR", "title": "HMM, 美 캘리포니아-한국항로서 오렌지 수송 4년 연속 1위", "src": "코리아쉬핑가제트", "date": "2026-07-15", "kSum": "HMM은 올해 한국으로 수입된 미국 캘리포니아산 오렌지 가운데 42%인 3060TEU를 운송해 4년 연속 이 분야 1위를 기록했다고 15일 밝혔다. 미국 해운전문지 저널오브커머스(JOC)의 피어스 데이터에 따른 것으로, 2023년 25% 점유율 이후 지속적으로 비중을 높여왔다. 리퍼(냉동·냉장) 컨테이너 운송 역량이 실적을 뒷받침했다.", "eSum": "HMM said on 15 July that it carried 42% (3,060 TEU) of all California oranges imported into Korea this year, ranking first for a fourth consecutive year, according to JOC Piers Data. Its share has risen steadily from 25% in 2023, underpinned by its reefer container capability.", "kImp": "리퍼 화물은 온도 관리 실패 시 클레임 리스크가 큰 고부가 화물로, 선박관리자 입장에서는 리퍼 플러그 용량·냉동 컨테이너 모니터링·발전기 부하 관리의 중요성이 커진다. 국적선사의 리퍼 점유율 확대는 관련 선박의 정비·예비품 계획에 직접 영향을 준다.", "eImp": "Reefer cargo is high-value and carries significant claim exposure if temperature control fails. Growing reefer share means ship managers must pay closer attention to reefer plug capacity, container monitoring and generator load planning, with direct knock-on effects for maintenance and spares planning.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147630"}, {"code": "KR", "title": "전세계 항만 효율성 하락세…부산항은 성장곡선", "src": "코리아쉬핑가제트", "date": "2026-07-16", "kSum": "세계은행과 S&P 글로벌마켓인텔리전스가 발표한 2025년 항만효율성지수(CPPI)에 따르면 지정학적 요인으로 세계 컨테이너항만의 운영 효율성이 전반적으로 악화됐다. 반면 우리나라 부산항은 성과를 끌어올리며 세계 상위권을 유지했다. 선전항 등 물동량 상위 항만들의 효율성 지표는 뒷걸음질쳤다.", "eSum": "According to the 2025 Container Port Performance Index (CPPI) from the World Bank and S&P Global Market Intelligence, global container terminal efficiency deteriorated on geopolitical factors. Busan, however, improved its score and held a top global ranking, while several high-volume ports such as Shenzhen slipped.", "kImp": "항만 효율성 저하는 곧 체선·대기시간 증가와 스케줄 신뢰도 하락을 뜻하며, 선박관리자의 입·출항 계획, 벙커 소모, 선원 교대 일정에 직접 영향을 준다. 부산항의 상대적 우위는 환적 및 선용품·수리 계획 수립 시 유리한 조건이 된다.", "eImp": "Falling port efficiency translates into longer waiting times and weaker schedule reliability, directly affecting port call planning, bunker consumption and crew change scheduling. Busan's relative strength is a favourable factor when planning transhipment, stores supply and repairs.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147592"}, {"code": "KR", "title": "해수부 북극항로추진본부장에 이수호 국장", "src": "코리아쉬핑가제트", "date": "2026-07-15", "kSum": "해양수산부는 7월15일부로 신임 북극항로추진본부장(실장급)에 이수호 해사안전국장을 임명했다. 이 본부장은 행정고시 40회 출신으로 해수부 항만국장, 주영국대사관 겸 IMO 대표부 공사참사관, 해사안전국장 등을 역임했다. 남재헌 차관의 영전으로 공석이 된 자리를 맡아 북극항로 추진정책과 국제협력, 관련 산업 육성 업무를 총괄한다.", "eSum": "Korea's Ministry of Oceans and Fisheries appointed Lee Su-ho, previously Director-General of Maritime Safety, as head of the Arctic Route Promotion Headquarters effective 15 July. A career official who has served as MOF port director-general and counsellor to the Korean mission to the IMO, he fills the post vacated by Vice Minister Nam Jae-heon and will oversee Arctic route policy, international cooperation and industry development.", "kImp": "북극항로 정책 총괄자가 해사안전국장 출신이라는 점은 향후 극지 운항 안전기준(폴라코드), 선급·검사 요건이 정책의 중심에 놓일 가능성을 시사한다. 북극항로 취항을 검토하는 선사·선박관리사는 빙급 선박 사양, 선원 극지 교육 요건 변화를 선제 점검할 필요가 있다.", "eImp": "Placing a former maritime safety director-general in charge of Arctic route policy suggests polar navigation safety standards (Polar Code), class and survey requirements will be central to the agenda. Owners and managers considering Arctic transits should review ice-class specifications and polar crew training requirements early.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147624"}, {"code": "KR", "title": "HD현대삼호, VLAC 3척 수주", "src": "한국해운신문", "date": "2026-07-15", "kSum": "HD현대삼호가 7월 10일 유럽 소재 선주와 9만cbm급 초대형 암모니아 운반선(VLAC) 3척을 척당 1억2100만 달러, 총 3억6300만 달러(약 5456억원)에 건조하는 계약을 체결했다. 인도 시한은 2030년 5월말까지다. 발주처는 공개되지 않았으나 신조 브로커들은 튀르키예 에너지·해운 기업 치네르 그룹으로 보고 있으며, 이 그룹은 지난 5월에도 7억1700만 달러 규모의 VLAC 6척을 발주한 바 있다.", "eSum": "HD Hyundai Samho signed a contract on 10 July with a European owner for three 90,000 cbm Very Large Ammonia Carriers (VLACs) at USD 121 million each, totalling USD 363 million (about KRW 545.6 billion), for delivery by end-May 2030. The buyer was not disclosed, but newbuilding brokers point to Turkey's Ciner Group, which ordered six VLACs worth USD 717 million in May.", "kImp": "암모니아 운반선 선대 확대는 독성 화물 취급 역량이 선박관리의 새로운 핵심 역량이 됨을 의미한다. 암모니아 누출 대응 절차, 개인보호장비, 화물 취급 선원 자격·훈련 체계를 지금부터 정비해야 인도 시점에 대응할 수 있다.", "eImp": "A growing ammonia carrier orderbook makes toxic cargo handling a core ship management competence. Managers need to build ammonia release response procedures, PPE regimes and cargo crew certification and training well ahead of delivery.", "url": "http://www.maritimepress.co.kr/news/articleView.html?idxno=332176"}, {"code": "KR", "title": "\"청해부대, 전쟁시 국적선 호위해야\"", "src": "한국해운신문", "date": "2026-07-16", "kSum": "고려대 김인현 명예교수는 7월 14일 한국해군과 최종현학술원이 공동 개최한 '바다가 흔들리면 국가가 흔들린다' 세미나에서 홍해사태·중동전쟁과 같은 전시에 우리나라 국적선이 안전하게 운항할 수 있도록 청해부대의 임무를 확대해 국적선 호위가 가능하도록 해야 한다고 제안했다. 유재준 해군대령은 '한국의 전략적 자율성과 해운의 역할'을 주제로 발표하며 국익 중심으로 변화한 미국이 동맹국들의 역할 확대와 자율적 방위역량 강화를 요구하고 있다고 지적했다.", "eSum": "At a 14 July seminar co-hosted by the ROK Navy and the Chey Institute, Prof. Emeritus Kim In-hyeon of Korea University proposed expanding the mandate of the Cheonghae naval unit so it can escort Korean-flag vessels during wartime, citing the Red Sea crisis and the Middle East conflict. Navy Captain Yoo Jae-jun presented on Korea's strategic autonomy and the role of shipping, noting that a more interest-driven United States is pressing allies to expand their roles and strengthen autonomous defence capability.", "kImp": "호르무즈·홍해 등 고위험 해역 통항 시 국가 차원의 호위 제공 여부는 선박관리자의 항로 선택, 전쟁보험료, 선원 위험수당 및 승선 거부 대응에 직결된다. 정책 변화 가능성을 모니터링해 고위험 해역 운항 절차에 반영해야 한다.", "eImp": "Whether state naval escort is available for transits through Hormuz, the Red Sea and other high-risk areas directly affects routing decisions, war risk premiums, crew hazard pay and handling of refusals to sail. Managers should track this policy debate and reflect it in high-risk area transit procedures.", "url": "http://www.maritimepress.co.kr/news/articleView.html?idxno=332182"}, {"code": "KR", "title": "KRISO 개발 SMR 컨선 설계, AIP 획득", "src": "한국해운신문", "date": "2026-07-16", "kSum": "선박해양플랜트연구소(KRISO)는 소형모듈원자로(SMR)를 적용한 1만5000TEU급 컨테이너선 개념설계에 대해 미국선급협회(ABS)로부터 기본승인(AIP)을 획득했다고 16일 밝혔다. AIP는 선급기관이 새로운 기술이나 설계안에 대해 관련 규정과 안전 기준을 바탕으로 기술적 구현 가능성과 안전성을 검토·확인하는 절차다.", "eSum": "The Korea Research Institute of Ships and Ocean Engineering (KRISO) announced on 16 July that its concept design for a 15,000 TEU containership powered by a Small Modular Reactor (SMR) received Approval in Principle (AIP) from the American Bureau of Shipping (ABS). AIP is a class process confirming the technical feasibility and safety of a novel technology or design against applicable rules and safety standards.", "kImp": "원자력 추진 상선이 개념 단계를 넘어 선급 검증 단계로 진입하고 있음을 보여준다. 장기적으로 선원 자격·방사선 안전 교육, 기항지 수용 여부, 보험·책임 체계 등 선박관리 전반의 재설계가 필요해질 사안으로 조기 추적이 필요하다.", "eImp": "This shows nuclear propulsion for merchant ships moving beyond concept into class verification. Longer term it implies a redesign of ship management fundamentals — crew certification and radiation safety training, port acceptance, and insurance and liability frameworks — and warrants early tracking.", "url": "http://www.maritimepress.co.kr/news/articleView.html?idxno=332184"}, {"code": "KR", "title": "미·이란 전쟁 재개에 걸프만 원유 수송 급감…산유국 감산 압박", "src": "더구루", "date": "2026-07-16", "kSum": "블룸버그 통신에 따르면 15일(현지시간) 사우디의 페르시아만 주요 원유 수출시설에 접안한 유조선은 한 척에 그쳤고, 이라크·이란의 원유 선적도 큰 폭으로 감소했다. 미·이란 휴전 합의 무산 후 호르무즈 해협에서 상선 공격이 이어져 최소 9척이 피해를 봤으며 이 중 5척이 초대형 원유운반선(VLCC)이었다. 국제해사기구(IMO)는 호르무즈 해협이 선박이 통항하기에 지나치게 위험한 상태라고 경고했고, AIS를 끄고 운항하는 '다크 해운'도 늘고 있다.", "eSum": "Bloomberg reported that as of 15 July only one tanker was berthed at Saudi Arabia's main Persian Gulf crude export terminals, with Iraqi and Iranian liftings also sharply down. Since the collapse of the US-Iran ceasefire, at least nine merchant ships have been attacked in the Strait of Hormuz, five of them VLCCs. The IMO warned the strait is too dangerous for navigation, and 'dark shipping' with AIS switched off is increasing.", "kImp": "호르무즈 통항 자체가 IMO 경고 수준의 위험으로 격상된 상황으로, 탱커 운항사는 항로 회피, 전쟁보험 재산정, 선원 승선 동의 확보, AIS 운용 정책 등 즉각적 의사결정이 필요하다. 다크 해운 확산은 충돌·구조 리스크와 P&I·제재 리스크를 동시에 키운다.", "eImp": "With the IMO warning that Hormuz transits are excessively dangerous, tanker operators face immediate decisions on routing avoidance, war risk repricing, obtaining crew consent to sail, and AIS policy. The spread of dark shipping simultaneously raises collision and rescue risk alongside P&I and sanctions exposure.", "url": "https://www.theguru.co.kr/news/article.html?no=104526"}, {"code": "KR", "title": "'트럼프 측근' 前 미 해군성 장관 \"한화, 미국 조선소 추가 인수 추진...적극 지원\"", "src": "더구루", "date": "2026-07-16", "kSum": "존 펠런 전 미국 해군성 장관이 한화와의 협력 확대를 예고하며, 한화가 미국 내 추가 투자를 추진하고 조선소 인수를 검토하고 있다고 밝혔다. 이를 통해 한화 필리조선소의 생산능력 한계를 극복하고 향후 미국 수요에 대응할 것으로 전망된다.", "eSum": "Former US Secretary of the Navy John Phelan signalled expanded cooperation with Hanwha, saying the group is pursuing additional US investment and reviewing further shipyard acquisitions. The move is seen as a way to overcome capacity constraints at Hanwha Philly Shipyard and meet future US demand.", "kImp": "한화의 미국 조선소 확장은 한국 선박관리 인력과 표준이 미국 야드로 이전될 가능성을 뜻하며, 신조 감독·검사 체계의 이원화 관리가 과제로 떠오른다. 미국 건조 선박 증가는 존스법·미국 선원 규정 등 별도 운영 요건 검토를 요구한다.", "eImp": "Hanwha's US yard expansion implies Korean ship management personnel and standards being transferred to US yards, raising the challenge of managing newbuilding supervision and survey across two jurisdictions. More US-built tonnage also requires separate review of Jones Act and US crewing requirements.", "url": "https://www.theguru.co.kr/news/article.html?no=104503"}, {"code": "KR", "title": "HD현대중·인도 코친조선소 프로젝트 합류 가능성... 타타그룹, '1조4000억' 메가 투자 예고", "src": "더구루", "date": "2026-07-16", "kSum": "인도 최대 기업 타타 그룹이 남부 케랄라주에 10억 달러(약 1조4000억원) 규모의 조선업 투자를 추진하면서, 현지 국영 코친 조선소와 파트너십을 맺고 있는 HD현대중공업의 프로젝트 합류 및 수혜 가능성에 업계의 이목이 집중되고 있다. 인도가 국가 차원에서 조선업 및 해군력 강화를 추진하는 가운데 한국 기업과의 기술 협력 시너지가 가속화될 것이라는 관측이 나온다.", "eSum": "India's largest conglomerate, Tata Group, is pursuing a USD 1 billion (about KRW 1.4 trillion) shipbuilding investment in the southern state of Kerala, drawing industry attention to whether HD Hyundai Heavy Industries — already partnered with state-owned Cochin Shipyard — could join and benefit from the project. With India pushing shipbuilding and naval capability at national level, technology cooperation with Korean firms is expected to accelerate.", "kImp": "인도의 조선 역량 확대는 중장기적으로 신조·수리 야드 선택지를 넓히고 드라이도크 확보 경쟁을 완화할 수 있다. 다만 신흥 야드의 품질·공정 관리 수준은 편차가 크므로 선박관리자는 감독 인력 배치와 검사 기준 강화를 전제로 검토해야 한다.", "eImp": "India's expanding shipbuilding capacity could widen the choice of newbuilding and repair yards over the medium term and ease competition for drydock slots. However, quality and process control at emerging yards varies widely, so managers should factor in stronger site supervision and tighter inspection standards.", "url": "https://www.theguru.co.kr/news/article.html?no=104509"}]}, {"code": "INS", "type": "news", "kTitle": "Section 12. 해상보험 (H&M)", "eTitle": "Section 12. Marine Insurance (H&M)", "items": [{"code": "INS", "title": "New sanctions from US target Iran shipping", "src": "Insurance Marine News", "date": "2026-07-16", "kSum": "미국 재무부 해외자산통제국(OFAC)은 7월 14일 이란 해운과 관련된 50명 이상의 개인 등을 대상으로 신규 제재를 부과한다고 발표했다. 이란 해운 네트워크를 겨냥한 조치다.", "eSum": "The US Treasury's Office of Foreign Assets Control (OFAC) announced on 14 July that it was adding new sanctions targeting more than 50 individuals connected with Iranian shipping.", "kImp": "제재 대상 확대는 보험 담보의 제재 배제 조항(sanctions exclusion clause) 발동과 담보 실효 위험을 높인다. 선박관리자는 거래 상대방·화주·수하인에 대한 제재 스크리닝을 강화하고 담보 유지 여부를 보험자와 확인해야 한다.", "eImp": "An expanded sanctions list raises the risk that sanctions exclusion clauses are triggered and cover falls away. Ship managers should tighten screening of counterparties, shippers and consignees and confirm with underwriters that cover remains in place.", "url": "https://insurancemarinenews.com/insurance-marine-news/new-sanctions-from-us-target-iran-shipping/"}, {"code": "INS", "title": "Trump announces 20% fee on all cargo transited through Strait of Hormuz", "src": "Insurance Marine News", "date": "2026-07-14", "kSum": "트럼프(Trump) 미국 대통령이 소셜미디어를 통해 미국의 호르무즈 해협(Strait of Hormuz) 봉쇄를 복원하겠다고 밝히면서, 해협을 통과하는 모든 화물에 20% 수수료를 부과하겠다고 발표했다. 페르시아만 사태와 관련해 가장 이례적인 조치 중 하나로 평가된다.", "eSum": "US President Trump said on social media that he would reinstate a US blockade and impose a 20% fee on all cargo transiting the Strait of Hormuz. Insurance Marine News described it as one of the most bizarre developments in the Persian Gulf situation to date.", "kImp": "화물 통과 수수료와 봉쇄 복원은 적하보험(cargo insurance) 및 전쟁위험 담보 조건과 항해 채산성에 직접적인 영향을 준다. 선박관리자는 용선계약상 비용 부담 주체와 담보 범위 변경 가능성을 사전에 점검할 필요가 있다.", "eImp": "A cargo transit fee plus a reinstated blockade bears directly on cargo insurance and war risk terms as well as voyage economics. Ship managers should check who bears the cost under the charter and watch for changes in cover scope.", "url": "https://insurancemarinenews.com/insurance-marine-news/trump-announces-20-fee-on-all-cargo-transited-through-strait-of-hormuz/"}, {"code": "INS", "title": "Some war insurers advise shipowners to pause Hormuz voyages", "src": "Insurance Marine News", "date": "2026-07-10", "kSum": "일부 전쟁위험 인수업자(war underwriters)가 선사에 호르무즈 해협(Strait of Hormuz) 통항을 일시 중단할 것을 권고했다고 로이터(Reuters)가 보도했다. 다른 인수업자들은 담보 조건(policy terms)을 재검토 중인 것으로 전해졌다.", "eSum": "Some war underwriters have advised shipping companies to pause voyages through the Strait of Hormuz, while others are reviewing their policy terms, according to a Reuters report carried by Insurance Marine News.", "kImp": "전쟁위험 인수업자의 통항 중단 권고와 담보 조건 재검토는 호르무즈 통항 선박의 전쟁위험 보험 가입 가능 여부와 보험료에 직결된다. 선박관리자는 해당 구간 배선 전 전쟁위험 담보 유효성과 통지 의무를 재확인해야 한다.", "eImp": "Advice to pause transits and a review of policy terms directly affect whether war risk cover is available, and at what price, for ships routed via Hormuz. Ship managers should re-confirm war risk cover validity and notification duties before fixing voyages through the strait.", "url": "https://insurancemarinenews.com/insurance-marine-news/some-war-insurers-advise-shipowners-to-pause-hormuz-voyages/"}, {"code": "INS", "title": "Hormuz War-Risk Cover Climbs as Shipowners Pull Back", "src": "gCaptain (Bloomberg)", "date": "2026-07-09", "kSum": "런던 해상보험 시장에서 호르무즈 해협 통항 견적 요청이 눈에 띄게 줄었고, 일부 브로커는 보험료가 소폭 상승했다고 전했다. 마쉬(Marsh)의 마커스 베이커(Marcus Baker)는 요율이 분쟁 이전 1% 미만에서 현재 선가의 2~6% 수준으로 올랐다고 밝혔으며, 1억 달러 유조선 기준 최대 600만 달러에 해당한다. 윌리스(Willis Towers Watson)의 사이먼 록우드(Simon Lockwood)는 견적 요청은 줄었지만 조건은 여전히 제시 가능하다고 말했다.", "eSum": "London marine insurers report fewer inquiries for Strait of Hormuz transits, with some seeing the cost of cover rise, as US-Iran attacks resume. Marsh's Marcus Baker said rates have risen to between 2% and 6% of vessel value from a fraction of a percent pre-conflict - up to $6m for a $100m tanker - while Willis' Simon Lockwood said quote requests have dropped off but terms remain available.", "kImp": "전쟁위험 보험료가 선가의 2~6%에 이르면 호르무즈 1회 통항 비용이 수백만 달러 단위로 늘어나 항해 채산성이 근본적으로 달라진다. 선박관리자는 용선주와의 추가보험료(AP) 부담 협의와 무사고 할인(no-claim discount) 적용 여부를 확인해야 한다.", "eImp": "At 2-6% of hull value, a single Hormuz transit can add millions of dollars, fundamentally changing voyage economics. Ship managers should settle additional premium (AP) allocation with charterers and confirm what no-claim discounts apply to headline rates.", "url": "https://gcaptain.com/hormuz-war-risk-cover-climbs-as-shipowners-pull-back/"}, {"code": "INS", "title": "El Niño risks cascading freight, energy and shipping disruption", "src": "Seatrade Maritime News", "date": "2026-07-08", "kSum": "TT클럽(TT Club)은 슈퍼 엘니뇨(El Niño) 가능성이 파나마 운하(Panama Canal) 수위 저하부터 에너지 가격 변동성, 공급업체 지연에 이르기까지 시스템 리스크를 배가시킬 수 있다고 경고했다. 화물·물류 보험자 관점에서 연쇄적 공급망 교란 위험을 지적한 분석이다.", "eSum": "TT Club warns that a potential super El Niño could multiply systemic risks for shipping, from Panama Canal water shortages to energy volatility and supplier delays. The cargo and logistics insurer flags the cascading nature of the resulting supply chain disruption.", "kImp": "기후 이벤트로 인한 운하 통항 제한과 공급망 지연은 적하보험 클레임과 지연 관련 분쟁을 늘린다. 선박관리자는 배선 계획과 대체 항로 검토 시 화물 담보 조건 및 지연 면책 범위를 함께 점검할 필요가 있다.", "eImp": "Canal transit restrictions and supply chain delays driven by climate events tend to increase cargo claims and delay-related disputes. Ship managers should review cargo cover terms and delay exclusions alongside routing and contingency planning.", "url": "https://www.seatrade-maritime.com/insurance/el-ni-o-risks-cascading-freight-energy-and-shipping-disruption"}, {"code": "INS", "title": "Europe Targets Shadow Fleet Tankers Falsely Using Cameroon Flag, Sources Say", "src": "Insurance Journal (Reuters)", "date": "2026-07-06", "kSum": "EU는 6월 8일 지중해 해군 작전 이리니(Operation IRINI)의 권한을 확대해 러시아 그림자 선단(shadow fleet) 의심 선박을 정선·승선·검사·억류할 수 있게 했다. 카메룬(Cameroon)은 자국 기국이 부정 사용됐다며 39척을 등록에서 말소했고, 2026년 들어 프랑스·벨기에·영국·스웨덴 해군이 9척을 나포했다. EU는 7월 중 30척을 추가 지정하는 제재 패키지를 준비 중이다.", "eSum": "The EU expanded Operation IRINI's mandate on 8 June to stop, board, inspect and detain suspected Russian shadow fleet vessels, and Cameroon has de-listed 39 ships after finding its registry was fraudulently used. Nine tankers have been seized by European navies since the start of 2026, and a further EU package listing 30 more shadow fleet vessels could be adopted in July.", "kImp": "그림자 선단 선박은 통상 서방 보험이나 안전 증서가 없어 나포·억류 위험이 크고, 기국 사기 사례는 기국·보험 증서의 진위 확인 필요성을 부각한다. 선박관리자는 상대 선박과 STS 작업 시 기국·보험자 실재 여부를 검증해야 한다.", "eImp": "Shadow fleet vessels typically lack recognised Western insurance or safety certification, exposing them to boarding and detention, and the fraudulent flag cases highlight the need to verify registry and insurance certificates. Ship managers should validate flag and insurer authenticity when dealing with counterparty vessels or STS operations.", "url": "https://www.insurancejournal.com/news/international/2026/07/06/876251.htm"}, {"code": "INS", "title": "$125bn trapped by Hormuz overshadows improving ship safety record", "src": "Seatrade Maritime News", "date": "2026-06-24", "kSum": "알리안츠(Allianz)의 '해상 안전 및 해운 리뷰 2026(Safety and Shipping Review 2026)'에 따르면 6월 15일 기준 아라비아만에 1,150척, 선박·화물 합계 약 1,250억 달러가 발이 묶였다. 100총톤 이상 선박의 2025년 보고 사고는 2,818건으로 전년 3,353건 대비 16% 감소했고, 전손(total loss)은 43건으로 2021~2025년 연평균 70건을 밑돌았다. 알리안츠 해상선체 글로벌 상품책임자 유스투스 하인리히(Justus Heinrich)는 선체·기관 리스크의 클레임 비용이 계속 상승하고 있다고 밝혔다.", "eSum": "Allianz's Safety and Shipping Review 2026 estimates 1,150 cargo-carrying vessels worth around $125bn including cargo were trapped in the Arabian Gulf as of 15 June. Reported incidents on vessels over 100 gt fell 16% to 2,818 in 2025 from 3,353 in 2024, with 43 total losses - below the 2021-2025 average of 70 - while Allianz warns political risk is now a growing threat and hull and machinery claims costs continue to rise.", "kImp": "전손은 줄었지만 수리비 인플레이션, 공급망 교란, 숙련 인력 부족으로 선체·기관 클레임 비용은 오르고 있어 갱신 시 보험료 압박으로 작용한다. 걸프에 억류된 선박은 얕은 수심 장기 정박과 정비 일정 중단에 따른 별도 리스크에 노출된다.", "eImp": "Even with fewer total losses, repair cost inflation, supply chain disruption and skilled labour shortages are pushing hull and machinery claims costs up, which will feed into renewal pricing. Vessels stuck in the Gulf face specific risks from long periods stationary in shallow water and interrupted machinery maintenance schedules.", "url": "https://www.seatrade-maritime.com/insurance/-125bn-trapped-by-hormuz-overshadows-improving-ship-safety-record"}, {"code": "INS", "title": "Shipyard fire losses and blind spot underwriting still cannot see", "src": "Seatrade Maritime News", "date": "2026-06-22", "kSum": "지난 10년간 화재·폭발이 선박 전손의 16%를 차지했고 109척이 화재로 상실됐으며, 2024년 한 해에만 250건의 화재 사고가 발생해 전년 대비 20% 늘었다고 지적했다. 램테크(Ramtech)의 아론 와디아(Aron Wadhia)는 선박의 상시 화재탐지·소화 설비가 정지된 상태에서 화기 작업이 진행되는 '시스템 손상 구간(system impairment gap)'이 인수심사에서 제대로 반영되지 않는다고 주장했다. 해상보험 손해율이 70~80%로 높게 유지되는 상황에서 대형 화재 클레임을 흡수할 여력이 크지 않다고 덧붙였다.", "eSum": "Fire and explosion accounted for 16% of total vessel losses over the past decade, with 109 vessels lost to fire and 250 fire incidents recorded in 2024 alone, up 20% year on year. Ramtech's Aron Wadhia argues that the 'system impairment gap' - when a vessel's permanent fire detection and suppression systems are offline during repair or newbuild hot works - is not consistently captured by underwriting models, while marine loss ratios stay elevated at 70-80%.", "kImp": "수리·개조 중 상시 소화설비 정지 구간은 선체보험 대형 화재 클레임의 핵심 노출 구간으로, 인수업자의 관심이 커지고 있다. 선박관리자는 조선소 입거 시 화기작업 허가, 임시 화재탐지 설비, 화재 감시(fire watch) 체계를 보험자에게 입증할 수 있도록 관리해야 한다.", "eImp": "The window when permanent fire systems are offline during repair or conversion is a key exposure for large hull fire claims and is drawing underwriter attention. Ship managers should be able to evidence hot work permits, temporary fire detection and fire watch arrangements to underwriters during yard periods.", "url": "https://www.seatrade-maritime.com/accidents/shipyard-fire-losses-and-blind-spot-underwriting-still-cannot-see"}]}, {"code": "PNI", "type": "news", "kTitle": "Section 13. P&I 클럽", "eTitle": "Section 13. P&I Clubs", "items": [{"code": "PNI", "title": "Circular 12/26: Update on Club Merger and Acquisition Proposal", "src": "UK P&I Club", "date": "2026-07-13", "kSum": "UK P&I 클럽(UK P&I Club)이 회람 12/26을 통해 진행 중인 클럽 합병·인수(Merger and Acquisition) 제안에 관한 최신 진행 상황을 회원들에게 통지했습니다. 이번 회람은 해당 거래에 대한 클럽의 공식 회원 대상 업데이트입니다.", "eSum": "UK P&I Club issued Circular 12/26 updating members on the status of its ongoing club merger and acquisition proposal. The circular is the club's formal member-facing update on the transaction.", "kImp": "선박관리자 입장에서 클럽 합병은 향후 보험료 수준, 담보 조건, 클레임 처리 담당 조직, 그리고 국제그룹(International Group) 내 풀링 구조에 직접적인 영향을 줄 수 있으므로 갱신 전략 수립 시 반드시 확인해야 합니다.", "eImp": "For ship managers, a club merger can directly affect future premium levels, cover terms, claims-handling contacts and the club's position within the International Group pool, so it must be factored into renewal planning.", "url": "https://www.ukpandi.com/news-and-resources/circulars/article/circular-12/26-update-on-club-merger-and-acquisition-proposal/"}, {"code": "PNI", "title": "LNG - Alternative Fuel Spill Response Considerations", "src": "UK P&I Club", "date": "2026-07-15", "kSum": "UK P&I 클럽(UK P&I Club)이 LNG 등 대체연료 유출 사고 대응 시 고려해야 할 사항을 정리한 회원 안내 자료를 발행했습니다. 기존 유류 유출 대응 절차와 구별되는 LNG 특유의 대응 관점을 다룹니다.", "eSum": "UK P&I Club published guidance for members on spill response considerations specific to LNG and other alternative fuels, highlighting how the response differs from conventional oil spill procedures.", "kImp": "LNG 이중연료 선박을 운영하거나 발주한 선박관리자는 기존 SOPEP/SMPEP 기반 대응 계획이 대체연료 유출에 그대로 적용되지 않는다는 점을 인지하고 비상대응 절차와 선원 훈련을 보완해야 합니다.", "eImp": "Managers operating or ordering LNG dual-fuel tonnage should recognise that existing SOPEP/SMPEP-based response plans do not map cleanly onto alternative fuel releases, and update emergency procedures and crew training accordingly.", "url": "https://www.ukpandi.com/news-and-resources/news/article/lng-alternative-fuel-spill-response-considerations/"}, {"code": "PNI", "title": "United States Eases Sanctions on Iranian Petroleum Trade – Key Implications", "src": "UK P&I Club", "date": "2026-07-01", "kSum": "UK P&I 클럽(UK P&I Club)이 미국의 이란산 석유 거래 관련 제재 완화 조치와 그 주요 시사점을 정리한 회원 안내를 발행했습니다. 제재 환경 변화가 해운·에너지·무역에 미치는 영향을 다룹니다.", "eSum": "UK P&I Club published member guidance on the United States easing sanctions on Iranian petroleum trade and the key implications, covering what the change means for shipping, energy and trade.", "kImp": "제재 완화라 하더라도 P&I 담보는 제재 위반 시 즉시 소멸될 수 있으므로, 선박관리자는 완화 범위와 잔존 금지 사항을 정확히 파악하고 용선계약 제재 조항 및 항차 승인 절차를 재점검해야 합니다.", "eImp": "Even where sanctions are eased, P&I cover can fall away instantly on a breach, so managers must establish the precise scope of the relief and any residual prohibitions, and revisit charterparty sanctions clauses and voyage approval procedures.", "url": "https://www.ukpandi.com/news-and-resources/news/article/united-states-eases-sanctions-on-iranian-petroleum-trade-key-implications/"}, {"code": "PNI", "title": "Fire in the engine room due to auxiliary engine erosion plug failure", "src": "Skuld", "date": "2026-07-03", "kSum": "스쿨드(Skuld)가 보조엔진 이로전 플러그(erosion plug) 파손으로 발생한 기관실 화재 사례를 회원 대상 손실예방 자료로 발행했습니다. 해당 사례의 원인과 재발 방지 관점을 다룹니다.", "eSum": "Skuld published a member loss prevention item on an engine room fire caused by the failure of an auxiliary engine erosion plug, covering the cause and the prevention perspective.", "kImp": "기관실 화재는 P&I와 선체보험 양쪽에 걸친 고액 클레임으로 이어지므로, 선박관리자는 보조엔진 이로전 플러그 등 소모성 부품의 점검 주기를 PMS에 반영하고 기관부 승무원에게 해당 사례를 전파할 필요가 있습니다.", "eImp": "Engine room fires generate high-value claims across both P&I and hull cover, so managers should ensure erosion plugs and similar consumable components are captured in the PMS inspection cycle and circulate the case to engine crews.", "url": "https://www.skuld.com/topics/ship/safety/fire-in-the-engine-room-due-to-auxiliary-engine-erosion-plug-failure/"}, {"code": "PNI", "title": "UK Emission Trading Scheme for Maritime entering into force on 1 July 2026", "src": "Skuld", "date": "2026-07-02", "kSum": "스쿨드(Skuld)가 2026년 7월 1일부로 발효된 영국 배출권거래제(UK Emission Trading Scheme, UK ETS)의 해운 부문 적용에 관한 회원 안내를 발행했습니다. 신규 제도의 적용 개시 시점과 회원 유의사항을 다룹니다.", "eSum": "Skuld published member guidance on the UK Emission Trading Scheme for maritime, which entered into force on 1 July 2026, setting out the start of the regime and points for members to note.", "kImp": "UK ETS 적용 개시로 영국 기항 선박은 배출량 모니터링·배출권 확보 의무가 발생하며, 선박관리자는 용선계약상 ETS 비용 부담 주체와 데이터 제공 책임을 명확히 하지 않으면 분쟁과 FD&D 클레임에 노출될 수 있습니다.", "eImp": "With UK ETS now live, ships calling in the UK face monitoring and allowance surrender obligations, and managers who do not clarify who bears ETS costs and who supplies the data under the charterparty risk disputes and FD&D claims.", "url": "https://www.skuld.com/topics/environment/air-pollution/europe/uk-emission-trading-scheme-for-maritime-entering-into-force-on-1-july-2026/"}, {"code": "PNI", "title": "Crew Watch – June 2026", "src": "Britannia P&I Club", "date": "2026-07-14", "kSum": "브리타니아 P&I 클럽(Britannia P&I Club)이 2026년 6월호 크루 워치(Crew Watch)를 발행했습니다. 선원 관련 클레임과 인사·복지 이슈에 대한 정기 회원 안내 간행물입니다.", "eSum": "Britannia P&I Club published its June 2026 edition of Crew Watch, the club's regular member publication covering crew-related claims and personnel issues.", "kImp": "선원 상해·질병 클레임은 P&I 클레임 건수에서 큰 비중을 차지하므로, 선박관리자는 클럽이 짚는 최신 선원 이슈를 승선 전 교육과 PEME 절차에 반영해 클레임 빈도를 낮출 수 있습니다.", "eImp": "Crew injury and illness claims account for a large share of P&I claims by number, so managers can use the club's latest crew themes to sharpen pre-joining briefings and PEME procedures and reduce claims frequency.", "url": "https://britanniapandi.com/2026/07/crew-watch-june-2026/"}, {"code": "PNI", "title": "Britannia Europe – Solvency and Financial Condition Report (SFCR)", "src": "Britannia P&I Club", "date": "2026-07-14", "kSum": "브리타니아 P&I 클럽(Britannia P&I Club)이 유럽 법인인 브리타니아 유럽(Britannia Europe)의 지급여력 및 재무상태 보고서(SFCR)를 공시했습니다. 솔벤시 II(Solvency II) 체제에 따른 정기 공시 자료입니다.", "eSum": "Britannia P&I Club published the Solvency and Financial Condition Report (SFCR) for its European entity, Britannia Europe, as part of its regular Solvency II disclosure.", "kImp": "SFCR은 클럽의 지급여력과 재무 건전성을 보여주는 공개 자료로, 선박관리자와 선주는 갱신 협상이나 클럽 선정 시 클럽의 자본 여력과 추가 보험료(추가 콜) 위험을 판단하는 근거로 활용할 수 있습니다.", "eImp": "The SFCR is a public window into the club's solvency and financial strength, and owners and managers can use it when choosing a club or negotiating renewal to gauge capital headroom and the risk of supplementary calls.", "url": "https://britanniapandi.com/2026/07/solvency-and-financial-condition-report-sfcr-7/"}, {"code": "PNI", "title": "Demurrage Claims and the Pumping Warranty", "src": "Britannia P&I Club", "date": "2026-07-06", "kSum": "브리타니아 P&I 클럽(Britannia P&I Club)이 체선료(demurrage) 클레임과 펌핑 워런티(pumping warranty)의 관계를 다룬 회원 안내를 발행했습니다. 탱커 용선계약에서 자주 다투어지는 쟁점을 정리합니다.", "eSum": "Britannia P&I Club published member guidance on demurrage claims and the pumping warranty, addressing a frequently disputed issue in tanker charterparties.", "kImp": "펌핑 워런티 위반 여부는 체선료 정산 결과를 크게 좌우하므로, 탱커 관리자는 양하 중 압력 기록과 펌프 로그를 일관되게 남겨 FD&D 분쟁에서 방어 자료로 확보해 두어야 합니다.", "eImp": "Whether the pumping warranty was met often decides the demurrage outcome, so tanker managers should keep consistent discharge pressure records and pump logs as defensive evidence in FD&D disputes.", "url": "https://britanniapandi.com/2026/07/demurrage-claims-and-the-pumping-warranty/"}, {"code": "PNI", "title": "Circular No. 14/26 - OFAC Issues General License Authorizing Certain Transactions Involving Iranian-origin Oil and Petroleum Products", "src": "American P&I Club", "date": "2026-06-24", "kSum": "아메리칸 P&I 클럽(American P&I Club)이 회람 14/26을 통해 미국 재무부 해외자산통제국(OFAC)이 이란산 원유 및 석유제품 관련 특정 거래를 허용하는 일반허가(General License)를 발급했음을 회원들에게 통지했습니다.", "eSum": "The American P&I Club issued Circular No. 14/26 notifying members that OFAC has issued a General License authorizing certain transactions involving Iranian-origin oil and petroleum products.", "kImp": "일반허가는 허용 범위가 좁고 조건부인 경우가 많으므로, 선박관리자는 해당 항차가 허가 범위에 실제로 포함되는지 클럽·법률자문과 사전 확인하지 않으면 P&I 담보 상실과 제재 노출 위험을 안게 됩니다.", "eImp": "General Licences are typically narrow and conditional, so managers should confirm with the club and legal counsel that a given voyage actually falls within the authorisation, or risk loss of P&I cover and sanctions exposure.", "url": "https://www.american-club.com/files/files/cir_14_26.pdf"}]}, {"code": "VET", "type": "news", "kTitle": "Section 14. 베팅·검사", "eTitle": "Section 14. Vetting & Inspection", "items": [{"code": "VET", "title": "The Inspection Iceberg: What PSC Trends Reveal About Fleet Risk Beneath the Surface", "src": "RightShip", "date": "2026-07-14", "kSum": "라이트십(RightShip)이 2025년 전 세계 PSC 데이터 분석 결과를 공개했다. 32,470여 척을 대상으로 77,400건 이상의 검사가 시행돼 184,738건의 결함이 적발됐고, 검사당 평균 2.4건, 억류율은 3.6%, 억류 1건당 평균 5.6일이 손실됐다. 유효한 RightShip 검사를 보유한 4,300여 척은 검사당 결함 2.0건, 억류율 2.4%, 억류기간 3.7일로 전체 선대보다 뚜렷이 우수했다.", "eSum": "RightShip published an analysis of 2025 global PSC data: over 77,400 inspections across more than 32,470 ships produced 184,738 deficiencies, averaging 2.4 per inspection, with a 3.6% detention rate and 5.6 days lost per detention. Bulk carriers and general cargo ships accounted for nearly 60% of all inspections, with bulkers showing a detention ratio of 4.69 versus 1.15 for oil tankers and 0.38 for LNG carriers. The 4,300+ vessels holding a valid RightShip Inspection outperformed the wider fleet on every metric (2.0 deficiencies, 2.4% detention ratio, 3.7 days).", "kImp": "벌크선의 억류비율이 유조선의 4배에 달한다는 점은 드라이벌크를 관리하는 선박관리자에게 검사 준비가 곧 상업적 경쟁력임을 보여준다. 고위험 결함 1건만으로 억류율이 4.1%로 올라가고, 고위험 결함을 포함해 11건 이상이면 억류 확률이 61%에 이르므로 결함 '건수'보다 '심각도' 중심의 사전 시정이 훨씬 효율적이다. 억류 1일당 약 USD 15,000, 평균 손실 USD 80,000 이상이라는 수치는 입항 전 리스크 점검 투자에 대한 명확한 근거가 된다.", "eImp": "For dry bulk ship managers the message is commercial as much as regulatory: bulkers face roughly four times the detention ratio of oil tankers. Severity beats volume — a single high-risk deficiency lifts detention probability to 4.1%, while 11+ deficiencies including high-risk findings reach 61%. At an estimated USD 15,000 per detention day and USD 80,000+ average loss, pre-arrival risk screening and closing out high-severity items is the highest-return preparation activity.", "url": "https://rightship.com/insights/the-inspection-iceberg-what-psc-trends-in-2025-reveal-about-fleet-risk-beneath-the-surface"}, {"code": "VET", "title": "From Paper Trails to Predictive Compliance - How Digitalisation Is Redefining Maritime Due Diligence", "src": "MaritimeCyprus", "date": "2026-07-12", "kSum": "프리벤션 앳 시(Prevention at Sea)의 최고제품·AI책임자 크리스토스 게오르기우(Christos Georgiou)가 기고한 글로, 베팅 검사가 '선박 생애의 단 하루를 표본으로 삼아 판정을 내리는' 회고적 모델이라는 한계를 지적했다. 디지털화의 핵심은 종이 절차를 화면으로 옮기는 것이 아니라 컴플라이언스를 '증거 계층'에서 '통제 계층'으로 이동시키는 것이라고 주장한다. SIRE 2.0, TMSA, DryBMS, RISQ, MARPOL, MLC가 서로 수렴·강화되는 가운데 갭 분석과 벤치마킹은 주기적 행사가 아닌 상시 규율이 되어야 한다고 강조한다.", "eSum": "An opinion piece by Christos Georgiou, Chief Product & AI Officer at Prevention at Sea, argues that vetting inspection 'samples a single day in a vessel's life and extrapolates a verdict from it', making traditional due diligence an act of retrospective reconstruction. The real digitalisation shift is not moving paper onto screens but moving compliance from an 'evidence layer' to a 'control layer' that plans the compliant event before it happens. It notes SIRE 2.0, TMSA, DryBMS, RISQ, MARPOL and MLC are converging and tightening, and that VR-based behavioural competency assessment is now recognised within SIRE 2.0.", "kImp": "선박관리자 입장에서 PSC나 SIRE 2.0/RISQ 감사가 닥쳤을 때 부서별로 흩어진 기록을 시간에 쫓기며 꿰맞추는 관행은 이미 시정 가능한 시점이 지난 뒤의 대응이라는 점을 짚어준다. 로그북·SMS·환경기록·휴식시간·베팅 준비를 하나로 연결하면 육상팀이 편차를 실시간으로 포착해 선박 방문 출장 자체를 줄일 수 있다는 실무적 논거를 제시한다. SIRE 2.0에서 VR 기반 행동역량평가가 인정된다는 점은 인적요소 대응 준비의 새 선택지로 검토할 만하다.", "eImp": "It names the exact pain ship managers know: stitching siloed records into a due diligence file under time pressure when a PSC or SIRE 2.0/RISQ audit arrives, usually after the window to correct a gap has closed. Connecting logbooks, SMS, environmental tracking, work/rest hours and vetting preparation gives shore teams a live fleet view and can replace physical vessel attendances, freeing superintendent capacity across the managed fleet. The note that VR-based behavioural competency assessment is now recognised within SIRE 2.0 is a concrete option for human-element preparation.", "url": "https://maritimecyprus.com/2026/07/12/from-paper-trails-to-predictive-compliance-how-digitalisation-is-redefining-maritime-due-diligence/"}, {"code": "VET", "title": "OCIMF Members' News - Issue 160: Engaging SIRE Inspector Forum held in London", "src": "OCIMF", "date": "2026-07-01", "kSum": "OCIMF가 발간한 회원 뉴스 160호에 따르면, 6월 18일 런던에서 SIRE Cat-1 검사관을 대상으로 한 반일 일정의 검사관 참여 포럼이 열렸고 EU 지역 검사관 약 40명이 참석했다. 프로그램 디렉터 데이브 커드버트슨(Dave Cudbertson)과 교육·인증 매니저 아제이 구르(Ajay Gour)가 검사관 교육 프로그램과 검사보고서 통계·품질에 관해 발표했다. 검사용 태블릿 문제, 프로그램 내 응답 도구의 올바른 사용, HVPQ 등 관련 문서의 기술적 개선사항이 논의됐다.", "eSum": "OCIMF's Members' News Issue 160 reports that a half-day inspector engagement forum for SIRE Cat-1 inspectors was held in London on 18 June, attended by nearly 40 inspectors from the EU region. Programmes Director Dave Cudbertson and Training and Accreditation Manager Ajay Gour presented on the inspector training programme and on inspection report statistics and quality. Discussion covered challenges with the inspection tablet, correct use of the response tools within the inspection programme, and technical improvements to associated documents such as the Harmonised Vessel Particulars Questionnaire (HVPQ). OCIMF will hold similar forums in other regions, with a schedule to be published. The issue also marks the handover of the Managing Director role from Karen Davis to Don Davis.", "kImp": "검사관 대상 포럼에서 '응답 도구의 올바른 사용'이 논의 주제로 오른 것은 SIRE 2.0에서 선사가 제출하는 응답의 품질·형식이 여전히 편차를 낳고 있다는 신호로, 관리팀의 응답 작성 기준을 재점검할 근거가 된다. 검사보고서 품질 통계가 검사관에게 피드백되고 있다는 점은 향후 관측사항(observation) 기재 수준이 상향될 가능성을 시사한다. HVPQ 개선 논의는 선박 제원 데이터의 정확성 관리가 베팅 준비의 기본임을 다시 상기시킨다.", "eImp": "That 'correct use of the response tools' was a forum agenda item signals continuing variability in how operators draft SIRE 2.0 responses — a prompt for managers to review their internal response standards and templates. Feeding inspection report quality statistics back to inspectors points to observations being written to a rising bar. The HVPQ improvement discussion is a reminder that keeping vessel particulars data accurate and current is foundational vetting housekeeping. OCIMF also confirmed a Managing Director transition from Karen Davis to Don Davis.", "url": "https://www.ocimf.org/news-and-events/newsletter/issue-160-june-2026"}, {"code": "VET", "title": "Recurring onboard shortcuts can lead to major incidents", "src": "Splash247", "date": "2026-07-15", "kSum": "이스라엘 기술기업 십인 시스템즈(ShipIn Systems)는 일상 작업에서 반복되는 작은 이탈이 '정상'으로 굳어지는 이른바 '운영 표류(operational drift)'가 선대 전반의 주요 리스크 요인이라고 밝혔다. 최고경영자 오셔 페리(Osher Perry)는 절차·감사·보고서의 존재 자체를 기준 준수의 증거로 오인하기 쉬우나, 이러한 통제는 주기적이고 서류 중심이어서 실제 작업 방식을 놓친다고 지적했다. 당직, 갑판·기관실 작업, 보호구 착용, 감독 수준, 초기 기술 징후에 대한 대응에서 표류가 가장 뚜렷하게 나타난다고 설명했다.", "eSum": "Israeli tech firm ShipIn Systems says 'operational drift' — small deviations that repeat until they become normal behaviour — is a major fleet-wide risk factor. CEO Osher Perry argues shore managers can mistake the existence of procedures, audits and reports for proof that standards are being followed, when those controls are periodic and compliance-led and so miss how work is actually done day to day. Drift shows up most clearly in watchkeeping, deck and engine-room practices, PPE use, supervision levels and responses to early technical signals. ShipIn also says risk is rarely spread evenly: a small number of vessels account for a disproportionate share of recurring issues, and once patterns are flagged and discussed with crews, measurable improvement often follows within one to three months.", "kImp": "베팅·감사 체계가 '스냅샷' 검사에 의존한다는 구조적 한계를 정면으로 다룬 논지로, SIRE 2.0·RISQ 준비를 검사일 중심으로 운영하는 관리사에게 경고가 된다. 선대 내 소수 선박이 반복 문제의 대부분을 차지한다는 지적은 제한된 감독 자원을 어디에 집중할지에 대한 실무적 힌트다. 1~3개월 내 개선이 측정된다는 주장은 표류 지표를 내부 KPI로 편입해 베팅 전 사전 시정 사이클을 설계할 근거가 될 수 있다.", "eImp": "This goes straight at the structural weakness of vetting: an inspection is a snapshot, and procedures on paper are not evidence of practice. For managers who organise SIRE 2.0 / RISQ readiness around inspection dates, the 'drift' framing argues for continuous verification instead. The point that a minority of vessels drive most recurring issues is a practical steer for allocating limited superintendent attention, and the claimed one-to-three-month improvement window suggests drift indicators could be run as an internal KPI feeding a pre-vetting corrective cycle.", "url": "https://splash247.com/recurring-onboard-shortcuts-can-lead-to-major-incidents/"}, {"code": "VET", "title": "Partner Spotlight: Wilhelmsen Ships Service — Advancing Safer Mooring Through Lifecycle Innovation", "src": "RightShip", "date": "2026-07-09", "kSum": "라이트십(RightShip)이 제로 함 이노베이션 파트너스 프로그램(Zero Harm Innovation Partners Program) 회원사인 빌헬름센 십스 서비스(Wilhelmsen Ships Service)의 계류 안전 생애주기 접근법을 소개했다. Timm™ 스냅백 어레스터(SBA™) 로프와 라인 관리 계획(LMP™)에서 시작해 AI 기반 검사 도구 LineLens, 로프 조달·모니터링·폐기를 아우르는 디지털 생애주기 관리, 순환형 이니셔티브 Re-Rope로 확장됐다. 현재 약 5,000척이 SBA™ 로프 4본 이상을 운용하고 약 1,000척이 LMP 플랫폼을 사용하며, Re-Rope는 약 75척에 도입됐다.", "eSum": "RightShip profiled Zero Harm Innovation Partners Program member Wilhelmsen Ships Service and its lifecycle approach to mooring safety. What began with the Timm™ Snap Back Arrestor (SBA™) ropes and the Line Management Plan (LMP™) has grown into AI-assisted inspection via LineLens, digital lifecycle management covering rope procurement, monitoring and retirement, and Re-Rope, a circular initiative for collecting and repurposing retired ropes. Around 5,000 vessels now operate with four or more SBA™ ropes, roughly 1,000 use the LMP platform, and Re-Rope has been introduced across about 75 vessels. The company is also developing sensors for rope tension monitoring.", "kImp": "계류 로프 데이터·증서·검사 기록을 단일 디지털 플랫폼에 통합하면 컴플라이언스 업무가 단순해지고 감사 대응 준비도(audit readiness)가 개선된다는 점이 고객 피드백으로 제시됐는데, 이는 SIRE 2.0·RISQ 계류 관련 질문 대응과 직결된다. 계류 로프의 검사 이력·폐기 기준 관리는 베팅 검사에서 반복적으로 지적되는 영역이므로 기록 일원화의 실익이 크다. SBA™ 로프가 항만·터미널에서 스냅백 리스크 저감 수단으로 인정받고 있다는 점도 터미널 수용성 측면에서 참고할 만하다.", "eImp": "The customer feedback cited — rope data, certificates and inspection records consolidated in one digital platform, simplifying compliance and improving audit readiness — maps directly onto SIRE 2.0 and RISQ mooring questions, where inspection histories and rope retirement criteria are recurring observation areas. Fragmented inspection records and inconsistent retirement practice are exactly what vetting inspectors probe, so record consolidation has direct vetting value. SBA™ ropes being increasingly recognised by ports and terminals for reducing snap-back risk is also relevant to terminal acceptance.", "url": "https://rightship.com/insights/partner-spotlight-wilhelmsen-ships-service-advancing-safer-mooring-through-lifecycle-innovation"}, {"code": "VET", "title": "IQ SOLUTIONS becomes the first cybersecurity-focused partner in RightShip's Zero Harm Innovation Partners Program", "src": "RightShip", "date": "2026-06-26", "kSum": "라이트십(RightShip)이 IQ 솔루션스(IQ SOLUTIONS)를 제로 함 이노베이션 파트너스 프로그램(Zero Harm Innovation Partners Program)의 첫 사이버보안 전문 파트너로 맞이했다. IQ 솔루션스는 선박 ICT 인프라, 선박 연결성, 사이버 복원력 분야의 전문성을 보유하며 VCell과 VTalos 솔루션을 제공한다. VCell은 네트워크 분리와 중앙 관리, 안전한 선-육상 통신을 지원하는 통합 선박 ICT 인프라이고, VTalos는 해상 환경의 대표적 위협 경로인 이동식 저장매체(USB)와 파일 전송을 안전하게 관리한다.", "eSum": "RightShip has welcomed IQ SOLUTIONS as the first cybersecurity-focused organisation to join its Zero Harm Innovation Partners Program. IQ SOLUTIONS provides maritime ICT services covering vessel connectivity, cybersecurity and digital resilience through its VCell and VTalos products. VCell delivers a unified vessel ICT infrastructure supporting network segmentation, centralised management and secure ship-to-shore communications, while VTalos targets removable media — one of the most common cyber threat vectors onboard — by enabling secure management of USB devices and file transfers. RightShip frames the move as recognition that cyber resilience now sits alongside traditional operational risk in the maritime safety landscape.", "kImp": "사이버 리스크가 베팅·평가 생태계의 정식 항목으로 편입되는 흐름을 보여주는 신호로, SIRE 2.0과 TMSA가 이미 사이버보안을 다루고 있는 상황과 맞물린다. 특히 USB 등 이동식 매체 통제는 검사에서 실제로 확인되는 항목이므로, 절차 문서화뿐 아니라 기술적 통제 수단의 실재 여부를 점검할 필요가 있다. 네트워크 분리(segmentation) 역시 선내 OT/IT 분리 요구가 강화되는 추세에서 선제적으로 준비할 영역이다.", "eImp": "This signals cyber risk moving formally into the vetting and assurance ecosystem, consistent with cyber security already sitting within SIRE 2.0 and TMSA scope. Removable-media control is a point inspectors actually test onboard, so managers should verify that a technical control exists rather than relying on a written procedure alone. Network segmentation is likewise worth getting ahead of as OT/IT separation expectations tighten across inspection regimes.", "url": "https://rightship.com/insights/iq-solutions-becomes-the-first-cybersecurity-focused-partner-in-rightships-zero-harm-innovation-partners-program"}]}, {"code": "CLASS", "type": "news", "kTitle": "Section 15. 선급", "eTitle": "Section 15. Classification Societies", "items": [{"code": "CLASS", "title": "DNV releases July 2026 edition of class rules and standards with new Battery ready and Shore power ready notations", "src": "DNV", "date": "2026-07-02", "kSum": "DNV(디엔브이)이 2026년 7월판 선박·해양 선급규칙 및 표준을 공개했다. 신설 선급부호로는 지정 운항조건에서의 설계 피로수명을 나타내는 FL(Y, E), 배터리를 주 에너지원 설비로 탑재할 준비가 된 선박용 'Battery ready', 육상전원 설비 준비 선박용 'Shore power ready'가 포함된다. 이와 함께 화물창 부식 여유 축소, 화재안전 관련 선급규칙 폐지(법정증서로 일원화), 가스연료 수소 규칙의 IMO MSC 잠정지침 정합화 등이 반영됐다.", "eSum": "DNV has published the July 2026 edition of its class rules and standards for ship and offshore. New class notations include FL(Y, E) for design fatigue life under specified operating conditions, 'Battery ready' for vessels prepared for batteries as part of the main onboard energy installation, and 'Shore power ready' for vessels prepared for shore power. Other changes include reduced corrosion margins for cargo tanks, discontinuation of the fire safety class rules (now covered by statutory certificates), and amendment of the gas-fuelled hydrogen rules concept to align with the IMO MSC Interim guideline.", "kImp": "선박관리자 입장에서 신규 발주 사양과 개조 계획에 직접 영향을 준다. 'Battery ready'와 'Shore power ready'는 EU/각국 육상전원 의무화와 배터리 하이브리드 개조를 앞두고 향후 자산가치와 규제 대응 여력을 좌우하는 부호이므로, 신조 계약 시 선택 여부를 사전 검토해야 한다. 또한 화재안전 선급규칙 폐지로 관련 검증이 법정증서 체계로 넘어가므로 사내 검사·문서 관리 흐름을 조정할 필요가 있다. 계약 전 프로젝트에도 당사자 합의 시 적용 가능하다는 점도 협상 포인트다.", "eImp": "This directly affects newbuilding specifications and retrofit planning. 'Battery ready' and 'Shore power ready' notations matter ahead of shore power mandates and hybrid retrofits, shaping future asset value and regulatory headroom, so owners should decide on them at the contracting stage. The discontinuation of fire safety class rules shifts that verification into the statutory certificate regime, requiring adjustments to internal survey and documentation workflows. The rules may also be applied to projects contracted before entry into force if all parties agree.", "url": "https://www.dnv.com/news/2026/standards-now-available-the-july-2026-edition-of-the-dnv-class-rules-and-standards-for-ship-and-offshore/"}, {"code": "CLASS", "title": "DNV clarifies class requirements for boiler tube plugging", "src": "DNV", "date": "2026-07-06", "kSum": "DNV(디엔브이)이 선박 보일러 튜브 플러깅(plugging)에 대한 선급 요건을 정리해 안내했다. 보일러 튜브는 열전달뿐 아니라 보일러의 압력 건전성 유지에 핵심적인 역할을 하므로, 누설이 발생했을 때 2차 손상을 막기 위한 신중한 평가가 요구된다는 점을 강조했다.", "eSum": "DNV has issued guidance clarifying class requirements for boiler tube plugging. Boiler tubes play a critical role both in heat transfer and in maintaining the pressure integrity of marine boilers, and DNV notes that when leaks occur, careful evaluation is required to prevent secondary damage.", "kImp": "보일러 튜브 누설은 현장에서 임시 플러깅으로 처리하려는 유혹이 큰 대표적 항목이다. 선급 요건을 벗어난 플러깅은 인접 튜브 과열과 압력부 손상으로 이어져 보일러 전면 교체나 운항 중단으로 번질 수 있으므로, 기술팀은 본선 기관부의 임시조치 범위와 선급 통보 기준을 명확히 재정립해야 한다.", "eImp": "Boiler tube leaks are a classic case where crews are tempted to apply ad hoc plugging. Plugging outside class requirements can cause overheating of adjacent tubes and pressure-part damage, escalating into full boiler replacement or off-hire, so technical teams should re-confirm the permitted scope of temporary repairs and the thresholds for notifying class.", "url": "https://www.dnv.com/news/2026/boiler-tube-plugging-class-requirements/"}, {"code": "CLASS", "title": "New DNV recommended practice establishes measurement framework for onboard carbon capture and storage systems", "src": "DNV", "date": "2026-06-22", "kSum": "DNV(디엔브이)이 선박 탑재형 탄소포집·저장(OCCS, Onboard Carbon Capture and Storage) 시스템의 성능을 측정·검증하기 위한 표준화된 프레임워크를 담은 권고지침(RP, Recommended Practice)을 발간했다. 그동안 제조사마다 제각각이던 포집 성능 주장에 공통 측정 기준을 제시하는 것이 목적이다.", "eSum": "DNV has published a recommended practice (RP) providing a standardized framework for measuring and verifying the performance of onboard carbon capture and storage (OCCS) systems on ships. The aim is to set a common measurement basis for capture performance claims that until now have varied by manufacturer.", "kImp": "OCCS는 IMO Net-Zero Framework와 EU ETS 하에서 탄소비용을 줄일 잠재 수단이지만, 포집량이 규제상 인정받으려면 신뢰할 수 있는 측정·검증이 전제된다. 선박관리자는 OCCS 투자 검토 시 벤더의 성능 보증을 이 RP 기준으로 비교·요구할 수 있게 되며, 향후 규제 크레딧 인정 논의에서도 이 프레임워크가 사실상 기준선이 될 가능성이 크다.", "eImp": "OCCS is a potential lever to cut carbon costs under the IMO Net-Zero Framework and EU ETS, but captured volumes will only count if measurement and verification are credible. Ship managers can now benchmark vendor performance guarantees against this RP when evaluating OCCS investments, and the framework is likely to become the de facto baseline in future discussions on regulatory credit recognition.", "url": "https://www.dnv.com/news/2026/New-DNV-RP-establishes-measurement-framework-for-onboard-carbon-capture-and-storage-systems/"}, {"code": "CLASS", "title": "Latest LR FOBAS Fuel Quality Report finds ISO-compliant fuels are increasingly causing operational problems", "src": "Lloyd's Register", "date": "2026-07-14", "kSum": "로이드선급(Lloyd's Register)이 2026년 상반기 FOBAS(Fuel Oil Bunker Analysis and Advisory Service) 연료품질 보고서를 발간하며, ISO 8217 정기시험은 통과하지만 실제 선상에서 문제를 일으키는 연료가 늘고 있다고 경고했다. 3~4월 주요 벙커링 허브에서 급유한 다수 선박이 운항 문제를 겪었고, 정밀 분석 결과 에스토니아산 셰일오일이 약 10~15% 함유된 것으로 추정됐다. 셰일오일은 ISO 8217상 허용 블렌드 성분이지만, 고농도일 경우 연료 불안정성과 필터·청정기·연료펌프 문제로 이어질 수 있다는 것이다.", "eSum": "Lloyd's Register has published its FOBAS (Fuel Oil Bunker Analysis and Advisory Service) Fuel Quality Report for H1 2026, warning that fuels passing routine ISO 8217 testing are increasingly causing operational problems onboard. In March and April, several vessels reported difficulties after bunkering at a major hub; forensic analysis found elevated concentrations of Estonian shale oil, estimated at around 10-15%. While shale oil is an acceptable blend component under ISO 8217, FOBAS found higher concentrations can be associated with instability and issues affecting filters, separators and fuel pumps.", "kImp": "'스펙 통과 = 안전한 연료'라는 전제가 더 이상 통하지 않는다는 뜻으로, 선박관리자에게는 실무 부담이 커지는 신호다. LR은 온스펙/오프스펙 구분보다 '운항상 견고한 연료'와 '취약한 연료'의 구분이 중요해졌다고 지적하므로, 정기 벙커 시험에 더해 안정성·적합성(compatibility) 시험과 연료 조성 파악을 표준 절차에 넣고, 문제 허브에서의 급유 시 탱크 분리와 사전 혼합시험을 강화할 필요가 있다. 황분 초과, 과다 수분, 촉매 미분, 나트륨 오염, 저인화점 유분 등 상습 항목도 여전하다.", "eImp": "The premise that 'on-spec means safe' no longer holds, raising the practical burden on ship managers. LR argues the meaningful distinction is now between operationally resilient and operationally fragile fuels, so managers should add stability and compatibility testing plus fuel composition analysis to standard bunkering procedures, and tighten tank segregation and pre-mixing checks when bunkering at affected hubs. Recurring issues such as sulphur exceedances, excess water, cat fines, sodium contamination and low flash point distillates also remain elevated.", "url": "https://www.lr.org/en/knowledge/press-room/press-listing/press-release/2026/latest-fobas-fuel-quality-report-finds-iso-compliant-fuels-are-increasingly-causing-operational-problems/"}, {"code": "CLASS", "title": "Lloyd's Register targets ageing feeder fleet with retrofit and renewal push", "src": "Lloyd's Register", "date": "2026-07-13", "kSum": "로이드선급(Lloyd's Register)이 노후화된 피더선 선대를 겨냥한 'Powering the next generation of feeder vessels' 캠페인을 시작했다. 선급·자문·디지털 서비스를 묶어 신조 사양 결정, 개조 전략, 선령 연장 계획, 운항 성능 개선, 미래연료 대응을 지원한다는 구상이다. OneOcean 항해 최적화와 BoxMax·LashRightUX·RollRight 등 적재 관련 디지털 솔루션도 함께 제시했다.", "eSum": "Lloyd's Register has launched a 'Powering the next generation of feeder vessels' campaign aimed at the ageing feeder fleet. It bundles classification, advisory and digital services to support newbuild specification, retrofit strategies, life-extension planning, operational performance and future fuel readiness. LR is also highlighting digital tools including OneOcean voyage optimisation and connected stowage solutions such as BoxMax, LashRightUX and RollRight.", "kImp": "피더선은 항로가 짧고 기항이 잦아 대형 원양선과 개조 경제성 계산이 다르다. 노후 자산, 강화되는 배출 규제, 연료비 상승이 겹치면서 '개조 후 계속 운항 vs. 대체 발주' 판단이 시급한데, 선급이 전 생애주기 관점의 패키지를 내놓았다는 것은 이 의사결정에 쓸 수 있는 기술 자문 옵션이 늘었다는 의미다. 단, 이는 선급의 영업 캠페인 성격이므로 실제 적용 범위와 비용은 개별 검증이 필요하다.", "eImp": "Feeders have shorter routes and more frequent port calls, so retrofit economics differ from deep-sea tonnage. With ageing assets, tighter emissions rules and rising fuel costs converging, the 'retrofit and keep trading versus replace' decision is pressing, and a class-led lifecycle package adds a technical advisory option for that call. Note this is a commercial campaign, so actual scope and cost should be verified case by case.", "url": "https://www.lr.org/en/knowledge/press-room/press-listing/press-release/2026/lloyds-register-targets-ageing-feeder-fleet-with-retrofit-and-renewal-push/"}, {"code": "CLASS", "title": "GasLog vessel receives combined ABS SMART (MHM) and PMP-CBM notations in industry first", "src": "ABS", "date": "2026-06-29", "kSum": "미국선급(ABS)이 가스로그(GasLog)의 LNG운반선에 SMART(MHM) 부호를 부여했으며, 이는 ABS 예방정비프로그램(PMP, Preventative Maintenance Program)과 결합해 보유한 세계 최초 선박이다. SMART(MHM) 부호는 ABS의 스마트 기능 지침에 따라 이상 징후를 탐지하고 성능 저하를 예측하는 상설 기관 상태감시(Machinery Health Monitoring) 시스템을 확인하는 것이다. ABS·가스로그·프로펄션 애널리틱스(Propulsion Analytics) 3사가 4년간 협업해 개발한 'DiEM' 플랫폼이 기반으로, Engine Hyper Cube에 콩스버그(Kongsberg) Vessel Insight 텔레메트리, 윤활유·화학 분석, 실시간 진동, 계획정비시스템(PMS) 데이터를 결합했다.", "eSum": "ABS has awarded the SMART (MHM) notation to a GasLog LNG carrier, the first vessel in the world to hold it combined with the ABS Preventative Maintenance Program (PMP). The SMART (MHM) notation, under the ABS Guide for Smart Functions for Marine Vessels and Offshore Units, confirms a permanently installed Machinery Health Monitoring system that detects anomalies and predicts degradation. It stems from a four-year collaboration between ABS, GasLog and Propulsion Analytics on the 'DiEM' platform, combining Propulsion Analytics' Engine Hyper Cube with Kongsberg Vessel Insight telemetry, lubrication and chemical data, live vibration and Planned Maintenance System data. GasLog is nearing completion of a fleetwide transition to SMART (MHM) under its Lifecycle Maintenance Strategy.", "kImp": "상태기반정비(CBM)를 선급이 정식 부호로 인정하고 예방정비프로그램과 묶어준 첫 사례로, 기술팀에는 '계획정비 주기 준수'에서 '실제 상태 기반 정비'로 전환할 수 있는 실질적 경로가 열린 셈이다. 승인된 CBM 체계는 불필요한 개방검사를 줄여 정비비와 정박시간을 절감할 수 있으나, 센서 데이터 품질과 무결성 관리 부담이 새로 생긴다. 가스로그가 선대 전체로 확대 중이라는 점에서 LNG선 부문의 사실상 표준으로 굳어질 가능성을 주시해야 한다.", "eImp": "This is the first case of class formally recognising condition-based maintenance as a notation and pairing it with a preventative maintenance programme, opening a practical route for technical teams to move from calendar-based PMS compliance to genuinely condition-based maintenance. An approved CBM regime can cut opening-up surveys, maintenance spend and off-hire, but it adds a new burden around sensor data quality and integrity. With GasLog rolling it out fleetwide, watch for this becoming a de facto standard in the LNG segment.", "url": "https://pressreleases.eagle.org/news/gaslog-vessel-receives-combined-abs-smart-mhm-and-pmp-cbm-notations-in-industry-first"}, {"code": "CLASS", "title": "ABS, Polaris Shipping, HHI and AVIKUS sign agreement for Conditional Unmanned Bridge", "src": "ABS", "date": "2026-06-16", "kSum": "미국선급(ABS), 폴라리스쉬핑(Polaris Shipping), HD현대중공업(HHI), 아비커스(AVIKUS) 4사가 '조건부 무인 선교(Conditional Unmanned Bridge)' 개념을 공동 개발하는 개념연구 협약을 체결했다. 폴라리스쉬핑의 32.5만톤급 초대형광석운반선(VLOC) 선대를 대상으로, 위험도가 낮은 원양 심해 구간에 한해 무인 선교 운항을 목표로 하며 IMO MASS 코드에 정합화한다. 폴라리스는 운항 데이터와 인적 대응 기준을, 아비커스는 자율항해 시스템 요건을, HHI는 선박 설계 변경 검토를, ABS는 독립적인 안전·규제 갭 분석을 맡는다.", "eSum": "ABS, Polaris Shipping, HD Hyundai Heavy Industries (HHI) and AVIKUS have signed a four-party Concept Study Agreement to jointly develop a 'Conditional Unmanned Bridge' concept for Polaris Shipping's 325K Very Large Ore Carrier (VLOC) fleet. The study targets unmanned bridge operation only during low-risk open-ocean deep-sea segments, aligned with the IMO MASS Code, and is described as the most realistic near-term autonomous shipping concept. Polaris Shipping provides operational data and human-response benchmarks, AVIKUS defines autonomous navigation system requirements, HHI reviews vessel design modifications, and ABS conducts an independent safety and regulatory gap analysis. Outcomes will be compiled into a Technical Publication feeding each party's roadmap.", "kImp": "전 구간 무인화가 아니라 '저위험 원양 구간 한정'이라는 점이 핵심으로, 실제 도입 가능성이 있는 첫 단계 시나리오다. 선박관리자에게는 향후 당직 편성, 선원 정원, STCW 당직 요건, 그리고 무인 구간 중 사고 시 책임 소재라는 미해결 쟁점이 직결된다. IMO MASS 코드 발효를 앞두고 선급이 갭 분석을 수행한다는 점에서, 여기서 나올 기술간행물이 향후 감독당국·보험사 요구사항의 밑그림이 될 수 있으므로 조기 파악이 필요하다.", "eImp": "The key point is that this is not full autonomy but unmanned operation limited to low-risk ocean legs, making it a plausible first-step scenario. For ship managers it bears directly on watchkeeping arrangements, manning levels, STCW watch requirements and the unresolved question of liability if an incident occurs during an unmanned segment. With the IMO MASS Code approaching and class running the gap analysis, the resulting Technical Publication could shape future regulator and insurer expectations, so early awareness is worthwhile.", "url": "https://pressreleases.eagle.org/news/abs-polaris-shipping-hhi-and-avikus-sign-agreement-for-conditional-unmanned-bridge"}, {"code": "CLASS", "title": "ClassNK launches world's first notation for ship construction carbon footprint", "src": "Container News", "date": "2026-06-30", "kSum": "일본선급(ClassNK)이 선박 건조 과정에서 발생하는 탄소발자국(CFP, Carbon Footprint)을 검증하는 세계 최초의 선급부호 'a-EA (CFP)'를 도입했다. 배출량은 ISO 14067에 따라 산정되고 독립적으로 검증되며, ClassNK 환경 가이드라인에 반영된다. 선주·화주의 Scope 3 카테고리 2(자본재) 배출 보고를 겨냥한 것으로, 조선소가 일반 계수가 아닌 프로젝트별 실측 데이터로 저탄소 자재 사용과 건조 단계 배출 감축을 입증할 수 있게 한다.", "eSum": "ClassNK has introduced notation a-EA (CFP), described as the world's first classification notation verifying the carbon footprint generated during ship construction. Emissions are calculated and independently verified in accordance with ISO 14067 and incorporated into ClassNK's Environmental Guidelines. It targets Scope 3 Category 2 (capital goods) emissions reporting for shipowners and cargo owners, allowing shipyards to demonstrate use of low-carbon materials and construction-phase emission reductions using project-specific rather than generic data.", "kImp": "지금까지 해운 탈탄소 논의는 운항 배출(Scope 1)에 집중됐지만, 이 부호는 선박의 '내재 탄소(embodied carbon)'를 처음으로 선급 검증 대상으로 끌어들였다. 선주·운영사가 Scope 3 보고 압박을 받는 상황에서 신조 발주 시 조선소 선정 기준에 탄소발자국이 추가될 수 있고, 화주가 공급망 배출 데이터를 요구할 때 대응 근거가 된다. 다만 선급별 산정 방식이 갈릴 경우 비교 가능성 문제가 생길 수 있어, IACS 차원의 조화 여부를 지켜볼 필요가 있다.", "eImp": "Shipping decarbonisation has focused on operational (Scope 1) emissions; this notation is the first to bring a vessel's embodied carbon under class verification. As owners and operators face Scope 3 reporting pressure, carbon footprint could become a yard selection criterion for newbuilds and a documented basis for responding to cargo owners' supply-chain emissions requests. If calculation methods diverge between societies, however, comparability becomes an issue, so watch whether IACS moves to harmonise the approach.", "url": "https://container-news.com/classnk-launches-worlds-first-notation-for-ship-construction-carbon-footprint/"}, {"code": "CLASS", "title": "Bureau Veritas advances ultrasonic weld inspection for LNG-fuelled vessels, replacing radiography", "src": "Bureau Veritas", "date": "2026-06-16", "kSum": "뷰로베리타스(Bureau Veritas)가 LNG 연료 선박의 얇은 두께 오스테나이트계 스테인리스강 배관 용접부 검사에서 방사선투과시험(RT)을 대체하는 반자동 위상배열 초음파탐상(PAUT) 기법을 개발·승인했다. 자격인정은 BV 규칙 NR216, ISO 20601, ISO 22825 및 ASME Section V 원칙에 따라 이뤄졌고, 인공 결함과 실제 결함을 포함한 시험편으로 검증해 RT와 동등하거나 우수한 검출 성능을 입증했다. BV 프랑스 브레스트(Brest) 사업부가 NR669에 따라 비파괴검사 공급자로 인정받았다.", "eSum": "Bureau Veritas has developed and approved a semi-automated phased array ultrasonic testing (PAUT) method that replaces radiographic testing (RT) for thin-wall austenitic stainless steel piping welds on LNG-fuelled vessels. Qualification followed BV Rules NR216, ISO 20601, ISO 22825 and ASME Section V principles, and was validated with test specimens containing artificial and realistic defects, showing detection performance equal or superior to RT. BV France Industry's Brest unit was accredited as an NDT supplier under NR669. The method removes the need for radiation safety exclusion zones, enabling concurrent shipyard work with faster digital data acquisition and full traceability.", "kImp": "검사 방식 변경은 조선소·수리조선소 공정 일정에 직접적인 이득을 준다. RT는 방사선 차단구역 설정 때문에 인접 작업을 중단시켜야 하지만, PAUT는 병행 작업이 가능해 LNG 연료 배관 시공이나 개조 공사의 공기를 단축할 수 있다. 또한 디지털 데이터로 기록이 남아 추적성이 확보되므로, 향후 하자 분쟁이나 검사 기록 요구에 대응하기 유리하다. LNG 이중연료 개조를 검토 중인 관리선대라면 조선소와 검사 방식을 사전 협의할 실익이 있다.", "eImp": "A change in inspection method has direct benefits for shipyard and repair yard scheduling. RT requires radiation exclusion zones that halt adjacent work, whereas PAUT allows concurrent operations, potentially shortening LNG fuel piping installation and conversion timelines. Digital records also provide full traceability, which helps in later defect disputes or when inspection records are demanded. Fleets considering LNG dual-fuel conversions have a practical reason to discuss the inspection method with yards in advance.", "url": "https://marine-offshore.bureauveritas.com/newsroom/bureau-veritas-advances-ultrasonic-weld-inspection-lng-fueled-vessels"}]}, {"code": "COMM", "type": "news", "kTitle": "Section 16. 상업·용선시장", "eTitle": "Section 16. Commercial & Chartering", "items": [{"code": "COMM", "title": "Rubico expands MR tanker newbuild bet with Top Ships deal", "src": "Splash247", "date": "2026-07-15", "kSum": "나스닥 상장 탱커 선사 루비코(Rubico)가 옛 모회사 톱쉽스(Top Ships)로부터 광저우조선(GSI)에서 건조 중인 47,499dwt 제품·케미컬 탱커 신조선 계약을 보유한 특수목적회사 지분을 약 625만 달러에 인수하기로 했다. 선박 건조가는 4,520만 달러이며 중국 리스사가 인스톨먼트의 85%를 세일앤리스백으로 조달한다. 이 선박은 인도 시점부터 7년간 익명의 대형 오일 트레이더에 용선되어 있으며, 옵션 포함 총 매출 잠재액은 약 7,540만 달러다.", "eSum": "Nasdaq-listed Rubico agreed to buy an MR newbuilding from former parent Top Ships, paying about $6.25m for shares of an SPC holding a contract for a 47,499 dwt product and chemical tanker at Guangzhou Shipyard International, due Q3 2029. The shipbuilding contract is priced at $45.2m, with a Chinese leasing company providing sale-and-leaseback financing for 85% of instalments at term SOFR plus 1.8%. The vessel is fixed to an unnamed major oil trader for seven years with four option years, carrying potential gross revenue of about $75.4m.", "kImp": "선주가 신조선을 장기 용선과 세일앤리스백 금융을 묶어 확보하는 전형적 구조로, 선박관리자 입장에서는 인도 전 단계부터 장기 고정 용선주(오일 메이저 트레이더)의 검사·베팅 요건이 사양에 반영된다는 뜻이다. GSI 등 중국 야드발 MR 물량이 계속 늘고 있어 신조 감독·인수 인력 수요와 2029년 인도 파이프라인 관리가 중요해진다.", "eImp": "This is a textbook structure of newbuilding plus long-term charter plus sale-and-leaseback financing, meaning a ship manager must build oil-major vetting and inspection requirements into the specification from the pre-delivery stage. With Chinese yards such as GSI continuing to add MR tonnage, demand for newbuilding supervision staff and management of the 2029 delivery pipeline both rise.", "url": "https://splash247.com/rubico-expands-mr-tanker-newbuild-bet-with-top-ships-deal/"}, {"code": "COMM", "title": "Los Angeles tops 1m teu in record June", "src": "Splash247", "date": "2026-07-16", "kSum": "로스앤젤레스항(Port of Los Angeles)이 6월 한 달 1,002,734TEU를 처리해 118년 항만 역사상 세 번째로 월간 100만 TEU를 돌파했다. 전년 동월 대비 8% 증가했으며, 적재 수입은 10% 늘어난 523,516TEU, 적재 수출은 4% 줄어든 118,332TEU였다. 상반기 누계는 548만 TEU로 전년 동기 대비 6% 앞서 있다.", "eSum": "The Port of Los Angeles handled 1,002,734 teu in June, the third time in its 118-year history that monthly volumes exceeded 1m teu, up 8% year on year. Loaded imports rose 10% to 523,516 teu while loaded exports fell 4% to 118,332 teu, and empties reached 360,886 teu. First-half throughput of 5.48m teu is 6% ahead of last year, with executive director Gene Seroka attributing the surge to importers front-loading goods in response to trade policy changes.", "kImp": "미국 서안 물동량 급증은 프론트로딩(관세 회피성 조기 선적)에 기인한 것으로, 하반기 반동 감소 가능성을 시사한다. 선박관리자는 서안 기항 선박의 체선·터미널 대기 증가와 그에 따른 승무원 교대·급유·정비 일정 차질에 대비해야 하며, 물동량이 꺾일 경우 컨테이너선 계선·감속 운항 전환에도 대응 계획이 필요하다.", "eImp": "The surge on the US west coast is driven by tariff-related front-loading, which points to a possible payback slump later in the year. Ship managers should prepare for heavier berth waiting and terminal delays affecting crew changes, bunkering and maintenance windows, and have a plan for a shift to slow steaming or lay-up if volumes turn down.", "url": "https://splash247.com/los-angeles-tops-1m-teu-in-record-june/"}, {"code": "COMM", "title": "DHT adds three-year VLCC cover", "src": "Splash247", "date": "2026-07-14", "kSum": "뉴욕 상장 VLCC 선사 DHT 홀딩스(DHT Holdings)가 2015년 건조 VLCC 'DHT Jaguar'를 익명의 글로벌 에너지 기업에 일일 75,000달러, 3년 정기용선으로 고정했다. 계약은 9월 개시 예정으로 선박을 2029년까지 커버한다. DHT는 2분기 전 선대 TCE를 일일 126,700달러로 추정했고, 스팟 운항 VLCC는 162,600달러를 벌어들였다.", "eSum": "New York-listed DHT Holdings fixed the 2015-built DHT Jaguar on a three-year time charter to an unnamed global energy company at $75,000 per day, starting in September and covering the vessel into 2029. In a business update, DHT estimated fleetwide Q2 TCE of $126,700 per day, with spot-trading VLCCs at $162,600 per day and time-chartered vessels at $90,800 per day. So far in Q3, 48% of available spot days are booked at an average $139,700 per day.", "kImp": "VLCC 스팟 수익이 일일 16만 달러를 넘는 상황에서 선주들이 장기 커버를 늘리고 있다는 신호로, 탱커 시황이 정점 부근일 수 있음을 시사한다. 선박관리자에게는 고수익 국면에서 오프하이어 최소화와 예정 검사·드라이독 일정 최적화가 수익에 직결되며, 장기 용선 계약 선박은 차터러의 성능보증(속력·연료소모) 준수가 핵심 관리 지표가 된다.", "eImp": "With VLCC spot earnings above $160,000 per day, owners locking in long-term cover suggests the tanker market may be near a peak. For ship managers, minimising off-hire and optimising survey and drydock scheduling directly protects earnings in a high-rate window, while vessels on long charters make compliance with speed and consumption warranties a core KPI.", "url": "https://splash247.com/dht-adds-three-year-vlcc-cover/"}, {"code": "COMM", "title": "Freightos Weekly Update: Hormuz closure pushing fuel costs back up", "src": "Container News", "date": "2026-07-15", "kSum": "프레이토스(Freightos)는 호르무즈 해협(Strait of Hormuz) 재봉쇄로 유가가 10% 뛰어 6월 중순 수준으로 되돌아갔고 벙커 가격도 5% 올랐다고 분석했다. 아시아-북유럽 운임은 6주 전보다 약 3,000달러 높은 FEU당 5,800달러, 지중해는 7,200달러이며, 태평양 횡단은 서안 7,500달러·동안 9,000달러 이상으로 마감했다. 다만 미국소매협회(NRF)는 8월과 9월 도착 물량이 각각 전월 대비 10%씩 감소할 것으로 전망해 피크가 이미 지났을 가능성을 시사한다.", "eSum": "Freightos reports that the renewed Strait of Hormuz closure has pushed oil prices up 10% back to mid-June levels, with bunker prices up 5%, though adjustments made by energy markets should stop prices returning to earlier wartime highs. Asia-North Europe rates are about $3,000/FEU higher than six weeks ago at $5,800/FEU and $7,200/FEU to the Mediterranean, while transpacific closed at $7,500/FEU to the West Coast and over $9,000/FEU to the East Coast. The NRF estimates July US arrivals will hit a record 2.47m teu but projects August and September volumes each falling 10% month on month.", "kImp": "벙커 가격 재상승은 선박관리자의 운항비 예산과 연료 조달 전략에 직접 타격을 준다. 호르무즈 통항 조건(이란 허가·오만 남측 항로)이 유동적이어서 걸프 기항 선박의 전쟁위험보험료(AWRP), 승무원 위험수당, 항로 계획 재검토가 필요하며, 벙커 품질·수급이 불안정한 대체 급유항 이용도 늘 수 있다.", "eImp": "Rising bunker prices hit ship managers' operating budgets and fuel procurement strategy directly. With Hormuz transit conditions in flux (Iranian permission versus the southern Omani lane), Gulf-calling vessels need fresh reviews of additional war risk premiums, crew hazard pay and voyage planning, and may have to use alternative bunker ports where quality and supply are less reliable.", "url": "https://container-news.com/freightos-weekly-update-hormuz-closure-pushing-fuel-costs-back-up/"}, {"code": "COMM", "title": "Port of Long Beach posts double-digit cargo growth in June", "src": "Container News", "date": "2026-07-15", "kSum": "롱비치항(Port of Long Beach)이 6월 779,331TEU를 처리해 역대 세 번째로 바쁜 6월을 기록했으며 전년 동월 대비 10.6% 증가했다. 수입은 11% 늘어난 387,025TEU, 수출은 1.3% 줄어든 86,446TEU, 공컨테이너는 14.1% 증가한 305,860TEU였다. 상반기 누계는 482만 TEU로 전년 대비 1.7% 늘어 기록적인 해의 페이스를 유지하고 있다.", "eSum": "The Port of Long Beach handled 779,331 teu in June, its third-busiest June on record and up 10.6% year on year. Imports rose 11% to 387,025 teu, exports slipped 1.3% to 86,446 teu, and empties jumped 14.1% to 305,860 teu, with first-half volumes of 4.83m teu up 1.7%. CEO Noel Hacegaba said retailers are accelerating imports ahead of possible trade policy changes, noting that 'businesses are preparing for volatility, not certainty'.", "kImp": "LA항과 함께 미 서안 양대 관문이 동시에 두 자릿수 성장을 기록한 것은 관세 관련 프론트로딩이 광범위하다는 뜻으로, 하반기 급격한 물동량 조정 위험을 키운다. 공컨테이너 반출이 14% 급증한 점은 아시아 회송 수요 압박을 시사하며, 선박관리자는 성수기 서안 체선에 따른 승무원 교대·수리 창구 축소에 대비해야 한다.", "eImp": "Double-digit growth at both major US west coast gateways confirms that tariff-driven front-loading is broad-based, raising the risk of a sharp volume correction later in the year. The 14% jump in empties points to pressure on repositioning back to Asia, and managers should expect narrower windows for crew changes and repairs as peak-season congestion builds on the west coast.", "url": "https://container-news.com/port-of-long-beach-posts-double-digit-cargo-growth-in-june/"}, {"code": "COMM", "title": "Container spot rates stall as Gulf tonnage returns", "src": "Seatrade Maritime News", "date": "2026-07-14", "kSum": "라이너리티카(Linerlytica)에 따르면 아라비아만에 묶여 있던 선복이 최고 49만 TEU에서 3만 TEU로 풀리고 최근 한 달간 17만 TEU가 신조 인도되면서 컨테이너 스팟 운임 상승세가 멈췄다. 선사들은 7월 초 인상분을 지키지 못했고 운임은 전반적으로 후퇴했으며, 제미니(Gemini)와 프리미어 얼라이언스(Premier Alliance)는 미 서안 운임을 FEU당 5,300달러까지 낮춰 전주 대비 최대 1,500달러 인하했다. 컨테이너선 발주잔량은 1,712척·1,372만 TEU로 현 선대의 40%에 달해 장기 공급과잉 우려가 커지고 있다.", "eSum": "Linerlytica reports that container spot rates have stalled as trapped Arabian Gulf tonnage fell from a peak of 490,000 teu to 30,000 teu, with nearly 170,000 teu also delivered over the last month. Carriers failed to hold early-July hikes and rates receded across the board, with Gemini Cooperation and Premier Alliance slashing US West Coast rates to $5,300/feu, up to $1,500/feu below a week earlier, while Asia-Europe offers range from $4,500 to $7,000/feu and EC freight futures bet on a 60% drop by November. The containership orderbook has hit 1,712 vessels totalling 13.72m teu, 40% of the current fleet, all due by 2030.", "kImp": "운임이 4월 이후 70% 오른 뒤 정점을 찍었다는 신호로, 컨테이너 선주·관리자는 하반기 수익 하강 국면 진입 가능성에 대비해야 한다. 발주잔량이 현 선대의 40%에 달하는 만큼 2028~2030년 만성적 공급과잉이 정기용선료와 관리 수수료를 압박할 수 있어, 노후선 해체·감속 운항 시나리오와 선대 갱신 계획을 지금부터 점검할 필요가 있다.", "eImp": "This signals that rates have peaked after a 70% rise since April, so container owners and managers should prepare for an earnings downturn in the second half. With the orderbook at 40% of the fleet, chronic overcapacity in 2028-2030 could squeeze timecharter rates and management fees, making it worth reviewing scrapping and slow-steaming scenarios and fleet renewal plans now.", "url": "https://www.seatrade-maritime.com/containers/container-spot-rates-stall-as-gulf-tonnage-returns"}, {"code": "COMM", "title": "Record VLCC orders raise fears of 2028 tanker squeeze", "src": "Seatrade Maritime News", "date": "2026-07-15", "kSum": "MSI 자료에 따르면 2026년 상반기에만 5,450만 dwt의 VLCC가 발주돼 종전 연간 최고 기록인 2006년의 3,260만 dwt를 크게 넘어섰다. VLCC 발주잔량 대 선대 비율은 2023년 2%에서 약 35%로 치솟았고, 상반기 발주 선박의 약 83%가 2028~2029년 인도 예정이어서 향후 수급 균형에 큰 부담이 될 전망이다. 상반기 계약의 약 89%가 중국 조선소로 갔으며 헝리조선(Hengli Shipbuilding)이 중국 물량의 55%를 확보했다.", "eSum": "MSI figures show 54.5m dwt of VLCCs were ordered in the first six months of 2026, eclipsing the previous annual record of 32.6m dwt set in 2006, pushing the VLCC orderbook-to-fleet ratio to roughly 35% from 2% in 2023. MSI warns that around 83% of vessels ordered in H1 2026 are slated for delivery in 2028 and 2029, more than doubling scheduled 2028 deliveries and placing significant pressure on future market balances. Around 89% of H1 contracts went to Chinese builders, with Hengli Shipbuilding taking 55% of the country's orders, while BRS notes Greek owners (72 ships on order) could overtake China (47) in VLCC ownership.", "kImp": "2028~2029년 인도 러시는 현재의 초호황 탱커 시황이 급반전할 수 있음을 경고하는 신호로, 선주의 신조 감독 수요는 늘지만 인도 후 운임 하락 리스크가 커진다. 중국 야드 집중도(89%)가 높아 선박관리자는 헝리 등 신흥 야드의 품질·인도 지연 리스크와 표준화되지 않은 사양에 따른 초기 운항 트러블에 대비해야 한다.", "eImp": "The 2028-2029 delivery rush warns that today's exceptional tanker market could reverse sharply, boosting newbuilding supervision demand now while raising post-delivery rate risk. With 89% of orders concentrated in Chinese yards, managers should prepare for quality and delivery-delay risk at emerging builders such as Hengli, and for early-service teething problems from non-standardised specifications.", "url": "https://www.seatrade-maritime.com/tankers/record-vlcc-orders-raise-fears-of-2028-tanker-squeeze"}, {"code": "COMM", "title": "COSCO Shipping Energy Transportation sees 141% first half profit surge", "src": "Seatrade Maritime News", "date": "2026-07-14", "kSum": "코스코 시핑 에너지 트랜스포테이션(COSCO Shipping Energy Transportation)이 2026년 상반기 순이익이 전년 대비 141% 급증한 약 45억 위안(6억 5,300만 달러)에 이를 것으로 전망했다. 발틱거래소 자료 기준 VLCC 핵심 항로인 TD15(서아프리카-중국) 평균 TCE는 상반기 일일 117,773달러로 180% 뛰었고, TD22(미국 걸프-중국)는 111,083달러로 170% 상승했다. 회사는 2월 28일부터 중동 전쟁으로 호르무즈 해협 운항이 급변해 일부 선박이 대기 조치를 취했으며 6월 말까지 모든 발이 묶였던 선박이 안전하게 해협을 빠져나왔다고 밝혔다.", "eSum": "COSCO Shipping Energy Transportation expects H1 2026 net profit attributable to listed shareholders of approximately RMB4.5bn ($653m), up 141% year on year, driven by a sharp increase in global crude tanker freight rates. Baltic Exchange data shows the VLCC TD15 route (West Africa to China) averaged $117,773 per day in H1, up 180% year on year, while TD22 (US Gulf to China) averaged $111,083 per day, up 170%. The company said Hormuz transits faced drastic operational changes from 28 February due to war in the Middle East, with several vessels adopting temporary waiting arrangements before all stranded ships sailed out safely by late June.", "kImp": "중국 최대 유조선사의 실적 급등은 지정학 리스크 프리미엄이 탱커 수익을 얼마나 끌어올렸는지 보여주는 동시에, 선박관리자에게는 호르무즈 대기·비상대응 체계가 실제 운영 과제였음을 확인시켜 준다. 선원 안전 확보, 물자 보급 안정화, 지역별 비상대응 메커니즘 가동은 고위험 해역 운항 선대의 표준 요구사항이 되고 있다.", "eImp": "The surge at China's largest tanker owner shows how far geopolitical risk premiums have lifted tanker earnings, while confirming that Hormuz waiting and emergency response have been a real operational burden for managers. Securing crew safety, stabilising stores and provisions supply, and activating region-specific emergency response mechanisms are becoming standard requirements for fleets trading in high-risk waters.", "url": "https://www.seatrade-maritime.com/tankers/cosco-shipping-energy-transportation-sees-141-first-half-profit-surge"}]}, {"code": "GEO", "type": "news", "kTitle": "Section 17. 지정학", "eTitle": "Section 17. Geopolitics", "items": [{"code": "GEO", "title": "Ukraine Claims 116 Russian Ships Hit in Nine Days in Sea of Azov", "src": "gcaptain.com", "date": "2026-07-14", "kSum": "우크라이나 무인체계군(Unmanned Systems Forces)은 아조프해(Sea of Azov)에서 9일간의 작전으로 러시아 관련 선박 116척을 타격했다고 밝혔다. 야간에만 탱커 5척, 화물선 5척, 예인선 1척이 추가로 피격됐으며, 케르치 해협(Kerch Strait)과 아조프-돈 항로의 상업 선박 통항이 중단됐다. 라브로프(Sergei Lavrov) 러시아 외무장관은 이를 '해적질을 넘어선 테러'라고 비난했고, 도밍게스(Arsenio Dominguez) IMO 사무총장도 공격을 규탄했다.", "eSum": "Ukraine's Unmanned Systems Forces said a nine-day campaign has struck 116 Russian-linked vessels in the Sea of Azov, including five tankers, five cargo ships and a tug overnight. Commercial traffic through the Kerch Strait and Azov-Don channel has been halted. Russian FM Lavrov called the campaign 'terrorism, pure and simple', while IMO Secretary-General Dominguez condemned the attacks on merchant shipping.", "kImp": "상선이 국가 간 분쟁의 직접 표적이 되고 있어 아조프해·흑해 항로 배선 시 전쟁위험 담보와 선원 안전 대책을 전면 재검토해야 한다. 케르치 해협 통항 중단은 러시아 곡물·연료 수출 물류를 재편시켜 흑해·발트해 항만의 체선과 용선 계약 이행 리스크를 키운다.", "eImp": "Merchant ships are now direct targets in a state conflict, forcing ship managers to reassess war-risk cover and crew safety for any Azov/Black Sea deployment. The Kerch Strait closure reroutes Russian grain and fuel flows, raising congestion and charterparty performance risk at Black Sea and Baltic terminals.", "url": "https://gcaptain.com/ukraine-claims-116-russian-ships-hit-in-nine-days-in-sea-of-azov/"}, {"code": "GEO", "title": "U.S. Intensifies Sanctions on Iranian Shipping Network as Naval Blockade Resumes", "src": "gcaptain.com", "date": "2026-07-14", "kSum": "미 재무부 해외자산통제국(OFAC)은 이란 사업가 모하마드 호세인 샴카니(Mohammad Hossein Shamkhani) 네트워크와 연계된 개인·기업·선박 50곳 이상을 제재했으며, 이로써 해당 네트워크 관련 제재 대상은 200곳을 넘어섰다. 지정 대상에는 싱가포르 소재 씨리드 시핑(Sea Lead Shipping)과 자회사 등 컨테이너 선사와 UAE·싱가포르·인도·홍콩·마셜제도·세인트키츠네비스에 걸친 선박관리사가 포함됐다. 제재는 미군이 이란 항만에 대한 해상 봉쇄를 재개한 직후 단행됐다.", "eSum": "OFAC has sanctioned more than 50 individuals, companies and vessels tied to Iranian businessman Mohammad Hossein Shamkhani, bringing total designations linked to the network past 200. Targets include Singapore-based Sea Lead Shipping and subsidiaries, plus shipping managers and vessel-owning entities across the UAE, Singapore, India, Hong Kong, the Marshall Islands and St Kitts and Nevis. The action came hours after US forces resumed the naval blockade of Iranian ports.", "kImp": "제재 대상이 탱커를 넘어 컨테이너 선사와 선박관리사로 확대되어, 관리 선대의 상대방 실사(KYC)와 이차 제재(secondary sanctions) 노출 점검 범위를 넓혀야 한다. 관리회사·선주 법인이 직접 지정된 사례가 나온 만큼 용선자·대리점·벙커 공급업체까지 스크리닝을 강화할 필요가 있다.", "eImp": "Designations now reach beyond tankers into container lines and ship managers, so counterparty KYC and secondary-sanctions exposure checks must widen accordingly. With management and vessel-owning entities named directly, screening should extend to charterers, agents and bunker suppliers.", "url": "https://gcaptain.com/u-s-intensifies-sanctions-on-iranian-shipping-network-as-naval-blockade-resumes/"}, {"code": "GEO", "title": "Ukraine's Azov campaign eclipses the tanker wars of the 1980s", "src": "splash247.com", "date": "2026-07-15", "kSum": "7월 6일 본격화된 우크라이나의 아조프해 작전은 9일간 116척 타격으로, 앰브레이(Ambrey) 자료 기준 일일 공격 빈도에서 1980년대 이란-이라크 탱커 전쟁을 능가하는 역대 최고 밀도의 상선 공격으로 기록되고 있다. 우크라이나는 작전을 흑해로 확대해 하룻밤에 러시아 선박 20척을 타격했다고 주장했다. 러시아는 7월 13~14일 오데사(Odesa) 항과 흑해에서 선박 4척을 타격해 선원 8명이 사망하고 10명이 부상했다.", "eSum": "Ukraine's Azov campaign, which began in earnest on July 6, has hit 116 vessels in nine days — surpassing the Iran-Iraq tanker war of the 1980s in attacks per day, per Ambrey data. Kyiv says it has now expanded the campaign into the Black Sea, claiming 20 Russian vessels hit in one night. Russian strikes on Odesa port and the Black Sea on July 13-14 hit four ships, killing eight seafarers and injuring 10.", "kImp": "선원 8명 사망은 흑해 배선이 더 이상 보험료 문제가 아니라 인명 리스크임을 보여주며, 오데사 기항 선박의 선원 승선 거부·계약 이탈 가능성에 대비해야 한다. 러시아 곡물 수출의 약 4분의 1을 담당하는 아조프 항만 봉쇄는 곡물 물동량 재편과 벌크선 시황 변동으로 이어진다.", "eImp": "Eight seafarer deaths make Black Sea trading a crew-safety issue, not just a premium question — managers should expect refusals to sail and contractual pushback on Odesa calls. With about a quarter of Russian grain moving via Azov ports, the blockade will redraw grain flows and shift bulker trading patterns.", "url": "https://splash247.com/ukraines-azov-campaign-eclipses-the-tanker-wars-of-the-1980s/"}, {"code": "GEO", "title": "South Korea joins the US in probe of container manufacturing giants", "src": "splash247.com", "date": "2026-07-15", "kSum": "한국 공정거래위원회(KFTC)가 싱가마스(Singamas)와 중국 CIMC, 동방국제컨테이너(Dong Fang International Containers), CXIC 등 세계 컨테이너 제조 4사에 대해 2019~2024년 공급 조작 및 가격 담합 혐의로 반독점 조사에 착수했다. 이들 4사는 표준 드라이 컨테이너 세계 생산의 약 95%를 차지한다. 이는 올해 초 미국 법무부가 제기한 형사 사건에 이은 조치로, 미 검찰은 이 담합이 팬데믹 당시 약 350억 달러의 무역 피해를 초래했다고 주장한다.", "eSum": "The Korea Fair Trade Commission has opened an antitrust probe into Singamas, CIMC, Dong Fang International Containers and CXIC over alleged supply manipulation and price-fixing between 2019 and 2024. The four account for an estimated 95% of global standard dry box production. The probe follows a US DOJ criminal case filed earlier this year alleging the cartel caused some $35bn in global trade damages during the pandemic.", "kImp": "컨테이너 제조 과점 구조가 미·한 양국의 규제 표적이 되면서 향후 박스 조달 단가와 공급 안정성에 구조적 변화가 예상된다. 선사·리스사와의 컨테이너 조달 계약을 검토하고, 제조사 제재 시 신조 박스 인도 지연 가능성을 공급망 계획에 반영해야 한다.", "eImp": "With the box-manufacturing oligopoly now targeted by both US and Korean regulators, container procurement pricing and supply stability face structural change. Managers should review box supply contracts with lines and lessors, and factor potential delivery delays into supply-chain planning if manufacturers face penalties.", "url": "https://splash247.com/south-korea-joins-the-us-in-probe-of-container-manufacturing-giants/"}, {"code": "GEO", "title": "US revives Iran blockade after Trump toll U-turn", "src": "splash247.com", "date": "2026-07-15", "kSum": "트럼프(Donald Trump) 미국 대통령은 호르무즈 해협(Strait of Hormuz) 통항 선박에 화물가액의 20%를 부과하려던 계획을 철회하고, 걸프 국가들의 대미 투자로 대체하겠다고 밝혔다. 이란 항만에 대한 미국의 봉쇄는 화요일 2000 GMT부터 재개됐으며, 이란 혁명수비대는 역내 모든 에너지 수출을 차단하겠다고 위협했다. 중개사 인터모달(Intermodal)은 VLCC TD3C 수익이 4거래일 만에 18% 상승해 일일 약 34만 4,000달러에 이르렀다고 전했다.", "eSum": "Trump has dropped his plan to charge ships 20% of cargo value to transit the Strait of Hormuz, replacing it with promises of Gulf investment into the US. The US blockade of Iranian ports resumed from 2000 GMT Tuesday, with Iran's Revolutionary Guard threatening to choke off all regional energy flows. Broker Intermodal said VLCC TD3C earnings jumped 18% in four trading days to around $344,000 per day as hostilities resumed.", "kImp": "합의가 2월 이후 세 번째로 붕괴되면서 중동 걸프 배선에 대한 용선자·선주의 신뢰가 무너져, 호르무즈 통항 가능 여부보다 '거래 가능한 시장인지'가 배선 판단의 핵심이 됐다. 사우디 동서 파이프라인 확장과 UAE 푸자이라(Fujairah) 우회 인프라 확대는 중장기적으로 걸프 화물 흐름을 재편할 수 있다.", "eImp": "With a third arrangement collapsing since February, owner and charterer confidence in Middle East Gulf trading has eroded — the operative question is no longer whether Hormuz is open but whether it is reliably tradable. Saudi East-West pipeline expansion and UAE Fujairah bypass infrastructure could redraw Gulf cargo flows over the medium term.", "url": "https://splash247.com/us-revives-iran-blockade-after-trump-toll-u-turn/"}, {"code": "GEO", "title": "Syrians Outline Future Russian Port Presence in Tartus", "src": "maritime-executive.com", "date": "2026-07-13", "kSum": "시리아 기업 러스라인(Rus Line) 경영진에 따르면 타르투스(Tartus) 구 러시아 해군기지의 두 부두 중 하나는 러시아 해군이 유지하고, 4번 부두는 러시아 상업 화물 처리에 활용될 예정이다. 러스라인은 밀·곡물·사료·식용유·목재·철강 등 월 25만 톤 처리를 목표로 하며, 7월 중순 곡물 3만 톤의 첫 선적이 계획돼 있다. 항만의 나머지 구역은 8억 달러 규모 30년 DP월드(DP World) 양허 대상으로 남아 있다.", "eSum": "Syrian company Rus Line executives say one of the two pierheads of the old Russian naval base at Tartus will be retained by the Russian navy, while Pier 4 will handle Russian commercial cargo. Rus Line is targeting 250,000 tons per month of wheat, grains, feed, vegetable oils, timber and steel, with a first 30,000-ton grain shipment planned for mid-July. The rest of the port remains under an $800m, 30-year DP World concession.", "kImp": "노보로시스크(Novorossiysk)-타르투스 항로가 열리면 우크라이나의 공격 대상이 될 수 있고, 점령지산 곡물 취급 의혹은 화물 출처 실사 부담을 키운다. 시리아 제재는 해제됐으나 러시아 관련 법인 제재는 유효하므로, 해당 항만·물류·금융 서비스 관여 시 OFAC 노출 위험을 반드시 확인해야 한다.", "eImp": "A Novorossiysk-Tartus route would be exposed to Ukrainian attack, and suspected occupied-territory grain raises cargo-provenance due diligence burdens. Syria sanctions have been lifted but Russian-entity sanctions have not, so any port, logistics or financial service involvement must be checked for OFAC exposure.", "url": "https://maritime-executive.com/article/syrians-outline-future-russian-port-presence-in-tartus"}, {"code": "GEO", "title": "Maersk returns West Africa service to the Red Sea as Suez comeback gathers pace", "src": "theloadstar.com", "date": "2026-07-14", "kSum": "머스크(Maersk)가 지중해-서아프리카 WAF6 서비스를 홍해·수에즈 운하(Suez Canal) 경유로 복귀시켰다. 이는 미국 동안-중동 MECL 서비스와 하파크로이드(Hapag-Lloyd)와 공동 운항하는 제미니(Gemini) 아시아-지중해 Loop 2에 이어 최근 수에즈로 복귀한 세 번째 머스크 계열 서비스다. WAF6는 미국-이스라엘-이란 분쟁 발발 후 희망봉 우회로 선박을 5척에서 9~10척까지 늘렸으나, 홍해 복귀로 2~3척을 다른 항로에 재배치할 수 있게 됐다.", "eSum": "Maersk has returned its Mediterranean-West Africa WAF6 service to Red Sea and Suez Canal routing, the third Maersk-linked service to come back to Suez in recent days after the US east coast-Middle East MECL service and the Gemini Asia-Med Loop 2 operated with Hapag-Lloyd. WAF6 had been forced up from five to nine or ten vessels via the Cape of Good Hope after the US-Israel-Iran conflict broke out; reverting to Suez should free two to three ships for redeployment.", "kImp": "수에즈 복귀는 선복 회수 효과로 항로별 톤마일 수요를 줄여 컨테이너 시황에 하방 압력으로 작용할 수 있어 선대 배치 계획에 반영해야 한다. 다만 머스크가 비상계획을 유지 중이고 사우디-후티 간 미사일 공방이 재발한 만큼, 홍해 복귀 서비스의 선원 안전 브리핑과 재우회 시나리오를 준비해 둘 필요가 있다.", "eImp": "The Suez return frees up tonnage and cuts tonne-mile demand, which can weigh on container rates and should feed into fleet deployment planning. But with Maersk keeping contingency plans and Saudi-Houthi missile exchanges resuming, crew safety briefings and re-diversion scenarios remain necessary for any Red Sea routing.", "url": "https://theloadstar.com/maersk-returns-west-africa-service-to-the-red-sea-as-suez-comeback-gathers-pace/"}, {"code": "GEO", "title": "Tariff refund bandwagon rolls on, but SMEs struggling", "src": "theloadstar.com", "date": "2026-07-14", "kSum": "미국 세관국경보호국(CBP)은 국제긴급경제권한법(IEEPA) 관세 환급 신청의 70% 이상을 수용했으며, 총 1,711억 달러 환급 대상 중 약 800억 달러가 이자와 함께 지급됐다. 미 연방대법원이 IEEPA 관세 정책을 무효화한 뒤 화주는 통관일로부터 1년에 180일을 더한 기간 내 청구해야 하며, 2025년 2월 1일 통관 건은 올해 7월 31일이 마감이다. 금액 기준 60%가 수용된 반면 건수 기준으로는 30%에 그쳐 중소 화주가 절차에서 밀려나고 있다는 지적이 나온다.", "eSum": "US Customs has accepted more than 70% of refund applications tied to IEEPA tariffs, with about $80bn of the $171.1bn owed paid out with interest. After the Supreme Court invalidated the IEEPA tariff policy, shippers have one year from entry plus 180 days to file — meaning a 1 February 2025 entry must be claimed by 31 July. While 60% of the value owed has been accepted, that equates to only 30% of entries, suggesting smaller shippers are losing out.", "kImp": "미국향 화물 관련 관세를 부담한 계열사·화주가 있다면 7월 31일 등 임박한 청구 시한을 즉시 점검해야 하며, 놓칠 경우 환급권이 영구 소멸된다. 일부 대형 통관사가 환급액의 10~15%를 수수료로 요구하는 사례가 보고되고 있어, 자체 통관 데이터 확보와 직접 신청 역량 검토가 비용 절감에 직결된다.", "eImp": "Any group company or shipper that paid US tariffs should immediately check imminent filing deadlines such as 31 July, since missing them permanently forfeits the refund right. With reports of large brokers demanding 10-15% of recoveries as a fee, securing in-house customs data and filing directly can translate into material savings.", "url": "https://theloadstar.com/opportunistic-brokers-jumping-on-as-tariff-refund-bandwagon-rolls-on/"}]}, {"code": "TW", "type": "news", "kTitle": "Section 18. TradeWinds 선박관리", "eTitle": "Section 18. TradeWinds Ship Management", "items": [{"code": "TW", "title": "Rubico buys second tanker newbuilding from Pistiolis' Top Ships", "src": "TradeWinds", "date": "2026-07-16", "kSum": "루비코(Rubico)가 에방겔로스 피스티올리스(Evangelos Pistiolis)의 톱 쉽스(Top Ships)로부터 두 번째 탱커 신조선을 매입했다. 유료 구독 기사로 세부 선가와 인도 일정은 확인되지 않았다.", "eSum": "Rubico has bought a second tanker newbuilding from Evangelos Pistiolis' Top Ships. The article is paywalled, so price and delivery details could not be confirmed.", "kImp": "신조선 리세일 거래는 선박관리사에게 신규 관리 계약 기회로 이어진다. 인도 전 단계에서 감독(newbuilding supervision)과 초기 승선 인력 배치 수요가 발생할 수 있다.", "eImp": "Newbuilding resales often translate into fresh management mandates. Managers may see demand for newbuilding supervision and initial crewing ahead of delivery.", "url": "https://www.tradewindsnews.com/tankers/rubico-buys-second-tanker-newbuilding-from-pistiolis-top-ships/2-1-2017370"}, {"code": "TW", "title": "KC Maritime breaks four-year order drought with ultramax bulkers deal in China", "src": "TradeWinds", "date": "2026-07-16", "kSum": "홍콩 선주 KC 마리타임(KC Maritime)이 4년 만에 신조 발주를 재개해 중국 조선소에 울트라막스 벌커를 발주했다. 유료 기사로 척수와 계약 금액은 확인되지 않았다.", "eSum": "Hong Kong owner KC Maritime has ended a four-year newbuilding drought with an order for ultramax bulkers at a Chinese yard. Vessel count and contract value were not confirmable behind the paywall.", "kImp": "중견 벌커 선주의 발주 재개는 건화물선 시장의 신조 사이클 회복 신호다. 중국 건조 울트라막스 증가는 관리사의 조선소 감독 및 인도 후 기술관리 수요를 늘린다.", "eImp": "A mid-sized bulker owner returning to the orderbook signals renewed confidence in the dry bulk newbuilding cycle. More Chinese-built ultramaxes means more yard supervision and post-delivery technical management work.", "url": "https://www.tradewindsnews.com/bulkers/kc-maritime-breaks-four-year-order-drought-with-ultramax-bulkers-deal-in-china/2-1-2017350"}, {"code": "TW", "title": "Greek owner Alberta Shipmanagement returns to Japan for tanker newbuildings", "src": "TradeWinds", "date": "2026-07-15", "kSum": "잉글레시스(Inglessis) 가문이 이끄는 그리스 선주 알버타 쉽매니지먼트(Alberta Shipmanagement)가 아프라막스 탱커 신조를 위해 일본 조선소로 복귀했다. 유료 기사로 척수와 선가는 확인되지 않았다.", "eSum": "Greek owner Alberta Shipmanagement, led by the Inglessis family, has returned to Japanese yards for aframax tanker newbuildings. Numbers and pricing were not readable behind the paywall.", "kImp": "그리스 선주의 일본 조선소 회귀는 고사양 탱커 선호를 보여준다. 일본 건조선은 사양과 검사 체계가 달라 관리사의 신조 감독 역량 배치에 영향을 준다.", "eImp": "Greek owners returning to Japan reflects a preference for high-spec tonnage. Japanese-built ships carry different specifications and survey regimes, which shapes how managers deploy newbuilding supervision resources.", "url": "https://www.tradewindsnews.com/tankers/inglessis-led-alberta-returns-to-japan-for-aframaxes/2-1-2016880"}, {"code": "TW", "title": "Hong Kong start-up inks eight-ship order to move into product tankers and car carriers", "src": "TradeWinds", "date": "2026-07-16", "kSum": "홍콩의 신생 선사가 8척 규모의 신조 계약을 체결하며 석유제품선(product tanker)과 자동차운반선(car carrier) 부문에 진출한다. 유료 기사로 조선소명과 계약 금액은 확인되지 않았다.", "eSum": "A Hong Kong start-up has signed an eight-ship newbuilding order, taking it into product tankers and car carriers. The yard and contract value were not readable behind the paywall.", "kImp": "신규 진입 선주는 자체 관리 조직이 없어 제3자 선박관리사에 위탁할 가능성이 높다. 특히 PCTC 부문 신규 톤수는 전문 관리 역량 수요와 직결된다.", "eImp": "New entrants typically lack in-house management infrastructure and are strong candidates for third-party management. New PCTC tonnage in particular drives demand for specialised management capability.", "url": "https://www.tradewindsnews.com/tankers/hong-kong-start-up-inks-eight-ship-order-to-move-into-product-tankers-and-car-carriers/2-1-2017136"}, {"code": "TW", "title": "JP Morgan VLCC newbuilding splurge tops $1.26bn with fresh orders at Hanwha Ocean", "src": "TradeWinds", "date": "2026-07-16", "kSum": "JP모건(JP Morgan)의 VLCC 신조 발주 규모가 한화오션(Hanwha Ocean) 추가 발주로 12억 6,000만 달러를 넘어섰다. 유료 기사로 추가 발주 척수 등 세부 내용은 확인되지 않았다.", "eSum": "JP Morgan's VLCC newbuilding programme has passed $1.26bn following fresh orders at Hanwha Ocean. The number of additional units and other details were not confirmable behind the paywall.", "kImp": "금융자본의 대형 탱커 발주는 선박을 직접 운영하지 않는 선주 구조로, 제3자 기술관리 수요를 창출한다. 한국 조선소 건조 VLCC 증가는 감독 인력 배치 계획에 영향을 준다.", "eImp": "Financial-investor tonnage implies owners who do not operate ships themselves, creating third-party technical management demand. A growing Korean-built VLCC pipeline also affects supervision staffing plans.", "url": "https://www.tradewindsnews.com/tankers/jp-morgan-vlcc-newbuilding-splurge-tops-1-26bn-with-fresh-orders-at-hanwha-ocean/2-1-2016901"}, {"code": "TW", "title": "Container ship sales fall in first half as owners hold on to tonnage", "src": "TradeWinds", "date": "2026-07-15", "kSum": "2026년 상반기 컨테이너선 매매(S&P) 거래가 감소했으며, 선주들이 보유 선박을 매각하지 않고 유지하는 경향이 나타났다. 유료 기사로 구체적 거래 건수와 통계는 확인되지 않았다.", "eSum": "Container ship sale-and-purchase activity fell in the first half of 2026, with owners holding on to their tonnage rather than selling. Specific transaction counts and figures were not readable behind the paywall.", "kImp": "선박 매각 감소는 관리 선대의 이동(관리사 변경)이 줄어든다는 의미로, 신규 관리 계약 확보 기회가 축소된다. 반면 기존 선대의 장기 보유는 안정적 관리 수익 기반이 된다.", "eImp": "Fewer sales means less churn in managed fleets and fewer opportunities to win new mandates. On the other hand, owners holding tonnage longer supports a stable recurring management revenue base.", "url": "https://www.tradewindsnews.com/containers/container-ship-sales-fall-in-first-half-as-owners-hold-on-to-tonnage/2-1-2017111"}, {"code": "TW", "title": "Owners shun US escorts for Strait of Hormuz transits after ship attacks", "src": "TradeWinds", "date": "2026-07-16", "kSum": "선박 피격 사건 이후에도 선주들이 호르무즈 해협(Strait of Hormuz) 통항 시 미군 호송(escort) 이용을 기피하고 있다. 유료 기사로 기피 사유에 대한 구체적 설명은 확인되지 않았다.", "eSum": "Shipowners are declining US naval escorts for Strait of Hormuz transits despite recent attacks on vessels. The stated reasons were not readable behind the paywall.", "kImp": "호르무즈 통항 리스크 관리와 승선원 안전 대책은 선박관리사의 핵심 현안이다. 호송 이용 여부는 항해 계획, 보험, 전쟁위험구역(War Risk) 대응 절차에 직접 영향을 미친다.", "eImp": "Hormuz transit risk management and crew safety measures are front-line issues for managers. Whether to accept escorts feeds directly into passage planning, insurance and war-risk procedures.", "url": "https://www.tradewindsnews.com/tankers/owners-shun-us-escorts-for-strait-of-hormuz-transits-after-ship-attacks/2-1-2017376"}, {"code": "TW", "title": "Over 100 vessels marooned in Middle East Gulf as window to escape closes", "src": "TradeWinds", "date": "2026-07-15", "kSum": "100척 이상의 선박이 중동 걸프(Middle East Gulf) 해역에 발이 묶였으며, 탈출 가능한 시간적 여유가 닫히고 있다. 유료 기사로 선종별 내역과 선주명은 확인되지 않았다.", "eSum": "More than 100 vessels are stranded in the Middle East Gulf as the window to leave the area closes. A breakdown by vessel type and owner was not readable behind the paywall.", "kImp": "선박 발이 묶이면 승선원 교대(crew change), 식량·보급, 정기 검사 일정이 모두 지연된다. 관리사는 장기 체류 대비 보급 계획과 승선원 피로도 관리 대책을 즉시 검토해야 한다.", "eImp": "Stranded ships mean delayed crew changes, provisioning and scheduled surveys. Managers need contingency plans for extended stays, covering supplies and crew fatigue management.", "url": "https://www.tradewindsnews.com/tankers/over-100-vessels-marooned-in-middle-east-gulf-as-window-to-escape-closes/2-1-2017094"}, {"code": "TW", "title": "Ofac cracks down again on Iranian kingpin's shipping empire", "src": "TradeWinds", "date": "2026-07-15", "kSum": "미국 재무부 해외자산통제국(Ofac)이 이란 관련 핵심 인물의 해운 네트워크에 대해 추가 제재를 부과했다. 유료 기사로 제재 대상 선박과 법인 목록은 확인되지 않았다.", "eSum": "The US Treasury's Office of Foreign Assets Control (Ofac) has imposed further sanctions on an Iranian figure's shipping network. The list of designated vessels and entities was not readable behind the paywall.", "kImp": "제재 명단 확대는 관리 선대의 상대방 실사(counterparty screening)와 용선처 확인 절차 강화를 요구한다. 제재 대상 선박·법인과의 접촉은 관리사에게 직접적인 법적·보험 리스크가 된다.", "eImp": "Expanding designations require tighter counterparty screening and charterer verification across managed fleets. Any exposure to sanctioned vessels or entities carries direct legal and insurance risk for the manager.", "url": "https://www.tradewindsnews.com/law/ofac-cracks-down-again-on-iranian-kingpin-s-shipping-empire/2-1-2017129"}]}, {"code": "HOT", "type": "news", "kTitle": "Section 19. 핫이슈: 호르무즈 해협", "eTitle": "Section 19. Hot Topic: Strait of Hormuz", "items": [{"code": "HOT", "title": "The Southern Route Through Hormuz Is No Longer Safe, Regardless of What Trump Says", "src": "gCaptain", "date": "2026-07-14", "kSum": "지난 화요일 새벽 아드녹 로지스틱스(ADNOC Logistics and Services)가 운항하는 UAE 국적 원유운반선 알 바히야(Al Bahiyah)와 몸바사(Mombasa) 2척이 오만 영해 내 남측 항로를 통항하던 중 이란 혁명수비대(IRGC)의 순항미사일에 피격됐다. 인도 선원 1명이 사망하고 8명이 부상했으며 이 중 4명은 중상이다. gCaptain은 '이란 연안을 피해 오만 쪽에 붙어 항해하면 안전하다'는 업계의 오랜 통념이 이번 공격으로 무너졌으며, 호르무즈는 이제 연안에서 연안까지 전 구간이 균일하게 위험한 해역이 됐다고 분석했다.", "eSum": "Two UAE-flagged crude carriers, Al Bahiyah and Mombasa, both operated by ADNOC Logistics and Services, were struck by Iranian cruise missiles while running the southern traffic lane through Omani territorial waters early Tuesday. One Indian seafarer was killed and eight crew injured, four seriously. gCaptain argues the industry's long-standing rule of thumb — stay off the Iranian side, hug the Omani coast — has now died, and that the Strait has become uniformly contested water from shore to shore.", "kImp": "선박관리자 입장에서 '남측 항로 = 상대적 안전'이라는 항로 선정 논리가 더 이상 성립하지 않으므로, 항로 지정만으로 리스크를 낮추려던 기존 항해계획 전제를 전면 재검토해야 한다. 기사는 전쟁위험보험료가 이란 연안 근접도 기준의 구역별 차등에서 해협 전체 단일 고위험구역으로 재편될 가능성, 용선계약상 전쟁위험 조항 재점검, 선원의 항해 거부권 행사 증가, 그리고 호송(escort) 통항 수요 급증을 예고하고 있어 배승·보험·용선 전반의 대응이 필요하다.", "eImp": "For ship managers, route selection alone can no longer materially reduce risk — the assumption that the southern lane is safer must be removed from voyage planning. The article flags likely repricing of war risk cover across the whole Strait rather than by zone, a need to review charterparty war risk clauses, an expected rise in crew refusals to sail, and mounting demand for naval escort or convoy arrangements.", "url": "https://gcaptain.com/the-strait-of-hormuzs-southern-route-is-no-longer-safe/"}, {"code": "HOT", "title": "Iranian Missile Attacks Hit Three More Tankers as U.S. Expands Strikes, Seafarer Death Toll Rises", "src": "gCaptain", "date": "2026-07-14", "kSum": "영국해사무역기구(UKMTO)가 24시간 동안 3건의 공격 경보를 발령했다. EOS 리스크 그룹(EOS Risk Group)에 따르면 아드녹 운항 탱커 MT 몸바사(IMO 9739501)와 MT 알 바히야(IMO 9937799)가 오만 항로 통항 중 이란 순항미사일에 피격돼 인도 선원 1명이 사망하고 8명(인도 6명·우크라이나 2명)이 부상했다. 세 번째 탱커는 오만 칼하트(Qalhat) 북동 약 40해리 해상에서 미확인 발사체에 우현 기관실이 손상됐으며, 이로써 확인된 선원 사망자는 최소 15명으로 늘었다.", "eSum": "UKMTO issued three attack warnings in 24 hours. Per EOS Risk Group, ADNOC-operated tankers MT Mombasa (IMO 9739501) and MT Al Bahiya (IMO 9937799) were struck by Iranian cruise missiles on the Omani route, killing one Indian crewmember and injuring eight (six Indian, two Ukrainian), four seriously. A third tanker was hit by an unidentified projectile about 40nm northeast of Qalhat, Oman, damaging its starboard engine room with no pollution and all crew accounted for. The confirmed seafarer death toll in the conflict has risen to at least 15, with at least six merchant vessels targeted in the past week.", "kImp": "일주일 새 최소 6척의 상선이 피격되고 사망자가 15명에 이른 것은 호르무즈 통항이 더 이상 관리 가능한 리스크가 아님을 보여준다. CENTCOM이 부셰르·차바하르·자스크·코나라크·아부무사·반다르아바스의 연안방어·미사일·드론 시설을 5시간에 걸쳐 타격했고 JMIC는 위협수준을 SEVERE로 유지 중이므로, 선박관리자는 통항 연기, 선원 심리지원, 사망·부상 시 보상체계, 그리고 IMO 번호 기반 자사 선대의 노출 점검을 즉시 수행해야 한다.", "eImp": "At least six merchant vessels hit in a week and a death toll of 15 shows Hormuz transit is no longer a manageable risk. With CENTCOM striking coastal defence, missile and drone sites at Bushehr, Chah Bahar, Jask, Konarak, Abu Musa and Bandar Abbas, and JMIC holding the threat at SEVERE, managers should weigh deferring transits and review crew welfare support, death and injury compensation arrangements, and their own fleet's exposure.", "url": "https://gcaptain.com/iranian-missile-attacks-hit-three-more-tankers-as-u-s-expands-strikes-seafarer-death-toll-rises/"}, {"code": "HOT", "title": "Trump Drops Proposed 20% Hormuz Fee, Replaces It With Gulf Investment Deals", "src": "gCaptain", "date": "2026-07-14", "kSum": "트럼프 대통령은 호르무즈 해협 통항 화물에 20% 수수료를 부과하겠다는 제안을 철회하고, 대신 걸프 국가들로부터 무역·투자 약속을 받는 방식으로 대체하겠다고 트루스소셜(Truth Social)에 밝혔다. 동시에 미국은 이란 항만을 오가거나 이란 화물을 실은 선박에 한정한 '전면 봉쇄'를 화요일 미 동부시간 오후 4시부터 재개했다. 합동해사정보센터(JMIC)에 따르면 7월 12일 호르무즈 통항은 4척, 13일은 12척에 그쳐 평시 일평균 약 138척에 크게 못 미쳤다.", "eSum": "Trump abandoned his proposed 20% fee on cargo transiting the Strait of Hormuz, saying the US will instead seek trade and investment commitments from Gulf states in return for providing security. At the same time US Central Command began enforcing a renewed blockade — limited to vessels calling at Iranian ports or carrying Iranian cargo — from 4pm ET Tuesday. JMIC reported only four Hormuz transits on July 12 and 12 on July 13, against a historical average of about 138 vessels per day, with just one tanker transit on July 12 and three on July 13.", "kImp": "통항료 부과안 철회로 예상 비용 부담 하나는 사라졌으나, 봉쇄 재개로 중립 선박도 밀수·봉쇄 위반 여부 확인을 위해 정선·승선·검색 대상이 될 수 있다는 점이 실무상 더 중요하다. JMIC는 호르무즈 위협수준을 SEVERE로 유지하고 오만만은 SUBSTANTIAL로 상향했으며, 미 해군 함정으로부터 30해리 이격 유지를 권고하고 있어 항해계획·통신절차·선장 지시서에 즉시 반영해야 한다.", "eImp": "The dropped fee removes one expected cost, but the resumed blockade matters more operationally: neutral vessels transiting between non-Iranian destinations may still be stopped and searched for contraband. JMIC keeps Hormuz at SEVERE and has raised the Gulf of Oman to SUBSTANTIAL, and recommends ships maintain a 30-nautical-mile standoff from US naval units — guidance that should flow straight into passage plans and master's instructions.", "url": "https://gcaptain.com/trump-drops-proposed-20-hormuz-fee-replaces-it-with-gulf-investment-deals/"}, {"code": "HOT", "title": "Red Sea Shipping Faces Renewed Risk as Iran Signals Pressure Beyond Hormuz", "src": "gCaptain (Reuters)", "date": "2026-07-14", "kSum": "호르무즈 해협 통항을 사실상 봉쇄한 이란이 이제 예멘 후티(Houthi) 세력을 동원해 바브엘만데브(Bab el-Mandeb) 해협까지 차단할 수 있다는 신호를 보내고 있다고 로이터가 보도했다. 안사룰라(Ansarullah) 정치국원 모하메드 알파라(Mohammed al-Farah)는 사우디가 예멘 공격을 계속할 경우 바브엘만데브와 호르무즈를 동시에 봉쇄할 수 있으며 유가가 배럴당 200달러까지 치솟을 것이라고 경고했다. 전문가들은 이란이 세계 2대 에너지 수송로를 동시에 위협하는 국면으로 분쟁을 확대하고 있다고 분석했다.", "eSum": "Having choked off shipping through the Strait of Hormuz, Iran is now signalling it could use its Houthi allies to shut the Bab el-Mandeb gateway to the Red Sea, opening a second front. A senior Ansarullah political bureau member, Mohammed al-Farah, warned that if the situation worsens both Bab el-Mandeb and Hormuz would be closed in an 'operational alliance', sending oil to $200 a barrel. Analysts told Reuters Tehran is widening the conflict to threaten two of the world's most vital energy arteries simultaneously.", "kImp": "호르무즈를 회피해 홍해·수에즈 경로로 우회하려는 대체 계획 자체가 무력화될 수 있다는 뜻으로, 선박관리자는 두 초크포인트가 동시에 막히는 시나리오를 전제로 희망봉 우회 및 벙커·용선기간·선원 교대 계획을 다시 짜야 한다. 후티의 상선 공격 전력(2023년 10월 이후)을 고려할 때 홍해 통항 선대의 전쟁위험보험·경계태세도 선제적으로 재점검할 필요가 있다.", "eImp": "A simultaneous closure of Hormuz and Bab el-Mandeb would neutralise the obvious workaround of rerouting Gulf cargoes via the Red Sea, so managers should plan for Cape of Good Hope routing with the associated bunker, charter duration and crew rotation consequences. Given the Houthis' demonstrated record against merchant shipping since October 2023, war risk cover and vigilance postures for Red Sea transits warrant pre-emptive review.", "url": "https://gcaptain.com/red-sea-shipping-faces-renewed-risk-as-iran-signals-pressure-beyond-hormuz/"}, {"code": "HOT", "title": "Rescuers Search for Crew Member After Container Ship Attack in Strait of Hormuz", "src": "gCaptain (Reuters)", "date": "2026-07-13", "kSum": "키프로스 국적 컨테이너선 GFS 갤럭시(GFS Galaxy)가 일요일 새벽 호르무즈 해협 통항 중 '미확인 발사체'에 피격됐다고 키프로스 해운부(DMS)가 밝혔다. 선원들은 구명정으로 퇴선했고 23명이 오만 해군에 구조됐으나, 3등기관사 계급의 인도 선원 1명은 실종 상태다. 선박은 UAE 코르파칸(Khor Fakkan) 항 최근접 안전묘박지로 예인 중이며 예인팀이 실종자 수색을 병행하고 있다. 이란 혁명수비대 해군은 해당 선박이 '시스템을 끈 채' 경고에도 불구하고 비인가 항로로 통항해 해상안전을 위협했다며 정지시켰다고 주장했다.", "eSum": "The Cyprus-flagged container ship GFS Galaxy was struck by an 'unidentified projectile' while transiting the Strait of Hormuz early Sunday, Cyprus's Deputy Ministry of Shipping said. The crew abandoned ship by lifeboat and 23 were rescued by the Oman Navy, but one Indian crew member, a third engineer, remains missing. The vessel is under tow toward the nearest safe anchorage at Khor Fakkan, UAE, with the towing team conducting a search. Iran's IRGC navy said it struck and halted a vessel that had 'jeopardized maritime security by switching off its systems' and attempted an unauthorized route despite warnings.", "kImp": "탱커뿐 아니라 컨테이너선도 표적이 되고 있으며, 특히 IRGC가 'AIS를 끈 것' 자체를 공격 정당화 사유로 명시적으로 언급한 점이 중요하다. 즉 다크 통항이 리스크 경감책이 아니라 오히려 피격 명분이 될 수 있다는 뜻으로, AIS 차단 방침을 검토 중인 선사는 이 사례를 반드시 반영해야 한다. 퇴선·구명정 운용·인근 해군과의 조난 연락체계, 실종자 수색 및 가족 대응 절차의 실효성 점검도 필요하다.", "eImp": "Container ships, not just tankers, are being targeted — and critically, the IRGC explicitly cited the vessel switching off its systems as justification for the strike, meaning dark transit may invite attack rather than mitigate risk. Any owner weighing an AIS-off policy must factor this in. The case also tests abandon-ship and lifeboat procedures, distress liaison with nearby navies, and missing-crew search and next-of-kin response arrangements.", "url": "https://gcaptain.com/rescuers-search-for-crew-member-after-container-ship-attack-in-strait-of-hormuz/"}]}, {"code": "SYS", "type": "news", "kTitle": "Section 20. 시스템·앱", "eTitle": "Section 20. System & App", "items": [{"code": "SYS", "title": "Indian Register of Shipping launches NEURON digital platform for class rules", "src": "Smart Maritime Network", "date": "2026-07-14", "kSum": "인도선급(IRClass, Indian Register of Shipping)이 선급 규칙·분류 노트·기술 간행물에 빠르게 접근할 수 있는 디지털 플랫폼 '뉴런(NEURON)'을 출시했다. 검색 가능한 데이터베이스로 설계·건조·운항 컴플라이언스 평가 과정에서 규제 정보 검색을 간소화하도록 만들어졌다. 시스템은 현재 가동 중이며 IRClass 웹사이트의 전용 포털을 통해 접속할 수 있다.", "eSum": "The Indian Register of Shipping (IRClass) has launched NEURON, a digital platform providing faster access to its class rules, classification notes and technical publications. The searchable database streamlines retrieval of regulatory information during ship design, construction and operational compliance assessments. The system is live and accessible through a dedicated portal on the IRClass website.", "kImp": "IRClass 입급 선박을 관리하는 기술팀은 PDF 규칙집을 뒤지는 대신 통합 검색으로 근거 조항을 찾을 수 있어 검사 준비와 개조 검토 속도가 빨라진다. 선급별 규칙 디지털화가 확산되는 흐름이므로 사내 문서관리 시스템과의 연계 여부를 확인해 둘 필요가 있다.", "eImp": "Technical teams managing IRClass-classed tonnage can search for the governing rule text instead of trawling PDFs, speeding survey preparation and conversion reviews. As rule digitalisation spreads across class societies, check how it links to your in-house document management system.", "url": "https://smartmaritimenetwork.com/2026/07/14/irs-launches-digital-platform-for-class-rules/"}, {"code": "SYS", "title": "Uni-Tankers deploys Sofar Ocean Wayfinder voyage optimisation platform fleetwide", "src": "Smart Maritime Network", "date": "2026-07-02", "kSum": "덴마크 탱커 선사 유니탱커스(Uni-Tankers)가 소파 오션(Sofar Ocean)과 파트너십을 맺고 항해 최적화 플랫폼 '웨이파인더(Wayfinder)'를 전 선대에 도입한다. 현재 44척을 운항 중인 이 회사는 항로·속도 결정 지원과 선박·육상 팀 간 협업 개선에 이 기술을 활용할 예정이다. 이 시스템은 실시간 해양 기상 정보와 선박별 디지털 트윈 성능 모델을 결합하며, 소파 오션은 2025년 실적 기준 항해당 평균 6.9%의 연료 절감을 제시했다.", "eSum": "Danish tanker owner Uni-Tankers has signed a partnership with Sofar Ocean to deploy its Wayfinder voyage optimisation platform across its 44-vessel fleet. The technology will support route and speed decisions and improve ship-shore team coordination. Wayfinder combines real-time marine weather intelligence with vessel-specific digital twins; Sofar Ocean cites average fuel savings of 6.9% per voyage from 2025 performance data.", "kImp": "항해 최적화 도구 선정 시 유니탱커스가 여러 대안을 충분히 검토·시험한 뒤 결정했다는 점은 벤치마킹 가치가 있다. 6.9% 연료 절감은 벤더 제시 수치이므로 자사 선대 적용 시 파일럿 검증이 필요하지만, CII·FuelEU 대응 관점에서 선박관리사가 검토할 만한 수단이다.", "eImp": "Uni-Tankers reviewed and trialled multiple options before selecting Wayfinder — a useful benchmark for managers running their own tool selection. The 6.9% saving is a vendor figure and needs pilot validation on your own fleet, but the tool is worth reviewing for CII and FuelEU compliance.", "url": "https://smartmaritimenetwork.com/2026/07/02/uni-tankers-implements-sofar-ocean-platform-for-voyage-optimisation/"}, {"code": "SYS", "title": "Lloyd's List Intelligence launches Vessel Due Diligence risk platform on Seasearcher", "src": "Splash247", "date": "2026-07-13", "kSum": "로이드리스트 인텔리전스(Lloyd's List Intelligence)가 자사 시서처(Seasearcher) 플랫폼 내 신규 모듈 '베슬 듀 딜리전스(Vessel Due Diligence)'를 출시했다. 선박 이력, 검사 기록, 사고 보고, 행태 기반 위험 지표를 하나의 워크플로로 통합해 해상보험사·선박 베팅팀·용선주의 운항 리스크 평가를 지원한다. 사고·검사·결함·억류, 선급 및 P&I 가입 상태, 입거 이력, 과거 기항 분석을 함께 제공한다.", "eSum": "Lloyd's List Intelligence has launched Vessel Due Diligence, a new module within its Seasearcher platform, to help marine insurers, vetting teams and charterers assess operational risk faster. It consolidates vessel histories, inspection records, incident reports and behavioural risk indicators into a single workflow, covering incidents, deficiencies, detentions, class and P&I status, drydock history and historic port calls.", "kImp": "선박관리사의 선박도 상대방 베팅 대상이 되므로, 억류·결함·입거 이력이 이런 통합 도구로 즉시 조회된다는 점을 인식해야 한다. PSC 결함 이력 관리와 검사 기록 정합성이 곧바로 용선 기회에 영향을 미칠 수 있다.", "eImp": "Managed vessels are themselves the subject of counterparty vetting, so detentions, deficiencies and drydock history are now instantly visible through tools like this. Keeping PSC deficiency records clean and inspection data consistent directly affects chartering opportunities.", "url": "https://splash247.com/lloyds-list-intelligence-launches-vessel-risk-platform/"}, {"code": "SYS", "title": "Sedna acquires AI startup Bridge Labs, names founder Alex Crooks chief product officer", "src": "Splash247", "date": "2026-07-14", "kSum": "해운 커뮤니케이션 소프트웨어 기업 세드나(Sedna)가 AI 스타트업 브리지 랩스(Bridge Labs)를 인수해 해운·원자재 거래의 자동화 워크플로 개발을 가속한다. 브리지 랩스 창업자 알렉스 크룩스(Alex Crooks)가 세드나의 최고제품책임자(CPO)로 선임됐다. 브리지 랩스는 올해 초 AI 워크플로 기업 더 시핑 봇(The Shipping Bot)과 합병했으며, 루이 드레퓌스·글렌코어·MOL 케미컬 탱커스·올덴도르프 등을 대상으로 5개의 상용 AI 제품을 출시한 바 있다.", "eSum": "Maritime communications software firm Sedna has acquired AI startup Bridge Labs to accelerate development of automated workflows for shipping and commodities transactions. Bridge Labs founder Alex Crooks becomes Sedna's chief product officer. Bridge Labs merged earlier this year with AI workflow firm The Shipping Bot and has shipped five commercial AI products for customers including Louis Dreyfus, Glencore, MOL Chemical Tankers and Oldendorff.", "kImp": "세드나는 하루 1,000만 통 이상의 이메일을 처리하며 해운업계 최대 비정형 데이터 흐름을 보유하고 있어, 이 데이터에 AI 워크플로가 결합되면 용선·오퍼레이션 업무의 자동화 수준이 빠르게 올라갈 수 있다. 이메일 기반 업무가 많은 선박관리 조직은 유사 도구 도입 시 데이터 보안·기밀 유지 조건을 계약 단계에서 명확히 해야 한다.", "eImp": "Sedna processes over 10 million emails a day and holds shipping's largest unstructured data flow; layering AI workflows onto it could rapidly raise automation in chartering and operations. Ship managers whose work is email-heavy should pin down data security and confidentiality terms at contract stage when adopting similar tools.", "url": "https://splash247.com/sedna-expands-ai-ambitions-with-bridge-labs-deal/"}, {"code": "SYS", "title": "CyberLogitec wins TOS and digital twin project at HMM-backed TTI Algeciras", "src": "Splash247", "date": "2026-07-14", "kSum": "한국 해운물류 IT 기업 사이버로지텍(CyberLogitec)이 스페인 알헤시라스항의 TTI 알헤시라스(TTI Algeciras) B1 확장 프로젝트에 터미널운영시스템(TOS)과 디지털 트윈 솔루션을 공급하는 계약을 체결했다. TTI 알헤시라스는 HMM과 CMA CGM 계열 투자사가 공동 보유한 반자동화 컨테이너 터미널이다. 사이버로지텍은 OPUS Terminal 플랫폼과 디지털 트윈을 배치해 선박·야드·게이트·장비 운영을 통합 관리하며, 터미널 연간 처리능력은 2028년까지 160만 TEU에서 210만 TEU로 확대될 예정이다.", "eSum": "Korean maritime IT firm CyberLogitec has signed an agreement to supply its terminal operating system (TOS) and digital twin technology for the B1 Expansion Project at TTI Algeciras, a semi-automated container terminal in Spain jointly owned by HMM and a CMA CGM-affiliated investment firm. CyberLogitec will deploy its OPUS Terminal platform and digital twin to manage vessel, yard, gate and equipment operations. Terminal capacity is set to rise from 1.6m TEU to 2.1m TEU by 2028.", "kImp": "한국 해운 IT 기업이 유럽 반자동화 터미널의 핵심 시스템을 수주했다는 점은 국내 벤더의 레퍼런스 확대를 의미하며, 터미널 디지털 트윈이 확산되면 선박 측 기항 계획·접안 정보의 정밀도도 함께 올라간다. HMM 지분 터미널이라는 점에서 국내 선사·관리사의 유럽 기항 오퍼레이션에도 파급 효과가 있다.", "eImp": "A Korean maritime IT vendor winning core systems at a European semi-automated terminal broadens domestic vendors' reference base, and wider terminal digital twins should improve the precision of port call and berthing information on the ship side. As an HMM-stake terminal, it also has knock-on effects for Korean owners' and managers' European port operations.", "url": "https://splash247.com/cyberlogitec-wins-digital-twin-project-at-tti-algeciras/"}, {"code": "SYS", "title": "MOL and IBM Japan launch AI platform for vessel operations decision support", "src": "MarineLink", "date": "2026-07-01", "kSum": "미쓰이 O.S.K. 라인(MOL)과 일본 IBM(IBM Japan)이 운항·기상·지정학 정보를 통합해 선박 운항 의사결정을 지원하는 AI 플랫폼을 공동 개발해 7월 1일 가동에 들어갔다. 이 플랫폼은 전 세계 MOL 관계 선박의 안전운항을 감시·지원하는 안전운항지원센터(SOSC)를 중심으로 운용된다. 생성형 AI 기반 어시스턴트가 과거 운항 기록과 현재 정보를 바탕으로 선박이 직면한 리스크를 실시간으로 식별·추출해 상황 판단과 우선순위 결정을 돕는다.", "eSum": "Mitsui O.S.K. Lines (MOL) and IBM Japan have jointly developed an AI-powered platform integrating operational, weather and geopolitical information to support vessel operations decision-making, which went live on 1 July. It is centred on MOL's Safety Operation Supporting Center (SOSC), which monitors MOL-affiliated vessels worldwide. A generative-AI assistant identifies and extracts risks facing vessels in real time from historical operation records and current data, supporting situation assessment and prioritisation.", "kImp": "기상·항로·지정학 정보가 흩어져 있어 담당자가 수동으로 취합하던 관행은 대부분의 선박관리사에 공통된 문제이므로, MOL의 통합 접근은 자사 운항지원 체계 설계의 참고 사례가 된다. 특히 호르무즈·홍해 등 지정학 리스크가 상시화된 국면에서 리스크 식별 속도가 곧 사고 예방 역량으로 직결된다.", "eImp": "Most ship managers share the same problem of weather, routeing and geopolitical data sitting in separate places and being pulled together by hand, so MOL's integrated approach is a useful reference for designing your own operations support setup. With geopolitical risk now permanent around Hormuz and the Red Sea, speed of risk identification translates directly into accident prevention capability.", "url": "https://www.marinelink.com/news/mol-ibm-japan-launch-ai-platform-vessel-540811"}, {"code": "SYS", "title": "Fleet Management's Pulse crew app passes 7,000 downloads across 27,000 seafarers", "src": "Digital Ship", "date": "2026-07-10", "kSum": "선박관리사 플릿 매니지먼트(Fleet Management)의 신규 모바일 앱 '펄스(Pulse)'가 출시 수 주 만에 7,000건 이상 다운로드를 기록하며 초기 목표 1,000건을 크게 넘어섰다. 600척 이상 관리 선박에 승선하는 27,000명의 선원을 위해 개발된 이 앱은 승선 전 요구사항, 계약서, 증서, 배승 업데이트, 경력 기록을 웰빙 지원 자원과 함께 단일 모바일 플랫폼에 통합했다. 로그인하면 직책·항해 상태·경력 단계에 맞춘 개인화된 홈 화면이 제공된다.", "eSum": "Ship manager Fleet Management's new Pulse mobile app has exceeded 7,000 downloads within weeks of launch, well ahead of its initial 1,000 target. Built for the company's 27,000 seafarers across more than 600 managed vessels, Pulse combines pre-joining requirements, contracts, certificates, assignment updates and career records with Fleet Care wellbeing resources in a single mobile platform. After login, seafarers get a personalised home screen tailored to role, voyage status and career stage.", "kImp": "선원이 여러 시스템을 오가지 않고 서류·배승·복지 정보를 한 앱에서 처리하도록 만든 사례로, 선원 행정 부담과 문의 응대 공수를 동시에 줄이는 접근이다. 선원 유지율과 MLC 준수 문서 관리가 과제인 관리사에게 벤치마크가 되며, 개인정보·건강정보 취급 정책의 정비가 전제 조건이다.", "eImp": "A clear case of putting documents, assignments and welfare into one app so crews no longer navigate multiple systems, cutting both seafarer admin burden and the shore team's query load. It is a useful benchmark for managers wrestling with retention and MLC document control, provided personal and health data handling policies are set up first.", "url": "https://thedigitalship.com/news/maritime-software/fleet-managements-pulse-passes-7000-downloads-as-ship-manager-expands-digital-support-for-27000-seafarers/"}, {"code": "SYS", "title": "Norwegian Cruise Line Holdings adopts ZeroNorth platform to digitise bunker procurement", "src": "Digital Ship", "date": "2026-07-10", "kSum": "노르위전 크루즈 라인 홀딩스(NCLH)가 전 세계 크루즈 선대의 연료 구매 디지털화 전략의 일환으로 제로노스(ZeroNorth)의 벙커 조달 솔루션(Bunker Procurement Solution)을 선정했다. 이 플랫폼은 조달 데이터, 공급사 소통, 구매 워크플로를 단일 디지털 시스템으로 통합한다. 실시간 가격 정보, 공급사 이력, 배출 영향 계산 기능을 제공해 FuelEU와 EU ETS 노출을 포함한 구매의 총비용을 발주 전에 확인할 수 있게 한다.", "eSum": "Norwegian Cruise Line Holdings (NCLH) has selected ZeroNorth's Bunker Procurement Solution as part of its strategy to digitise fuel purchasing across its global cruise fleet. The platform brings procurement data, supplier engagement and purchasing workflows into a single digital system. It offers live price intelligence, supplier history and emissions impact calculations to show the full cost of a purchase — including FuelEU and EU ETS exposure — before the order is placed.", "kImp": "발주 전에 FuelEU·EU ETS 비용까지 포함한 총비용을 보여준다는 점이 핵심으로, 연료 단가만 보고 결정하던 관행에서 벗어나야 하는 현 규제 환경을 정확히 반영한다. 선박관리사가 벙커 조달을 대행하는 경우 규제 비용을 반영한 비교 견적 체계를 갖췄는지 점검할 필요가 있다.", "eImp": "The key point is showing total cost including FuelEU and EU ETS exposure before the order is placed — exactly what the current regulatory environment demands, versus deciding on fuel unit price alone. Managers who handle bunker procurement on owners' behalf should check whether their comparison quotes actually price in regulatory cost.", "url": "https://thedigitalship.com/news/maritime-software/norwegian-cruise-line-holdings-adopts-zeronorth-digital-platform-to-modernise-bunker-procurement/"}, {"code": "SYS", "title": "Marcura acquires US demurrage claims specialist Fairway Maritime", "src": "Digital Ship", "date": "2026-07-15", "kSum": "해운 소프트웨어·서비스 그룹 마큐라(Marcura)가 미국 체선료(demurrage) 클레임 전문업체 페어웨이 마리타임(Fairway Maritime)의 사업 자산을 인수했다. 이번 인수로 북미 관리형 클레임 사업과 AI 기반 체선료 처리 플랫폼이 강화된다. 2005년 설립된 페어웨이는 선주·선박풀·정유사·트레이딩 회사를 대상으로 체선료, 이로(deviation), 시프팅, 디텐션 등 클레임 전 과정을 관리해 왔으며, 앞선 HubSE·Shipdem 인수에 이어 마큐라 클레임스(Marcura Claims)는 물량 기준 업계 최대 정박기간 처리 사업자가 됐다.", "eSum": "Maritime software and services group Marcura has acquired the business assets of US-based demurrage claims specialist Fairway Maritime, strengthening its managed claims business in North America and expanding its AI-assisted demurrage platform. Founded in 2005, Fairway manages the full claims process — demurrage, deviation, shifting and detention — for shipowners, vessel pools, refiners and traders. Following earlier acquisitions of HubSE and Shipdem, Marcura Claims is now the industry's largest laytime processor by volume.", "kImp": "체선료 클레임은 항해당 회수 금액이 크지만 인력 집약적이어서 AI 처리로 옮겨가는 흐름이 뚜렷하다. 선박관리사가 상업관리까지 맡는 경우 자사 정박기간 계산 역량과 외주 관리형 서비스의 비용·정확도를 비교 검토할 시점이며, 벤더 통합이 진행될수록 협상력 저하도 함께 고려해야 한다.", "eImp": "Demurrage claims carry meaningful per-voyage recoveries but are labour-intensive, and the shift to AI-assisted processing is now clear. Managers who also handle commercial management should compare in-house laytime capability against outsourced managed services on cost and accuracy — while noting that continued vendor consolidation erodes negotiating leverage.", "url": "https://thedigitalship.com/news/maritime-software/ai-is-reshaping-demurrage-marcura-acquires-fairway-maritime/"}, {"code": "SYS", "title": "NAVTOR expands e-navigation platform to about 18,000 vessels after Voyager migration", "src": "PortNews", "date": "2026-07-09", "kSum": "나브토르(NAVTOR)가 보이저 월드와이드(Voyager Worldwide) 고객의 자사 기술 이관을 완료하며 e-내비게이션 플랫폼을 약 1만8천척 규모로 확대했다. 2023년 보이저 해도 사업 인수로 최대 경쟁사를 흡수해 전자해도 유통 부문 세계 최대 점유율을 확보한 결과다. 나브토르는 확대된 해도 기반 위에 배출 규제 대응, 전자 항해일지, 선내 시스템과 육상 운영의 연계를 더해 종합 선박 소프트웨어 플랫폼을 구축 중이며, MOL과 전자 항해일지 프로젝트를 진행하고 일본을 차기 성장 핵심 시장으로 삼고 있다.", "eSum": "NAVTOR has expanded its e-navigation platform to about 18,000 vessels after completing the migration of Voyager Worldwide customers onto its technology. This followed NAVTOR's 2023 acquisition of Voyager's chart business, which absorbed one of its largest competitors and gave the Norwegian group the largest global share in electronic chart distribution. NAVTOR is using the enlarged chart base to build a broader vessel software platform adding emissions regulation services, digital logbooks and tighter ship-shore links, and is working with MOL on electronic logbooks with Japan a key next growth market.", "kImp": "전자해도 유통이 사실상 단일 사업자 중심으로 재편되면서 해도·항해일지·성능 데이터가 한 벤더에 묶이는 구조가 되고 있어, 관리사는 계약 갱신 시 가격 인상과 데이터 이식성(portability) 조항을 반드시 점검해야 한다. 반대로 항해일지 전자화와 센서 자동 입력이 확산되면 선원 서류 작업 경감 효과는 실질적이다.", "eImp": "With electronic chart distribution consolidating around effectively one dominant supplier, charts, logbooks and performance data increasingly sit with a single vendor — so managers must scrutinise price escalation and data portability clauses at renewal. On the upside, spreading logbook digitalisation with automatic sensor input delivers real relief from crew paperwork.", "url": "https://en.portnews.ru/news/393966/"}, {"code": "SYS", "title": "Stena Line completes fleet-wide rollout of Telko TELSCOPE electronic record book on 32 vessels", "src": "Telko", "date": "2026-07-09", "kSum": "스테나 라인(Stena Line)이 RoPax·RoRo 선대 32척 전 선박에 텔코(Telko)의 TELSCOPE 전자기록부(Electronic Record Book) 시스템 배치를 완료하며 2021년 시작한 무서류 보고 프로그램을 마무리했다. 이 시스템은 종이 항해일지와 체크리스트를 전자 기록으로 대체하고, 선내 센서 데이터를 활용해 운항·규제·환경 보고를 단일 연결 플랫폼에서 처리한다. 스테나 라인은 데이터 자동 수집으로 수작업 보고가 줄고 투명한 감사 추적으로 데이터 품질이 개선됐다고 밝혔으며, MARPOL 보고는 선박에서 육상으로 자동 전송된다.", "eSum": "Stena Line has completed deployment of Telko's TELSCOPE Electronic Record Book across all 32 vessels in its RoPax and RoRo fleet, finishing a paperless reporting programme begun in 2021. The system replaces paper logbooks and checklists with electronic records that use onboard sensor data to support operational, regulatory and environmental reporting on a single connected platform. Stena Line says it reduces manual reporting through automated data capture while improving data quality via a transparent audit trail, with MARPOL reporting transferred automatically from ship to shore.", "kImp": "전자기록부는 MARPOL 개정으로 이미 허용된 방식이지만, 32척 전 선대 완료까지 2021년부터 5년이 걸렸다는 점은 실제 전환 난이도를 보여준다. 센서 데이터 자동 채움으로 기록 위·변조 리스크와 PSC 지적을 줄일 수 있어 기술팀이 도입 로드맵을 세울 때 참고할 사례다.", "eImp": "Electronic record books are already permitted under amended MARPOL, but the fact that the 32-vessel rollout took five years from 2021 shows the real difficulty of transition. Auto-populating records from sensor data reduces falsification risk and PSC findings, making this a useful reference when technical teams build their own adoption roadmap.", "url": "https://telko.no/2026/07/09/stena-line-completes-fleet-wide-rollout-of-telscope/"}, {"code": "SYS", "title": "Hanwha Ocean adopts Rakuten Maritime integrated vessel cybersecurity solution", "src": "Hankyung (한국경제)", "date": "2026-07-09", "kSum": "라쿠텐 마리타임(Rakuten Maritime)이 한화오션과 선박 사이버보안 통합 솔루션 도입 계약을 체결했다. 한화오션은 설계 단계부터 보안을 체계적으로 반영해 선박 생애주기 기반의 사이버 위험 관리 체계를 구축할 예정이다. 설계 단계에서 위협 분석 모듈로 잠재적 사이버 위험을 분석하고, 선박에 탑재되는 주요 기자재에 대해 보안 위험성 평가를 수행하며, 현재 건조 중인 일부 선박에는 위험 관리 모듈을 적용할 계획이다.", "eSum": "Rakuten Maritime has signed an agreement with Hanwha Ocean to deploy its integrated vessel cybersecurity solution. Hanwha Ocean will build a vessel-lifecycle cyber risk management framework with security designed in from the earliest stages. It will use threat analysis modules during design to identify potential cyber risks, run security risk assessments on key onboard equipment, and apply risk management modules to selected vessels currently under construction.", "kImp": "IACS UR E26·E27이 적용되면서 사이버 보안이 인도 시점의 확인 항목이 되고 있어, 조선소 단계에서 보안 설계가 반영된 선박을 인수하는 관리사는 인도 후 대응 부담이 줄어든다. 신조 감독 시 사이버 보안 요구사항과 기자재 위험성 평가 결과를 인도 문서에 포함시킬 것을 요구해야 한다.", "eImp": "With IACS UR E26/E27 now in force, cyber security has become a delivery-stage verification item, so managers taking over vessels with security built in at the yard face less remediation after delivery. During newbuilding supervision, insist that cyber security requirements and equipment risk assessment results are included in the delivery documentation.", "url": "https://www.hankyung.com/article/202607095333O"}]}, {"code": "SMGR", "type": "news", "kTitle": "Section 21. 선박관리사", "eTitle": "Section 21. Ship Managers", "items": [{"code": "SMGR", "title": "V.Group presents first Annual Safety Catch Award to seafarer in Lagos", "src": "V.Group", "date": "2026-07-07", "kSum": "브이그룹(V.Group)이 제1회 연례 세이프티 캐치 어워드(Annual Safety Catch Award)를 나이지리아 라고스에서 화부 제임스 샤이부(James Shaibu)에게 수여했다. 이 상은 위험 요소를 선제적으로 보고한 선원의 공로를 인정하는 제도로, 2025년 수상자가 첫 사례가 됐다. 본선 근무지가 아닌 선원의 모항에서 시상식을 진행한 점이 특징이다.", "eSum": "V.Group presented Fireman James Shaibu with the 2025 V.Group Annual Safety Catch Award at his home port of Lagos, Nigeria. The award is the first of its kind for the group and recognises seafarers who proactively report hazards under the company's Safety Catch reporting scheme.", "kImp": "선원의 자발적 위험 보고를 포상 제도로 제도화한 사례로, 선박관리사의 안전문화(Safety Culture) 정착과 니어미스 보고율 제고에 직접적인 참고가 된다. 모항 시상이라는 방식은 선원 유지율(retention)과 소속감 제고 측면에서도 벤치마킹 가치가 있다.", "eImp": "Shows how a major ship manager institutionalises proactive hazard reporting through recognition — directly relevant to raising near-miss reporting rates and embedding safety culture. The home-port ceremony format is also a retention and engagement lever worth benchmarking.", "url": "https://vgrouplimited.com/presenting-the-first-v-group-annual-safety-catch-award/"}, {"code": "SMGR", "title": "V. and International Seaways' female cadet programme enters second year", "src": "V.Group", "date": "2026-05-18", "kSum": "브이십스(V.Ships)와 인터내셔널 시웨이스(International Seaways)가 공동 운영하는 여성 캐뎃 프로그램이 2년차에 접어들었다. 세계 여성 해양인의 날(International Day for Women in Maritime)에 맞춰 발표됐으며, 해상 인력의 성별 다양성 확대와 인력난 대응을 목표로 한다.", "eSum": "On the International Day for Women in Maritime, V.Ships and International Seaways Inc. marked the second year of their joint female cadet programme, aimed at improving gender diversity at sea and addressing the industry's skills shortage.", "kImp": "선원 부족이 심화되는 상황에서 선박관리사가 선주와 공동으로 캐뎃 파이프라인을 구축한 모델이다. 여성 인력 확보는 장기 선원 공급 안정화와 선주사 ESG 요구 대응에 동시에 기여한다.", "eImp": "A model of a ship manager building a cadet pipeline jointly with an owner amid tightening seafarer supply. Recruiting women addresses both long-term crew supply stability and owners' ESG expectations.", "url": "https://vgrouplimited.com/female-cadets-programme-in-partnership-with-insw-2/"}, {"code": "SMGR", "title": "Anglo-Eastern marks Day of the Seafarer 2026 with CEO message on seafarers' role", "src": "Anglo-Eastern", "date": "2026-06-25", "kSum": "앵글로-이스턴(Anglo-Eastern)이 2026년 선원의 날(Day of the Seafarer)을 맞아 비외른 호이고르(Bjorn Hojgaard) CEO의 메시지를 공개했다. CEO는 세계 무역에서 선원이 수행하는 핵심적 역할과 이들이 직면한 위험을 강조했다.", "eSum": "Anglo-Eastern marked Day of the Seafarer 2026 with a message from CEO Bjorn Hojgaard on the vital role seafarers play in global trade and the risks they face.", "kImp": "지정학적 위험이 고조된 시기에 최고경영진이 직접 선원 복지와 위험 노출을 언급한 것은 선원 신뢰 확보와 대외 커뮤니케이션 측면에서 의미가 있다. 선박관리사의 선원 유지 전략에서 경영진 메시지의 역할을 보여준다.", "eImp": "Senior leadership speaking directly to seafarer welfare and risk exposure matters for crew trust at a time of heightened geopolitical risk, and illustrates the role of executive messaging in a ship manager's retention strategy.", "url": "https://www.angloeastern.com/news-and-insights/day-of-the-seafarer-2026/"}, {"code": "SMGR", "title": "Anglo-Eastern Technical Summit 2026: shared learning, stronger standards", "src": "Anglo-Eastern", "date": "2026-06-11", "kSum": "앵글로-이스턴(Anglo-Eastern)이 제1회 기술 서밋(Anglo-Eastern Technical Summit)을 개최했다. 전 조직의 고위 리더와 기술 전문가가 모여 학습 내용을 공유하고 기술 표준을 강화하는 자리로 마련됐다.", "eSum": "The inaugural Anglo-Eastern Technical Summit brought together senior leaders and technical experts from across the organisation to share learning and strengthen technical standards fleet-wide.", "kImp": "다국적 선박관리사가 분산된 기술 노하우를 조직 차원에서 표준화하는 시도로, 선대 전반의 기술관리 품질 편차를 줄이는 방법론으로 참고할 만하다. 기술팀 역량 내재화 사례다.", "eImp": "An example of a multinational ship manager standardising dispersed technical know-how at organisational level — a useful reference for reducing quality variance in technical management across a fleet.", "url": "https://www.angloeastern.com/news-and-insights/anglo-eastern-technical-summit-2026-shared-learning-stronger-standards/"}, {"code": "SMGR", "title": "Anglo-Eastern further strengthens Greece presence with refreshed leadership commitment", "src": "Anglo-Eastern", "date": "2026-05-19", "kSum": "앵글로-이스턴 유니밴 그룹(Anglo-Eastern Univan Group)이 그리스 사업 기반을 강화했다. 세계 주요 해운 시장 중 하나인 그리스에 대한 장기적 의지의 일환으로 현지 리더십을 재정비했다.", "eSum": "Anglo-Eastern Univan Group has strengthened its presence in Greece with a refreshed leadership commitment, as part of its long-term commitment to one of the world's most prominent and competitive shipping markets.", "kImp": "그리스는 세계 최대 선주 집중 시장으로, 선박관리사의 현지 거점 강화는 신규 선대 수주 경쟁력과 직결된다. 지역 밀착형 조직 운영이 관리 계약 확보의 핵심 요소임을 보여준다.", "eImp": "Greece is the world's largest concentration of shipowners, so strengthening a local base directly affects a manager's ability to win new tonnage. Illustrates that local presence is a core factor in securing management contracts.", "url": "https://www.angloeastern.com/news-and-insights/anglo-eastern-further-strengthens-its-greece-presence-with-refreshed-leadership-commitment/"}, {"code": "SMGR", "title": "Anglo-Eastern examines offshore wind workforce trends driving salaries, retention and crewing", "src": "Anglo-Eastern", "date": "2026-07-08", "kSum": "앵글로-이스턴(Anglo-Eastern)이 해상풍력 부문의 인력 동향 분석을 공개했다. 해상풍력은 해사 산업 내에서 가장 빠르게 성장하는 분야 중 하나로 부각되고 있으며, 임금·유지율·승무 전략을 좌우하는 요인을 다뤘다.", "eSum": "Anglo-Eastern published an analysis of offshore wind workforce trends, noting the offshore wind segment continues to stand out as one of the fastest-growing areas within the maritime industry, and examining what is driving salaries, retention and crewing strategies.", "kImp": "해상풍력 부문의 인력 경쟁이 전통 상선 선원 시장의 임금과 유지율에 파급 효과를 미치고 있다. 선박관리사는 인접 부문의 임금 인상 압력을 선원 확보 전략에 선제적으로 반영할 필요가 있다.", "eImp": "Competition for offshore wind personnel spills over into wage and retention pressure in the conventional merchant crew market. Ship managers need to factor adjacent-sector pay escalation into their crewing strategy.", "url": "https://www.angloeastern.com/news-and-insights/offshore-wind-workforce-trends-whats-driving-salaries-retention-and-crewing-strategies/"}, {"code": "SMGR", "title": "Columbia Group nears 100 managed Greek vessels", "src": "The Manila Times", "date": "2026-06-10", "kSum": "컬럼비아 그룹(Columbia Group)의 그리스 현지 관리 선대가 100척에 근접했다고 경영진이 밝혔다. 안드레아스 하지페트루(Andreas Hadjipetrou) CEO는 아테네 소재 자회사 컬럼비아 십매니지먼트 그리스(CSM Greece)를 통한 현지 선주와의 관계 심화를 강조했다. 포시도니아(Posidonia) 2026 개막을 앞두고 350명 이상의 해운 임원·고객·파트너가 모인 네트워킹 행사에서 발표됐다.", "eSum": "Columbia Group's fleet under local Greek management has climbed to nearly 100 vessels, executives said at an Athens networking gala attended by more than 350 maritime executives, clients and partners ahead of Posidonia 2026. CEO Andreas Hadjipetrou emphasised deepening ties with local shipowners through Athens-based subsidiary Columbia Shipmanagement (CSM) Greece.", "kImp": "그리스 시장에서 100척 규모 선대 확보는 제3자 선박관리사의 지역 거점 전략이 실적으로 이어진 사례다. 경쟁 관리사의 그리스 확장 속도는 시장 점유율 경쟁 구도를 파악하는 지표가 된다.", "eImp": "Reaching a ~100-vessel Greek book shows a third-party manager's regional hub strategy converting into real tonnage. The pace of rivals' Greek expansion is a useful gauge of competitive dynamics in the sector.", "url": "https://www.manilatimes.net/2026/06/10/business/maritime/columbia-group-nears-100-managed-greek-vessels/2361869"}, {"code": "SMGR", "title": "Northern Marine rolls out digital inspection reporting tool following successful pilot", "src": "Cyprus Shipping News", "date": "2026-06-18", "kSum": "스테나 그룹(Stena Group) 계열 노던 마린 매니지먼트(Northern Marine Management)가 카이코 시스템즈(Kaiko Systems)의 디지털 검사 보고 플랫폼을 관리 선대 전반에 도입하기로 했다. 파일럿 성공에 따른 결정으로, 육상 검사팀용 '쇼어 리포트(Shore Reports)' 솔루션부터 적용한다. 파일럿 기간 중 검사 보고서 작성 소요 시간이 단축되는 성과를 확인했다.", "eSum": "Northern Marine Management, part of the Stena Group, will roll out Kaiko Systems' digital inspection reporting platform across its managed fleet after a successful pilot, starting with the Shore Reports solution for shore-based inspection teams. During the pilot Northern Marine saw a reduction in the time required to complete inspection reports while maintaining consistent, structured output.", "kImp": "검사 보고 워크플로우는 감독(superintendent)의 행정 시간이 가장 많이 소모되는 영역으로, 측정 가능한 디지털화 성과가 확인된 사례다. 파일럿 후 선대 확대라는 단계적 도입 방식은 디지털 툴 도입 시 참고할 만한 접근법이다.", "eImp": "A concrete, measurable digitalisation win in the inspection workflow — the area where superintendents lose the most administrative time. Demonstrates the pilot-then-scale approach for onboarding digital tools across a managed fleet.", "url": "https://cyprusshippingnews.com/2026/06/18/northern-marine-rolls-out-digital-inspection-reporting-tool-following-successful-pilot/"}, {"code": "SMGR", "title": "Fleet Management champions 'silent' seafarers navigating rising geopolitical tensions", "src": "The Manila Times", "date": "2026-06-25", "kSum": "플리트 매니지먼트(Fleet Management Limited)가 선원의 날을 맞아 지정학적 긴장 속에서 묵묵히 일하는 선원들을 조명했다. 회사는 전 세계 약 2만 명의 민간 선원이 매일 지정학적 위험을 감수하고 있으며, 이 중 약 600명이 자사 관리 하에 있다고 밝혔다. 카라벨 그룹(The Caravel Group) 계열인 플리트는 600척 이상을 관리한다.", "eSum": "Fleet Management Limited used Day of the Seafarer to highlight the 'silent' seafarers working through rising geopolitical tensions, noting that an estimated 20,000 civilian seafarers — including around 600 under Fleet's care — bear the risks of geopolitical disruption daily. Fleet, part of The Caravel Group, manages more than 600 vessels.", "kImp": "지정학적 위험 노출 선원 규모를 구체적 수치로 공개한 것은 관리사의 위험 관리 투명성 사례다. 선원 복지 커뮤니케이션이 채용·유지 경쟁력의 일부가 되고 있음을 보여준다.", "eImp": "Publishing concrete numbers on crew exposure to geopolitical risk is an example of transparency in a manager's risk communication, and shows how seafarer welfare messaging is becoming part of recruitment and retention competitiveness.", "url": "https://www.manilatimes.net/2026/06/25/tmt-newswire/media-outreach-newswire/fleet-management-champions-silent-seafarers-navigating-rising-geopolitical-tensions/2372568"}, {"code": "SMGR", "title": "Bernhard Schulte Offshore takes delivery of fourth CSOV in newbuild series", "src": "OffshoreWind.biz", "date": "2026-07-03", "kSum": "베른하르트 슐테 오프쇼어(Bernhard Schulte Offshore, BSM 계열)가 신조 시리즈의 네 번째 CSOV(Commissioning Service Operation Vessel) '윈데아 클라크(Windea Clarke)'를 인도받았다. 이로써 4척 신조 시리즈가 완성됐다. 앞서 자매선 '윈데아 퀴리(Windea Curie)'는 6월 26일 명명식을 가졌으며 EU 해상 송전 사업자 테넷(TenneT)에 투입돼 북해 해상 계통연계 설비를 지원한다.", "eSum": "Bernhard Schulte Offshore, part of the Bernhard Schulte group, took delivery of Windea Clarke, the fourth and final CSOV in its newbuild series. Sister vessel Windea Curie was christened on 26 June and is deployed for EU offshore transmission system operator TenneT to support offshore grid connection facilities in the North Sea.", "kImp": "BSM 그룹이 해상풍력 지원선 부문에 4척 신조 시리즈로 대규모 투자를 완료한 것은 선박관리사의 사업 다각화 방향을 보여준다. 상선 관리 수익 변동성을 오프쇼어 에너지 부문으로 헤지하는 전략이다.", "eImp": "Completing a four-vessel CSOV newbuild programme shows how the Bernhard Schulte group is diversifying into offshore wind support — a strategy of hedging merchant-management earnings volatility with offshore energy exposure.", "url": "https://www.offshorewind.biz/2026/07/03/bernhard-schulte-offshore-takes-delivery-of-fourth-csov-in-newbuild-series/"}, {"code": "SMGR", "title": "Anglo-Eastern: seeing below the surface — how GoPro is changing hull inspections", "src": "Anglo-Eastern", "date": "2026-06-02", "kSum": "앵글로-이스턴(Anglo-Eastern)이 고프로(GoPro) 카메라를 활용한 선체 검사 방식을 소개했다. 해운에서 눈에 보이는 것이 곧 조치로 이어지지만, 정작 가장 중요한 부분은 수면 아래에 있어 확인이 어렵다는 문제의식에서 출발했다.", "eSum": "Anglo-Eastern described how it is using GoPro cameras to change hull inspections, noting that in shipping what we see often shapes what we do, yet some of the most important areas lie below the waterline and go unseen.", "kImp": "고가의 전용 장비 대신 범용 카메라를 활용해 선체 상태를 시각화한 저비용 실용 사례다. 수중 선체 오손(fouling) 상태 파악은 연료 효율·CII 관리와 직결되므로 기술팀이 즉시 응용할 수 있다.", "eImp": "A low-cost, practical case of using off-the-shelf cameras rather than dedicated survey equipment to visualise hull condition. Since underwater fouling assessment feeds directly into fuel efficiency and CII management, it is immediately applicable for technical teams.", "url": "https://www.angloeastern.com/news-and-insights/seeing-below-the-surface-how-gopro-is-changing-hull-inspections/"}, {"code": "SMGR", "title": "Anglo-Eastern reinforces fleet security through its Global Security Desk as Hormuz disruption continues", "src": "Anglo-Eastern", "date": "2026-05-27", "kSum": "앵글로-이스턴 유니밴 그룹(Anglo-Eastern Univan Group)이 호르무즈 해협(Strait of Hormuz) 혼란이 지속되는 가운데 글로벌 시큐리티 데스크(Global Security Desk)를 중심으로 선대 보안을 강화했다. 독립 선박관리 부문의 글로벌 리더로서 중앙집중형 보안 관리 역량을 활용하고 있다.", "eSum": "Anglo-Eastern Univan Group, a global leader in independent ship management services, is drawing on its Global Security Desk to reinforce fleet security as disruption around the Strait of Hormuz continues.", "kImp": "고위험 해역 통항이 일상화된 환경에서 중앙집중형 보안 데스크를 운영하는 것은 선박관리사의 필수 역량이 되고 있다. 선주·용선자에 대한 위험 정보 제공과 선원 안전 확보를 동시에 달성하는 구조를 보여준다.", "eImp": "With transits through high-risk areas now routine, running a centralised security desk is becoming a baseline capability for ship managers. It shows a structure that simultaneously delivers risk intelligence to owners/charterers and protects crew.", "url": "https://www.angloeastern.com/news-and-insights/anglo-eastern-reinforces-fleet-security-through-its-global-security-desk-as-hormuz-disruption-continues/"}]}]};